  box-shadow: 0 10px 40px rgba(0,0,0,.35);
}
#hud::after { content: ''; position: absolute; left: 0; right: 0; bottom: -5px; height: 4px;
  background: linear-gradient(90deg, transparent, rgba(201,161,92,.25) 18%, rgba(201,161,92,.08) 50%, rgba(201,161,92,.25) 82%, transparent); }
.brand { display: flex; align-items: center; gap: 11px; min-width: 246px; }
