.brand-copy h1 { font-family: var(--serif); font-weight: 500; font-size: 21px; letter-spacing: .19em; margin: 0 0 2px; background: linear-gradient(180deg, #f2dfb8, #bd9552); -webkit-background-clip: text; background-clip: text; color: transparent; }
.brand-copy span { display: block; color: var(--parch-dim); font-size: 8.5px; letter-spacing: .28em; text-transform: uppercase; }

.chrono { min-width: 188px; padding-left: 20px; border-left: 1px solid var(--line); position: relative; }
.chrono-date { display: flex; align-items: center; gap: 7px; color: var(--parch-dim); font-size: 9px; letter-spacing: .13em; text-transform: uppercase; }
.chrono-date i { display: block; width: 2px; height: 2px; border-radius: 50%; background: var(--gold); }
.chrono-time { display: flex; align-items: baseline; gap: 9px; margin-top: 2px; }
.chrono-time #time-label { font-family: var(--serif); font-size: 21px; letter-spacing: .05em; color: var(--parch); }
.chrono-time b { font-size: 8px; letter-spacing: .17em; color: var(--gold); font-weight: 500; text-transform: uppercase; }
.sun-track { position: relative; height: 2px; margin-top: 5px; background: linear-gradient(90deg, rgba(201,161,92,.1), rgba(201,161,92,.3), rgba(201,161,92,.1)); }
.sun-track::before, .sun-track::after { content:''; position:absolute; top:-1px; width:4px; height:4px; border-radius:50%; background: var(--gold-dim); }
.sun-track::before { left: 0; } .sun-track::after { right: 0; }
#sun-dot { position: absolute; top: -3px; width: 8px; height: 8px; border-radius: 50%; background: #e9c987; box-shadow: 0 0 10px #c9a15c; transition: left .3s linear; }
.weather { position: absolute; right: 0; top: 2px; display: flex; align-items: center; gap: 4px; color: var(--parch-dim); font-size: 8px; letter-spacing: .06em; text-transform: uppercase; }
