.resource .res-cap { font-size: 8px; color: var(--parch-dim); letter-spacing: .03em; }
.resource.flash { animation: resFlash .5s; }
@keyframes resFlash { 0% { background: rgba(233,201,135,.24); } 100% { background: rgba(230,212,174,.025); } }
.resource.warn .res-val { color: #df8b70; }

.hud-actions { display: flex; gap: 5px; }
