  width: 30px; height: 30px; display: grid; place-items: center; cursor: pointer;
  border: 1px solid var(--line); background: rgba(230,212,174,.03); color: var(--parch-dim);
  border-radius: 2px; font-size: 13px; transition: .18s;
}
.icon-btn:hover { color: var(--gold-bright); border-color: rgba(201,161,92,.5); background: rgba(201,161,92,.08); }

/* ------------------------------------------------------------- PANELS */
.panel {
  position: absolute; z-index: 15; top: 88px; bottom: 80px;
  background:
    linear-gradient(145deg, rgba(38, 30, 22, .55), transparent 38%),
    linear-gradient(180deg, rgba(23, 18, 13, .95), rgba(16, 13, 10, .93));
