  box-shadow: var(--shadow), inset 0 0 60px rgba(0,0,0,.2);
  backdrop-filter: blur(12px);
  display: flex; flex-direction: column;
}
.panel-corners { position: absolute; inset: 3px; pointer-events: none; z-index: 3; }
.panel-corners::before, .panel-corners::after {
  content: ''; position: absolute; width: 14px; height: 14px; border-color: var(--gold-dim); opacity: .75;
}
.panel-corners::before { left: 0; top: 0; border-left: 1px solid; border-top: 1px solid; }
.panel-corners::after { right: 0; bottom: 0; border-right: 1px solid; border-bottom: 1px solid; }
#left-panel { left: 16px; width: 354px; }
#right-panel { right: 16px; width: 306px; }

.codex-tabs { display: flex; padding: 0 8px; border-bottom: 1px solid var(--line); background: rgba(0,0,0,.18); flex: none; }
.tab {
  flex: 1; border: 0; background: none; cursor: pointer; padding: 12px 2px 10px; position: relative;
  color: #8f8066; font-size: 8.5px; letter-spacing: .09em; text-transform: uppercase; transition: .18s;
}
.tab span { display: block; font-size: 14px; margin-bottom: 3px; color: #695c49; transition: .18s; }
.tab:hover { color: var(--parch); }
.tab.active { color: var(--gold-bright); }
.tab.active span { color: var(--gold); text-shadow: 0 0 12px rgba(201,161,92,.55); }
.tab.active::after { content: ''; position: absolute; bottom: -1px; left: 20%; right: 20%; height: 1px; background: var(--gold); box-shadow: 0 0 8px var(--gold); }

.panel-scroll { overflow-y: auto; overflow-x: hidden; flex: 1; padding: 14px 15px 20px; scrollbar-gutter: stable; }
.panel-footer { flex: none; border-top: 1px solid var(--line-soft); padding: 8px 15px; display: flex; align-items: center; gap: 7px; font-size: 9px; letter-spacing: .06em; color: var(--parch-dim); background: rgba(0,0,0,.16); text-transform: uppercase; }
.live-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--moss); box-shadow: 0 0 7px var(--moss); animation: pulse 2.2s infinite; }
@keyframes pulse { 50% { opacity: .3; } }

/* --------------------------------------------------------- COMPONENTS */
.section-head { display: flex; align-items: center; gap: 8px; margin: 2px 0 10px; }
.section-head h3 { font-family: var(--serif); font-weight: 400; font-size: 14px; letter-spacing: .12em; margin: 0; color: var(--parch); text-transform: uppercase; }
.section-head .rule { flex: 1; height: 1px; background: linear-gradient(90deg, var(--line), transparent); }
.section-head .count { font-size: 8px; color: var(--gold); border: 1px solid var(--line); padding: 2px 5px; border-radius: 10px; letter-spacing: .08em; }
.section-sub { color: var(--parch-dim); font-size: 9.5px; line-height: 1.5; margin: -3px 0 11px; letter-spacing: .02em; }
.micro-label { font-size: 7.5px; letter-spacing: .16em; color: #88785f; text-transform: uppercase; margin-bottom: 5px; }

.colony-banner {
  position: relative; border: 1px solid var(--line); padding: 12px 12px 11px; margin-bottom: 13px;
  background: radial-gradient(ellipse at 20% 0%, rgba(201,161,92,.13), transparent 60%), rgba(0,0,0,.18);
  overflow: hidden;
}
.colony-banner::before { content: ''; position: absolute; right: -30px; top: -30px; width: 110px; height: 110px; border: 1px solid rgba(201,161,92,.12); transform: rotate(45deg); }
.colony-banner h4 { font-family: var(--serif); font-size: 17px; font-weight: 400; margin: 0 0 3px; color: var(--gold-bright); letter-spacing: .05em; }
.colony-banner p { margin: 0; font-size: 9px; line-height: 1.5; color: var(--parch-dim); max-width: 250px; }
.mood-row { display: flex; gap: 9px; align-items: center; margin-top: 12px; }
.mood-orbs { display: flex; gap: 3px; }
.mood-orb { width: 7px; height: 7px; border-radius: 50%; background: #3c352b; }
.mood-orb.on { background: var(--gold); box-shadow: 0 0 6px rgba(201,161,92,.5); }
.mood-score { margin-left: auto; font-family: var(--serif); color: var(--gold-bright); font-size: 14px; }
.mood-caption { font-size: 8px; color: var(--parch-dim); letter-spacing: .08em; text-transform: uppercase; }

.colonist-list { display: flex; flex-direction: column; gap: 5px; }
.colonist-card {
  display: grid; grid-template-columns: 36px 1fr auto; align-items: center; gap: 9px; width: 100%;
  text-align: left; border: 1px solid transparent; background: rgba(230,212,174,.025); padding: 7px 8px;
  cursor: pointer; transition: .16s; position: relative;
}
.colonist-card:hover { background: rgba(230,212,174,.06); border-color: var(--line-soft); }
.colonist-card.selected { border-color: rgba(201,161,92,.48); background: linear-gradient(90deg, rgba(201,161,92,.12), rgba(201,161,92,.02)); }
.colonist-card.selected::before { content:''; position:absolute; left:-1px; top:6px; bottom:6px; width:2px; background: var(--gold); box-shadow:0 0 8px var(--gold); }
.avatar {
  width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; position: relative;
  font-family: var(--serif); font-size: 14px; color: #f0dcb4;
  border: 1px solid rgba(230,212,174,.22); box-shadow: inset 0 0 13px rgba(0,0,0,.6);
}
.avatar .status-pip { position: absolute; right: -1px; bottom: -1px; width: 8px; height: 8px; border-radius: 50%; border: 1px solid #16120e; background: var(--moss); }
.avatar .status-pip.bad { background: #b35243; } .avatar .status-pip.warn { background: #c5934c; }
.colonist-card .c-name { font-family: var(--serif); font-size: 12.5px; color: var(--parch); line-height: 1.2; }
.colonist-card .c-meta { font-size: 8px; color: var(--parch-dim); margin-top: 3px; letter-spacing: .05em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.colonist-card .c-job { font-size: 8px; color: var(--gold); text-align: right; letter-spacing: .04em; text-transform: uppercase; max-width: 76px; }
.need-bars { display: flex; gap: 2px; margin-top: 4px; }
.need-bars i { height: 2px; flex: 1; background: rgba(255,255,255,.08); position: relative; overflow: hidden; }
.need-bars i b { position: absolute; inset: 0 auto 0 0; background: var(--moss); }
.need-bars i.low b { background: #b35243; }

.stat-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; margin-bottom: 12px; }
.stat-card { border: 1px solid var(--line-soft); background: rgba(0,0,0,.16); padding: 7px 8px; }
.stat-card .v { font-family: var(--serif); color: var(--parch); font-size: 16px; line-height: 1; }
.stat-card .k { font-size: 7px; letter-spacing: .11em; color: var(--parch-dim); margin-top: 3px; text-transform: uppercase; }

/* work matrix */
.work-scroll { margin: 0 -6px; overflow-x: auto; border: 1px solid var(--line-soft); }
.work-table { border-collapse: collapse; width: 100%; min-width: 315px; }
.work-table th { font-size: 7px; font-weight: 500; color: #8d7d63; text-transform: uppercase; letter-spacing: .06em; padding: 6px 2px; border-bottom: 1px solid var(--line); background: rgba(0,0,0,.22); }
.work-table th:first-child { text-align: left; padding-left: 7px; position: sticky; left: 0; background: #1c1711; z-index: 2; }
.work-table td { font-size: 8px; text-align: center; border-bottom: 1px solid rgba(230,212,174,.04); }
.work-table td:first-child { text-align: left; padding: 5px 7px; color: var(--parch-dim); letter-spacing: .02em; position: sticky; left: 0; background: #19140f; z-index: 1; white-space: nowrap; }
.work-table tr:hover td { background: rgba(230,212,174,.035); }
.prio { width: 22px; height: 18px; border: 0; cursor: pointer; background: transparent; color: #655a48; font-size: 9px; border-radius: 1px; transition: .14s; }
.prio:hover { background: rgba(201,161,92,.12); }
.prio.p1 { color: #e9c987; background: rgba(201,161,92,.15); font-weight: 600; }
.prio.p2 { color: #b6a483; background: rgba(230,212,174,.06); }
.prio.p3 { color: #7c705b; }
.prio.p4 { color: #433b30; }
.work-legend { display: flex; gap: 8px; margin-top: 6px; color: #7d6f59; font-size: 7px; letter-spacing: .07em; text-transform: uppercase; }
.work-legend b { color: var(--gold); font-weight: 500; }

/* build */
.build-toolbar { display: flex; gap: 4px; flex-wrap: wrap; margin-bottom: 9px; }
.chip-btn { border: 1px solid var(--line-soft); background: rgba(0,0,0,.14); color: var(--parch-dim); font-size: 7.5px; letter-spacing: .08em; padding: 4px 7px; cursor: pointer; text-transform: uppercase; }
.chip-btn.active { color: var(--gold-bright); border-color: rgba(201,161,92,.48); background: rgba(201,161,92,.08); }
.build-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.build-card { border: 1px solid var(--line-soft); background: rgba(0,0,0,.16); padding: 7px; cursor: pointer; text-align: left; transition: .16s; position: relative; overflow: hidden; }
.build-card:hover { border-color: rgba(201,161,92,.42); background: rgba(201,161,92,.05); transform: translateY(-1px); }
.build-card.locked { opacity: .42; cursor: not-allowed; }
.build-card.active { border-color: var(--gold); background: rgba(201,161,92,.1); }
.build-card .b-icon { font-size: 17px; color: var(--gold); height: 21px; display: block; }
.build-card .b-name { font-family: var(--serif); font-size: 10.5px; color: var(--parch); margin-top: 2px; }
.build-card .b-cost { display: flex; gap: 6px; margin-top: 4px; font-size: 7.5px; color: var(--parch-dim); }
.build-card .b-cost span.lack { color: #c36c58; }
.build-card .b-lock { font-size: 7px; color: var(--gold); margin-top: 3px; letter-spacing: .04em; }
.build-card .b-key { position: absolute; right: 5px; top: 5px; font-size: 6.5px; border: 1px solid var(--line-soft); color: var(--parch-dim); padding: 1px 3px; }

/* research */
.research-points { display: flex; align-items: baseline; gap: 8px; margin-bottom: 10px; }
.research-points b { font-family: var(--serif); font-size: 26px; color: var(--gold-bright); font-weight: 400; line-height: 1; }
.research-points span { font-size: 8px; color: var(--parch-dim); letter-spacing: .12em; text-transform: uppercase; }
.research-card { border: 1px solid var(--line-soft); background: rgba(0,0,0,.15); padding: 9px; margin-bottom: 6px; cursor: pointer; position: relative; overflow: hidden; transition: .16s; }
.research-card:hover { border-color: rgba(201,161,92,.38); }
.research-card.active { border-color: rgba(201,161,92,.52); background: rgba(201,161,92,.06); }
.research-card.done { opacity: .72; }
.research-card.locked { opacity: .4; cursor: not-allowed; }
.research-card h4 { margin: 0 0 3px; font-family: var(--serif); font-weight: 400; font-size: 12px; color: var(--parch); display: flex; gap: 6px; align-items: center; }
.research-card h4 .r-icon { color: var(--gold); font-size: 12px; }
.research-card p { margin: 0; font-size: 8.5px; line-height: 1.45; color: var(--parch-dim); padding-right: 20px; }
.research-card .r-meta { display: flex; justify-content: space-between; margin-top: 6px; font-size: 7px; letter-spacing: .08em; color: #8f7f65; text-transform: uppercase; }
.research-card .r-prog { height: 2px; background: rgba(255,255,255,.07); margin-top: 5px; }
.research-card .r-prog i { display: block; height: 100%; background: linear-gradient(90deg, var(--gold-dim), var(--gold-bright)); box-shadow: 0 0 5px var(--gold); }
.research-card .done-mark { position: absolute; right: 8px; top: 8px; color: var(--moss); font-size: 12px; }

/* world / quests */
.quest-card { border: 1px solid rgba(201,161,92,.22); border-left: 2px solid var(--gold); background: linear-gradient(90deg, rgba(201,161,92,.06), transparent); padding: 9px 10px; margin-bottom: 7px; }
.quest-card.done { border-left-color: var(--moss); opacity: .7; }
.quest-card h4 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: 12.5px; color: var(--gold-bright); }
.quest-card p { margin: 4px 0 0; font-size: 8.5px; color: var(--parch-dim); line-height: 1.45; }
.quest-card .q-obj { font-size: 7.5px; color: #9c8b70; margin-top: 6px; display: flex; justify-content: space-between; }
.quest-card .q-obj b { color: var(--parch); font-weight: 400; }
.world-actions { display: flex; flex-direction: column; gap: 4px; }
.world-action { display: flex; justify-content: space-between; align-items: center; border: 1px solid var(--line-soft); background: rgba(0,0,0,.15); padding: 7px 9px; cursor: pointer; transition: .15s; }
.world-action:hover { border-color: var(--line); background: rgba(201,161,92,.05); }
.world-action .wa-name { font-family: var(--serif); font-size: 10.5px; color: var(--parch); }
.world-action .wa-sub { font-size: 7.5px; color: var(--parch-dim); margin-top: 2px; }
.world-action .wa-cost { font-size: 7px; color: var(--gold); letter-spacing: .05em; }

.log-list { display: flex; flex-direction: column; gap: 0; }
.log-entry { display: grid; grid-template-columns: 42px 12px 1fr; gap: 6px; padding: 6px 0; border-bottom: 1px solid rgba(230,212,174,.045); font-size: 8.5px; line-height: 1.4; color: var(--parch-dim); }
.log-entry .lt { color: #6f634f; font-size: 7.5px; letter-spacing: .03em; padding-top: 1px; }
.log-entry .ld { color: var(--gold-dim); font-size: 8px; }
.log-entry.good .ld { color: var(--moss); } .log-entry.bad .ld { color: var(--blood); } .log-entry.epic .ld { color: var(--gold-bright); }
.log-entry strong { color: var(--parch); font-weight: 500; }

/* ------------------------------- right panel / inspector */
#right-content { padding-left: 13px; padding-right: 13px; }
.inspector-head { display: flex; gap: 10px; align-items: center; border-bottom: 1px solid var(--line); padding-bottom: 12px; margin-bottom: 12px; }
.inspector-head .avatar { width: 54px; height: 54px; font-size: 19px; }
.inspector-head h3 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: 17px; color: var(--parch); line-height: 1.1; }
.inspector-head .sub { margin-top: 3px; font-size: 8px; letter-spacing: .09em; color: var(--gold); text-transform: uppercase; }
.inspector-tags { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 5px; }
.tag { border: 1px solid var(--line-soft); padding: 2px 5px; font-size: 6.5px; letter-spacing: .05em; color: var(--parch-dim); text-transform: uppercase; }
.tag.good { color: #9eb080; border-color: rgba(115,130,90,.4); }
.tag.bad { color: #c77d6b; border-color: rgba(154,65,52,.4); }

.vitals { display: flex; flex-direction: column; gap: 8px; margin-bottom: 12px; }
.vital-row { display: grid; grid-template-columns: 38px 1fr 30px; align-items: center; gap: 7px; }
.vital-row .vk { font-size: 7.5px; letter-spacing: .1em; color: var(--parch-dim); text-transform: uppercase; }
.vital-row .vbar { height: 5px; background: rgba(255,255,255,.07); position: relative; overflow: hidden; border-radius: 1px; }
.vital-row .vbar i { display: block; height: 100%; background: linear-gradient(90deg, #657554, #94a875); transition: width .4s; }
.vital-row .vbar.hunger i { background: linear-gradient(90deg, #8b653c, #c9a15c); }
.vital-row .vbar.rest i { background: linear-gradient(90deg, #496575, #7a9da3); }
.vital-row .vbar.mood i { background: linear-gradient(90deg, #8a6b64, #c9a15c); }
.vital-row .vv { text-align: right; font-family: var(--serif); font-size: 11px; color: var(--parch); }
.vital-row .vbar.low i { background: linear-gradient(90deg, #6e2a22, #b35243); }

.skill-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 3px 10px; margin-bottom: 12px; }
.skill-row { display: flex; align-items: center; gap: 5px; }
.skill-row span { font-size: 8px; color: var(--parch-dim); width: 52px; }
.skill-row .pips { display: flex; gap: 2px; flex: 1; }
.skill-row .pips i { width: 5px; height: 5px; background: #3a3329; transform: rotate(45deg); }
.skill-row .pips i.on { background: var(--gold); box-shadow: 0 0 3px rgba(201,161,92,.4); }
.skill-row b { font-size: 8px; color: var(--parch); font-weight: 500; width: 10px; text-align: right; }

.trait-line { font-size: 8.5px; color: var(--parch-dim); line-height: 1.45; margin-bottom: 10px; padding: 7px 8px; border-left: 1px solid var(--gold-dim); background: rgba(0,0,0,.13); }
.trait-line b { color: var(--gold); font-weight: 400; }

.inspector-section { margin-top: 12px; }
.standing-orders { display: flex; flex-direction: column; gap: 3px; }
.order-btn { border: 1px solid var(--line-soft); background: rgba(0,0,0,.15); padding: 6px 8px; display: flex; justify-content: space-between; font-size: 8px; color: var(--parch-dim); cursor: pointer; }
.order-btn:hover { border-color: var(--line); color: var(--parch); }
.order-btn b { color: var(--gold); font-weight: 500; font-size: 7px; letter-spacing: .05em; }

.empty-inspector { text-align: center; padding: 16px 8px 10px; }
.empty-inspector .glyph { font-size: 28px; color: var(--gold-dim); margin-bottom: 8px; }
.empty-inspector h3 { font-family: var(--serif); font-weight: 400; font-size: 15px; margin: 0 0 5px; color: var(--parch); }
.empty-inspector p { font-size: 8.5px; line-height: 1.5; color: var(--parch-dim); margin: 0 auto; max-width: 210px; }

.colony-meters { display: flex; flex-direction: column; gap: 6px; margin: 12px 0; }
.colony-meter { display: grid; grid-template-columns: 58px 1fr 32px; gap: 7px; align-items: center; font-size: 7.5px; color: var(--parch-dim); text-transform: uppercase; letter-spacing: .07em; }
.colony-meter .cm-bar { height: 4px; background: rgba(255,255,255,.07); }
.colony-meter .cm-bar i { display: block; height: 100%; background: var(--moss); }
.colony-meter b { font-family: var(--serif); color: var(--parch); font-size: 10px; font-weight: 400; text-align: right; }

.building-actions { display: flex; gap: 4px; flex-wrap: wrap; margin-top: 10px; }
.panel-btn { border: 1px solid var(--line); background: rgba(201,161,92,.07); color: var(--gold-bright); font-size: 7.5px; letter-spacing: .08em; padding: 6px 9px; cursor: pointer; text-transform: uppercase; }
.panel-btn:hover { background: rgba(201,161,92,.15); }
.panel-btn.danger { border-color: rgba(154,65,52,.45); color: #d39080; background: rgba(154,65,52,.08); }
.panel-btn.full { width: 100%; }

/* ------------------------------------------------ bottom */
#bottom-bar { position: absolute; z-index: 18; bottom: 0; left: 0; right: 0; height: 60px; display: flex; align-items: center; gap: 16px; padding: 0 20px; background: linear-gradient(0deg, rgba(12,9,7,.97), rgba(14,11,8,.8) 70%, transparent); border-top: 1px solid rgba(201,161,92,.12); }
.speed-cluster { display: flex; border: 1px solid var(--line); background: rgba(0,0,0,.3); flex: none; }
.speed-btn { width: 32px; height: 28px; border: 0; background: transparent; color: #7c6f5a; cursor: pointer; font-size: 7px; letter-spacing: -1px; transition: .15s; }
.speed-btn:hover { color: var(--parch); background: rgba(201,161,92,.08); }
.speed-btn.active { color: var(--gold-bright); background: rgba(201,161,92,.14); box-shadow: inset 0 -1px var(--gold); }
.alert-ribbon { flex: 1; display: flex; align-items: center; gap: 8px; min-width: 0; font-size: 9.5px; color: var(--parch-dim); letter-spacing: .025em; }
.alert-ribbon .alert-icon { color: var(--gold); font-size: 11px; }
#alert-text { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bottom-stats { display: flex; gap: 14px; font-size: 7.5px; color: #8b7c63; letter-spacing: .07em; text-transform: uppercase; white-space: nowrap; }
.bottom-stats b { color: var(--parch); font-weight: 400; }

/* ------------------------------------------------------- toast & banner */
#toast-stack { position: absolute; z-index: 40; top: 88px; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; gap: 5px; width: min(400px, 58vw); pointer-events: none; }
.toast { background: linear-gradient(90deg, rgba(28,22,16,.97), rgba(22,18,13,.94)); border: 1px solid var(--line); border-left: 2px solid var(--gold); padding: 8px 13px; box-shadow: 0 8px 28px rgba(0,0,0,.45); font-size: 9px; color: var(--parch-dim); animation: toastIn .25s ease-out; line-height: 1.4; }
.toast strong { color: var(--parch); font-weight: 500; font-family: var(--serif); font-size: 10px; }
.toast.bad { border-left-color: var(--blood); }
.toast.good { border-left-color: var(--moss); }
.toast.epic { border-left-color: var(--gold-bright); background: linear-gradient(90deg, rgba(48,37,23,.98), rgba(25,20,14,.95)); }
.toast.out { animation: toastOut .3s forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-7px); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-7px); } }

#event-banner { position: absolute; z-index: 35; top: 94px; left: 50%; transform: translateX(-50%); width: min(500px, 70vw); padding: 13px 18px 14px; text-align: center; background: linear-gradient(90deg, transparent, rgba(32,24,16,.97) 18%, rgba(41,31,19,.98) 50%, rgba(32,24,16,.97) 82%, transparent); border-top: 1px solid rgba(201,161,92,.4); border-bottom: 1px solid rgba(201,161,92,.4); animation: bannerIn .5s ease-out; pointer-events: none; }
#event-banner .eb-kicker { font-size: 7px; letter-spacing: .26em; color: var(--gold); text-transform: uppercase; }
#event-banner h3 { font-family: var(--serif); font-weight: 400; font-size: 21px; letter-spacing: .06em; color: var(--gold-bright); margin: 4px 0 3px; }
#event-banner p { margin: 0; font-size: 9px; color: var(--parch-dim); line-height: 1.45; }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, -10px); } }

#tooltip { position: absolute; z-index: 60; pointer-events: none; background: rgba(18,14,10,.97); border: 1px solid var(--line); padding: 5px 8px; font-size: 8px; color: var(--parch); max-width: 220px; line-height: 1.4; box-shadow: 0 6px 20px rgba(0,0,0,.4); }
#tooltip b { color: var(--gold); font-weight: 400; }

/* ------------------------------------------------------ start screen */
#start-screen {
  position: absolute; inset: 0; z-index: 90; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center;
  background:
    radial-gradient(ellipse at 50% 42%, rgba(78,61,38,.36), transparent 50%),
    radial-gradient(ellipse at 50% 110%, rgba(13,30,25,.45), transparent 55%),
    linear-gradient(180deg, #0a0907 0%, #15110c 50%, #090806 100%);
  transition: opacity .8s ease, visibility .8s;
}
#start-screen::before {
  content: ''; position: absolute; inset: 0; opacity: .16;
  background-image: url("data:image/svg+xml,%3Csvg width='120' height='120' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.62' numOctaves='4'/%3E%3C/filter%3E%3Crect width='120' height='120' filter='url(%23n)' opacity='.72'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}
#start-screen::after { content: ''; position: absolute; inset: 22px; border: 1px solid rgba(201,161,92,.13); pointer-events: none; }
#start-screen.dismiss { opacity: 0; visibility: hidden; }
.start-fog { position: absolute; width: 70vw; height: 50vh; border-radius: 50%; filter: blur(60px); opacity: .16; pointer-events: none; }
.fog-a { background: #7d623c; left: -15%; bottom: -20%; animation: fog 18s ease-in-out infinite alternate; }
.fog-b { background: #2f5549; right: -15%; top: -20%; animation: fog 24s ease-in-out infinite alternate-reverse; }
@keyframes fog { to { transform: translate(9vw, 4vh) scale(1.2); } }
.start-crest { width: 98px; height: 98px; color: var(--gold); filter: drop-shadow(0 0 26px rgba(201,161,92,.28)); margin-bottom: 4px; opacity: .92; }
.start-crest svg { width: 100%; height: 100%; }
.eyebrow { font-size: 8.5px; letter-spacing: .34em; color: var(--parch-dim); text-transform: uppercase; margin: 10px 0 0; }
#start-screen h2 { font-family: var(--serif); font-weight: 400; font-size: clamp(54px, 8.5vw, 102px); letter-spacing: .13em; line-height: .98; margin: 12px 0 11px; background: linear-gradient(180deg, #f7e7c3 10%, #cba25c 54%, #8a6a37 100%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 13px 32px rgba(0,0,0,.7)); }
.start-sub { font-family: var(--serif); font-style: italic; font-size: 15px; color: #bfae8d; letter-spacing: .03em; margin: 0; max-width: 640px; padding: 0 18px; }
.start-rule { display: flex; align-items: center; gap: 11px; color: var(--gold-dim); font-size: 9px; margin: 20px 0 16px; width: 330px; }
.start-rule span { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(201,161,92,.45)); }
.start-rule span:last-child { background: linear-gradient(90deg, rgba(201,161,92,.45), transparent); }
.start-blurb { font-size: 10px; line-height: 1.7; color: #8e816b; margin: 0; letter-spacing: .04em; }
.start-btn { margin-top: 26px; position: relative; cursor: pointer; border: 1px solid rgba(201,161,92,.55); background: linear-gradient(180deg, rgba(201,161,92,.15), rgba(201,161,92,.04)); padding: 12px 42px 10px; min-width: 220px; transition: .25s; box-shadow: 0 0 0 4px rgba(201,161,92,.035), 0 12px 35px rgba(0,0,0,.35); }
.start-btn span { display: block; font-family: var(--serif); font-size: 16px; letter-spacing: .16em; color: var(--gold-bright); text-transform: uppercase; }
.start-btn small { display: block; font-size: 7px; letter-spacing: .2em; text-transform: uppercase; color: #8d7c61; margin-top: 4px; }
.start-btn:hover { background: linear-gradient(180deg, rgba(201,161,92,.26), rgba(201,161,92,.08)); border-color: var(--gold-bright); transform: translateY(-2px); box-shadow: 0 0 0 5px rgba(201,161,92,.06), 0 17px 45px rgba(0,0,0,.45); }
.start-features { display: flex; gap: 23px; margin-top: 26px; font-size: 7.5px; letter-spacing: .13em; text-transform: uppercase; color: #6d614e; flex-wrap: wrap; justify-content: center; padding: 0 20px; }
.start-features span { color: #8b7b62; }
.start-foot { position: absolute; bottom: 31px; margin: 0; font-size: 7px; letter-spacing: .18em; color: #514738; text-transform: uppercase; }

/* -------------------------------------------------------------- modal */
#modal-layer { position: absolute; inset: 0; z-index: 80; background: rgba(6,5,4,.74); display: grid; place-items: center; backdrop-filter: blur(4px); }
.modal { width: min(590px, 90vw); max-height: 82vh; overflow-y: auto; position: relative; background: linear-gradient(160deg, #241c14, #15110d 70%); border: 1px solid var(--line); box-shadow: var(--shadow); padding: 26px 28px; }
.modal::before { content: ''; position: absolute; inset: 5px; border: 1px solid rgba(201,161,92,.09); pointer-events: none; }
.modal-close { position: absolute; right: 9px; top: 8px; border: 0; background: none; color: #8e7e64; cursor: pointer; font-size: 20px; line-height: 1; padding: 4px 8px; }
.modal-close:hover { color: var(--gold-bright); }
.modal .m-kicker { font-size: 7.5px; letter-spacing: .24em; color: var(--gold); text-transform: uppercase; }
.modal h2 { font-family: var(--serif); font-weight: 400; font-size: 27px; color: var(--gold-bright); margin: 5px 0 7px; letter-spacing: .04em; }
.modal p { font-size: 10px; line-height: 1.65; color: var(--parch-dim); }
.modal .rules { display: grid; grid-template-columns: 1fr 1fr; gap: 9px 18px; margin-top: 14px; }
.modal .rule { font-size: 8.5px; color: var(--parch-dim); line-height: 1.5; padding-left: 10px; border-left: 1px solid var(--gold-dim); }
.modal .rule b { display: block; color: var(--parch); font-weight: 500; font-family: var(--serif); font-size: 10.5px; margin-bottom: 2px; }
.modal .m-actions { display: flex; gap: 7px; flex-wrap: wrap; margin-top: 19px; }
.modal .m-actions button { cursor: pointer; border: 1px solid var(--line); background: rgba(201,161,92,.08); color: var(--gold-bright); padding: 7px 14px; font-size: 8px; letter-spacing: .1em; text-transform: uppercase; }
.modal .m-actions button:hover { background: rgba(201,161,92,.17); }
.modal .m-list { margin: 10px 0 0; padding: 0; list-style: none; }
.modal .m-list li { border-top: 1px solid var(--line-soft); padding: 8px 0; display: flex; justify-content: space-between; gap: 12px; font-size: 9px; color: var(--parch-dim); }
.modal .m-list li b { color: var(--parch); font-weight: 400; font-family: var(--serif); font-size: 10px; }

/* ---------------------------------------------------------- overview */
#overview { position: absolute; z-index: 70; inset: 86px 16px 70px; background: rgba(12,10,8,.96); border: 1px solid var(--line); box-shadow: var(--shadow); flex-direction: column; }
#overview:not(.hidden) { display: flex; }
.overview-head { height: 45px; flex: none; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); padding: 0 15px; font-size: 8px; letter-spacing: .25em; color: var(--gold); }
#overview-close { border: 0; background: none; color: var(--parch-dim); font-size: 20px; cursor: pointer; }
#overview-canvas { flex: 1; width: 100%; min-height: 0; cursor: grab; }
.overview-legend { flex: none; height: 32px; display: grid; place-items: center; font-size: 7px; letter-spacing: .12em; color: #6d614f; text-transform: uppercase; border-top: 1px solid var(--line-soft); }

/* ------------------------------------------------------------ mobile */
@media (max-width: 1080px) {
  .resources .resource { min-width: 52px; padding: 5px 6px; }
  .resource:nth-child(n+7) { display: none; }
  .brand { min-width: 202px; }
  #left-panel { width: 322px; }
  #right-panel { width: 280px; }
  .bottom-stats { display: none; }
}
@media (max-width: 860px) {
  #hud { height: 58px; gap: 8px; padding: 0 10px; }
  .brand { min-width: 0; flex: none; }
  .brand-copy span { display: none; }
  .brand-copy h1 { font-size: 15px; letter-spacing: .12em; }
  .sigil { width: 30px; height: 30px; }
  .chrono { display: none; }
  .resources { justify-content: flex-start; gap: 0; }
  .resources .resource { min-width: 42px; padding: 4px 4px; gap: 4px; }
  .resource svg { width: 13px; height: 13px; }
  .resource .res-val { font-size: 12px; }
  .resource .res-cap { display: none; }
  .resource:nth-child(n+6) { display: none; }
  .hud-actions { margin-left: auto; }
  .hud-actions #btn-minimap { display: none; }
  #left-panel { left: 0; right: 0; top: auto; bottom: 54px; width: 100%; height: 40vh; border-left: 0; border-right: 0; border-bottom: 0; transition: height .2s; }
  #left-panel.collapsed { height: 44px; }
  #left-panel.collapsed .panel-scroll, #left-panel.collapsed .panel-footer { display: none; }
  #right-panel { display: none; }
  .codex-tabs { height: 44px; }
  .tab { padding: 5px 2px 4px; }
  .tab span { font-size: 12px; margin-bottom: 1px; }
  #bottom-bar { height: 54px; padding: 0 8px; gap: 8px; }
  .speed-btn { width: 30px; height: 27px; }
  .alert-ribbon { font-size: 8px; }
  #toast-stack { top: 70px; width: 90vw; }
  #event-banner { top: 66px; width: 94vw; padding: 10px; }
  #event-banner h3 { font-size: 17px; }
  .start-sub { font-size: 12px; }
  .start-blurb { font-size: 9px; padding: 0 24px; }
  .start-features { gap: 12px; font-size: 6.5px; }
  .modal { padding: 22px 18px; }
  .modal .rules { grid-template-columns: 1fr; }
  #overview { inset: 66px 8px 60px; }
}
@media (max-height: 660px) {
  .start-crest { width: 64px; height: 64px; }
  #start-screen h2 { font-size: 52px; margin: 6px 0; }
  .start-blurb { display: none; }
  .start-rule { margin: 12px 0; }
  .start-btn { margin-top: 16px; }
  .start-features { margin-top: 14px; }
}

