    researchActive: 'agriculture',
    completedResearch: [],
    time: { day: 1, dayInSeason: 1, season: 0, year: 732, hour: 7.15, weather: 'Clear skies', weatherTtl: 9 },
    speed: 1,
    prevSpeed: 1,
    tick: 0,
    simTime: 0,
    threat: 0,
    selected: null,
    hover: null,
    buildMode: null,
    buildCategory: 'All',
    uiTab: 'colony',
    expedition: null,
    stats: { gathered: 0, built: 0, kills: 0, mealsCooked: 0, researchDone: 0, daysSurvived: 1 },
    nextIncident: { day: 1, hour: 20.4 },
    recentDeath: 0,
    mood: 58,
    notifications: [],
    banner: null,
    log: [],
    quests: [
      { id: 'home', title: 'A Fire in the Dark', desc: 'Raise six new structures around the waystone. A camp becomes a colony one wall at a time.', objective: 'Structures raised', progress: 0, total: 6, status: 'active', reward: 'Research & silver' },
      { id: 'veil', title: 'Teeth in the Fog', desc: 'The Marches are testing you. Cut down five creatures that come for the fire.', objective: 'Creatures slain', progress: 0, total: 5, status: 'active', reward: 'Colony mood' },
      { id: 'shrine', title: 'The Sunken Shrine', desc: 'Something beneath the drowned stones is dreaming. Delve the ruin and silence it — or wake it.', objective: 'Delve the Sunken Shrine', progress: 0, total: 1, status: 'active', reward: 'Arcana & crystal' },
    ],
    choice: null,
    gameOver: false,
    dirty: true,
    lastUi: 0,
    nextId: 1,
    version: 1,
  };

  addInitialBuildings(state, rng);
  addInitialColonists(state, rng);
  state.selected = { kind: 'colonist', id: state.colonists[0].id };

  state.log = [
    { t: 'Dawn', icon: '✦', kind: 'epic', text: 'The exiles light the waystone fire. <strong>Ashenreach</strong> is founded.' },
    { t: 'Dawn', icon: '◈', kind: '', text: 'A broken waystone hums beneath the camp. Its dream is not a kind one.' },
    { t: 'Dawn', icon: '❦', kind: 'good', text: 'Sunwheat is sown. The first harvest will decide how the winter tastes.' },
  ];

  notify(state, 'The colony of Ashenreach is founded. Keep the fire burning.', 'epic');
  showBanner(state, 'A Fire in the Dark', 'The Marches are wide, hungry, and full of old promises. Five exiles have claimed a broken waystone. Build. Survive. Belong.', 'Chronicle begins');
  return state;
}

function addInitialBuildings(state, rng) {
  const place = (type, x, y, extra = {}) => {
    const def = BUILDINGS[type];
    const b = {
      id: 'b' + (state.nextId++), type, x, y, w: def.w, h: def.h,
      complete: true, progress: 100, active: true, ...extra,
    };
    state.buildings.push(b);
    return b;
  };
  place('campfire', 29, 22);
  place('tent', 26, 18);
  place('bed', 25, 21);
  place('bed', 25, 22);
  place('bed', 31, 22);
  place('bed', 32, 22);
  place('bed', 25, 23);
  place('stockpile', 23, 24);
  place('workbench', 32, 24);
  place('researchDesk', 33, 21);
  place('well', 35, 22);
  for (const [x, y] of [[27, 17], [28, 17], [29, 17], [27, 16], [28, 16], [29, 16]]) {
    const b = place('farm', x, y);
    b.crop = 0.35 + rng() * 0.45;
    state.world.tiles[y * state.world.w + x] = 7;
  }
  for (const [x, y] of [[28, 15], [29, 15], [30, 15], [31, 15], [27, 15]]) {
    place('palisade', x, y);
  }
}

function addInitialColonists(state, rng) {
  const spots = [[28, 23], [27, 23], [30, 23], [31, 23], [30, 21]];
  ROSTER.forEach((t, i) => {
    const [first, last] = t.name.split(' ');
    const c = makeColonist(state, {
      id: 'c' + (i + 1), first, last, race: t.race, cls: t.cls, traits: t.traits,
      skills: t.skills, priorities: { ...DEFAULT_PRIORITIES, ...t.priorities },
      x: spots[i][0], y: spots[i][1], rng,
    });
    state.colonists.push(c);
  });
}

export function makeColonist(state, opts) {
  const rng = opts.rng || Math.random;
  const race = opts.race || pick(rng, RACE_KEYS);
  const cls = opts.cls || pick(rng, CLASS_KEYS);
  const first = opts.first || pick(rng, FIRST_NAMES);
  const last = opts.last || pick(rng, LAST_NAMES);
  const skills = opts.skills || {};
  if (!opts.skills) for (const s of SKILLS) skills[s.id] = 1 + Math.floor(rng() * 7);
  for (const t of opts.traits || []) {
    const trait = TRAITS[t];
    if (trait?.skills) for (const [s, n] of Object.entries(trait.skills)) skills[s] = (skills[s] || 1) + n;
  }
  const frail = (opts.traits || []).includes('frail');
  const maxHp = 72 + (skills.combat || 4) * 4 - (frail ? 22 : 0);
  return {
    id: opts.id || 'c' + (state.nextId++),
    name: `${first} ${last}`,
    first, last, race, cls,
    traits: opts.traits || [],
    skills,
    priorities: { ...DEFAULT_PRIORITIES, ...(opts.priorities || {}) },
    x: opts.x, y: opts.y, homeX: opts.x, homeY: opts.y,
    path: [], pathIndex: 0,
    job: null, jobTarget: null,
    hp: maxHp, maxHp, bleeding: 0, downed: false, dead: false, downTimer: 0,
    hunger: 68 + rng() * 25, rest: 66 + rng() * 24, mood: 58 + rng() * 12,
    moodBase: 50, attackTimer: 0, movePhase: rng() * 6, facing: 1,
    status: 'Idle', thought: 'Watching the horizon.',
    onExpedition: false, xp: {}, level: 1,
    lastSocial: 0, breakTimer: 0,
    color: CLASSES[cls].color,
    skin: RACES[race].color,
  };
}

export function addColonist(state, rng = Math.random) {
  const used = new Set(state.colonists.map(c => c.name));
  let first = pick(rng, FIRST_NAMES), last = pick(rng, LAST_NAMES);
  let tries = 0;
  while (used.has(`${first} ${last}`) && tries++ < 20) { first = pick(rng, FIRST_NAMES); last = pick(rng, LAST_NAMES); }
  const traits = [];
  const keys = Object.keys(TRAITS);
  while (traits.length < 2) {
    const t = pick(rng, keys);
    if (!traits.includes(t)) traits.push(t);
  }
  const c = makeColonist(state, {
    first, last, traits, x: state.world.campX + 4, y: state.world.campY + 4, rng,
    race: pick(rng, RACE_KEYS), cls: pick(rng, CLASS_KEYS),
  });
  state.colonists.push(c);
  logEvent(state, `${c.name} joins the colony.`, '◈', 'good');
  notify(state, `<strong>${c.name}</strong> joins the colony as a ${RACES[c.race].name} ${CLASSES[c.cls].name}.`, 'good');
  return c;
}

export function logEvent(state, html, icon = '·', kind = '') {
  state.log.unshift({ t: timeLabel(state.time.hour), icon, kind, text: html });
  if (state.log.length > 90) state.log.pop();
  state.dirty = true;
}

export function notify(state, text, kind = '') {
  state.notifications.push({ id: 'n' + (state.nextId++), text, kind, ttl: 5.2 });
  if (state.notifications.length > 4) state.notifications.shift();
}

export function showBanner(state, title, text, kicker = 'Incident') {
  state.banner = { title, text, kicker, ttl: 6.3, max: 6.3 };
}

function addFloat(state, x, y, text, color = '#e9c987') {
  state.floats.push({ x, y, text, color, ttl: 1.2, max: 1.2, vy: -0.6 });
  if (state.floats.length > 40) state.floats.shift();
}

export function spawnParticles(state, x, y, count, colors, opts = {}) {
  for (let i = 0; i < count; i++) {
    const a = Math.random() * Math.PI * 2;
    const s = (opts.speed || 1.2) * (0.3 + Math.random());
    state.particles.push({
      x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s - (opts.lift || 0.2),
      life: (opts.life || 0.7) * (0.5 + Math.random()),
      max: opts.life || 0.7,
      color: colors[Math.floor(Math.random() * colors.length)],
      size: (opts.size || 2) * (0.5 + Math.random()),
      gravity: opts.gravity ?? 0.6,
    });
  }
  if (state.particles.length > 360) state.particles.splice(0, state.particles.length - 360);
}

export function costString(cost) {
  return Object.entries(cost).map(([r, n]) => `${n} ${RESOURCE_META[r]?.name || r}`).join(' · ');
}

export function canAfford(state, cost) {
  return Object.entries(cost || {}).every(([r, n]) => (state.resources[r] || 0) >= n);
}

export function spend(state, cost) {
  if (!canAfford(state, cost)) return false;
  for (const [r, n] of Object.entries(cost)) state.resources[r] -= n;
  state.dirty = true;
  return true;
}

export function addResource(state, resource, amount, quiet = false) {
  if (!(resource in state.resources)) return;
  state.resources[resource] = Math.max(0, Math.min(state.resourceCap, state.resources[resource] + amount));
  if (!quiet) state.dirty = true;
}

export function addResearch(state, amount) {
  state.researchPoints += amount;
  state.dirty = true;
  const r = RESEARCH[state.researchActive];
  if (r && state.researchPoints >= r.cost && !state.completedResearch.includes(state.researchActive)) {
    finishResearch(state, state.researchActive);
  }
}

export function finishResearch(state, id) {
  const r = RESEARCH[id];
  if (!r || state.completedResearch.includes(id)) return;
  if (state.researchPoints < r.cost) return;
  state.researchPoints -= r.cost;
  state.completedResearch.push(id);
  state.stats.researchDone++;
  state.researchActive = Object.keys(RESEARCH).find(k => !state.completedResearch.includes(k) && (!RESEARCH[k].requires || state.completedResearch.includes(RESEARCH[k].requires))) || null;
  logEvent(state, `<strong>${r.name}</strong> is understood. ${r.effect}`, '✦', 'epic');
  notify(state, `<strong>${r.name}</strong> researched. ${r.effect}`, 'epic');
  spawnParticles(state, state.world.campX, state.world.campY, 30, ['#e9c987', '#a27dc4', '#f4e3b5'], { speed: 2.4, life: 1.4, lift: 0.7, gravity: .05 });
  state.dirty = true;
  checkQuests(state);
}

export function setResearch(state, id) {
  const r = RESEARCH[id];
  if (!r || state.completedResearch.includes(id)) return;
  if (r.requires && !state.completedResearch.includes(r.requires)) {
    notify(state, `Requires ${RESEARCH[r.requires].name} first.`, 'bad');
    return;
  }
  state.researchActive = id;
  state.dirty = true;
}

export function getBuildingDef(state, type) {
  return BUILDINGS[type];
}

export function buildingsOfType(state, type) {
  return state.buildings.filter(b => b.type === type && b.complete);
}

export function hasBuilding(state, type) {
  return state.buildings.some(b => b.type === type && b.complete);
}

export function isUnlocked(state, type) {
  const def = BUILDINGS[type];
  if (!def) return false;
  return !def.requires || state.completedResearch.includes(def.requires);
}

export function canPlace(state, type, x, y) {
  const def = BUILDINGS[type];
  if (!def) return { ok: false, reason: 'Unknown structure.' };
  for (let yy = 0; yy < def.h; yy++) {
    for (let xx = 0; xx < def.w; xx++) {
      const tx = x + xx, ty = y + yy;
      if (tx < 0 || ty < 0 || tx >= state.world.w || ty >= state.world.h) return { ok: false, reason: 'Beyond the map.' };
      if (!TERRAIN_INFO[state.world.tiles[ty * state.world.w + tx]].walk) return { ok: false, reason: 'Unbuildable ground.' };
      const f = state.featureIndex.get(key(tx, ty));
      if (f) return { ok: false, reason: f.type === 'tree' ? 'A tree stands here. Mark it for chopping.' : 'Something already occupies this ground.' };
      const b = buildingAt(state.buildings, tx, ty);
      if (b) return { ok: false, reason: 'Structure overlap.' };
    }
  }
  return { ok: true };
}

export function placeBuilding(state, type, x, y) {
  const def = BUILDINGS[type];
  if (!def) return false;
  if (!isUnlocked(state, type)) { notify(state, `${def.name} has not been researched.`, 'bad'); return false; }
  const check = canPlace(state, type, x, y);
  if (!check.ok) { notify(state, check.reason, 'bad'); return false; }
  if (!canAfford(state, def.cost)) { notify(state, `Not enough materials for ${def.name}.`, 'bad'); return false; }
  spend(state, def.cost);
  const b = {
    id: 'b' + (state.nextId++), type, x, y, w: def.w, h: def.h,
    complete: false, progress: 0, active: true,
  };
  if (type === 'farm') b.crop = 0;
  state.buildings.push(b);
  state.buildMode = { type };
  spawnParticles(state, x + def.w / 2, y + def.h / 2, 8, ['#c9a15c', '#9c8255', '#e6d4ae'], { speed: .8, size: 1.3, life: .5 });
  state.dirty = true;
  return true;
}

export function cancelBuilding(state, id) {
  const b = state.buildings.find(v => v.id === id);
  if (!b) return;
  if (b.complete) {
    notify(state, 'Completed structures cannot be cancelled. Use deconstruct.', 'bad');
    return;
  }
  const def = BUILDINGS[b.type];
  for (const [r, n] of Object.entries(def.cost)) addResource(state, r, Math.floor(n / 2), true);
  state.buildings = state.buildings.filter(v => v.id !== id);
  if (state.selected?.id === id) state.selected = null;
  logEvent(state, `Cancelled ${def.name}. Half the materials recovered.`, '⌫');
  state.dirty = true;
}

export function markFeature(state, feature) {
  if (!feature) return;
  feature.marked = !feature.marked;
  state.dirty = true;
}

export function setPriority(state, colonistId, work, value) {
  const c = state.colonists.find(v => v.id === colonistId);
  if (!c) return;
  c.priorities[work] = value;
  if (c.job && c.job.workType === work && value === 4) clearJob(state, c);
  state.dirty = true;
}

export function select(state, kind, id) {
  state.selected = kind ? { kind, id } : null;
  state.dirty = true;
}

export function setSpeed(state, speed) {
  if (speed === 0) {
    if (state.speed !== 0) state.prevSpeed = state.speed;
    state.speed = 0;
  } else {
    state.speed = speed;
    state.prevSpeed = speed;
  }
  state.dirty = true;
}

export function togglePause(state) {
  setSpeed(state, state.speed === 0 ? state.prevSpeed || 1 : 0);
}

export function startExpedition(state, id) {
  if (state.expedition) { notify(state, 'A party is already in the field.', 'bad'); return; }
  const exp = EXPEDITIONS.find(e => e.id === id);
  if (!exp) return;
  if (exp.requires) {
    const loc = state.quests.find(q => q.id === exp.requires);
    if (!loc || loc.status !== 'complete') { notify(state, 'That place has not been discovered.', 'bad'); return; }
  }
  if (!canAfford(state, exp.cost)) { notify(state, 'The party lacks supplies.', 'bad'); return; }
  spend(state, exp.cost);
  const candidates = [...state.colonists].filter(c => !c.dead && !c.downed).sort((a, b) => (b.skills[exp.skill] || 0) - (a.skills[exp.skill] || 0));
  const party = candidates.slice(0, Math.min(2, candidates.length));
  for (const c of party) { c.onExpedition = true; clearJob(state, c); c.status = 'On expedition'; }
  state.expedition = {
    id, name: exp.name, daysLeft: Math.max(1, Math.round(exp.days * 1.5)), risk: exp.risk,
    party: party.map(c => c.id), started: state.time.day, reward: exp.reward, quest: exp.quest,
    progress: 0, total: Math.max(1, Math.round(exp.days * 1.5)),
  };
  logEvent(state, `A party sets out for <strong>${exp.name}</strong>.`, '◈', 'epic');
  notify(state, `Expedition departed: ${exp.name}.`, 'epic');
  showBanner(state, exp.name, exp.desc, 'Expedition');
  state.dirty = true;
}

function completeExpedition(state) {
  const exp = state.expedition;
  if (!exp) return;
  for (const [r, n] of Object.entries(exp.reward)) {
    if (r === 'research') addResearch(state, n);
    else addResource(state, r, n);
  }
  for (const id of exp.party) {
    const c = state.colonists.find(v => v.id === id);
    if (c) {
      c.onExpedition = false;
      c.x = state.world.campX + (Math.random() - .5) * 2;
      c.y = state.world.campY + 2;
      c.hunger = Math.max(12, c.hunger - 20);
      c.rest = Math.max(8, c.rest - 25);
      c.status = 'Returned';
      c.skills[exp.skill] = Math.min(10, (c.skills[exp.skill] || 1) + 0.4);
    }
  }
  logEvent(state, `The party returns from <strong>${exp.name}</strong>. ${Object.entries(exp.reward).map(([r, n]) => `+${n} ${RESOURCE_META[r]?.name || 'research'}`).join(', ')}.`, '◈', 'epic');
  notify(state, `Expedition returned from ${exp.name}.`, 'epic');
  if (exp.quest) {
    const q = state.quests.find(v => v.id === exp.quest);
    if (q) { q.progress = 1; q.status = 'complete'; }
  }
  state.expedition = null;
  checkQuests(state);
  state.dirty = true;
}

export function checkQuests(state) {
  for (const q of state.quests) {
    if (q.status !== 'active') continue;
    if (q.id === 'home') q.progress = Math.min(q.total, state.stats.built);
    if (q.id === 'veil') q.progress = Math.min(q.total, state.stats.kills);
    if (q.id === 'shrine' && q.progress >= 1) q.status = 'complete';
    if (q.progress >= q.total) {
      q.status = 'complete';
      if (q.id === 'home') { addResearch(state, 30); addResource(state, 'silver', 30); }
      if (q.id === 'veil') { for (const c of state.colonists) c.mood = Math.min(100, c.mood + 10); addResource(state, 'crystal', 3); }
      if (q.id === 'shrine') { addResearch(state, 40); addResource(state, 'crystal', 6); state.quests.find(v => v.id === 'shrine').status = 'complete'; }
      logEvent(state, `Quest complete: <strong>${q.title}</strong>.`, '✦', 'epic');
      notify(state, `Quest complete — ${q.title}.`, 'epic');
      showBanner(state, q.title, 'The chronicle remembers this deed. Your people will tell it around the fire for years.', 'Quest Complete');
      spawnParticles(state, state.world.campX, state.world.campY, 24, ['#e9c987', '#f4e3b5'], { speed: 1.5, life: 1.5, lift: .6, gravity: .05 });
    }
  }
}

function updateTime(state, dt) {
  const t = state.time;
  const before = t.hour;
  t.hour += dt * (24 / 300); // one day = five minutes at 1x
  t.weatherTtl -= dt;
  const crossed = Math.floor(before) !== Math.floor(t.hour);
  if (crossed) onHour(state, Math.floor(t.hour) % 24);
  if (t.hour >= 24) {
    t.hour -= 24;
    t.day++;
    t.dayInSeason++;
    state.stats.daysSurvived = t.day;
    if (t.dayInSeason > 12) {
      t.dayInSeason = 1;
      t.season = (t.season + 1) % SEASONS.length;
      logEvent(state, `The season turns. <strong>${SEASONS[t.season].name}</strong> settles over the Marches.`, '◐', 'epic');
    }
    if (t.day === 4) {
      const q = state.quests.find(v => v.id === 'barrow');
      if (!q) state.quests.push({ id: 'barrow', title: 'Kingsbarrow', desc: 'A hill that was not always a hill. Its door has opened.', objective: 'Open Kingsbarrow', progress: 0, total: 1, status: 'active', reward: 'Treasure' });
    }
    logEvent(state, `Dawn breaks on day ${state.stats.daysSurvived}. The colony endures.`, '☼', 'good');
    for (const c of state.colonists) if (!c.dead) c.mood = Math.min(100, c.mood + 2);
    checkQuests(state);
  }
  if (t.weatherTtl <= 0) {
    const season = SEASONS[t.season];
    t.weather = pick(Math.random, season.weather);
    t.weatherTtl = 7 + Math.random() * 10;
    if (t.weather.includes('rain') || t.weather.includes('sleet') || t.weather.includes('Mist')) {
      for (const c of state.colonists) c.mood = Math.max(0, c.mood - 1);
    }
    state.dirty = true;
  }
  if (state.nextIncident && t.day >= state.nextIncident.day && t.hour >= state.nextIncident.hour) {
    state.nextIncident = null;
    triggerIncident(state);
  }
  if (state.expedition) {
    state.expedition.progress += dt / (300 * 0.45);
    if (state.expedition.progress >= state.expedition.total) completeExpedition(state);
  }
}

function onHour(state, hour) {
  state.dirty = true;
  if (hour === 6) {
    // New day checks and a small chance of discovery.
    if (Math.random() < 0.32) {
      const amount = 3 + Math.floor(Math.random() * 6);
      addResource(state, 'food', amount, true);
      logEvent(state, `Foragers return with ${amount} food from the riverbank.`, '❦', 'good');
    }
  }
  if (hour === 21 && state.stats.daysSurvived > 1 && Math.random() < 0.35) {
    logEvent(state, 'Something howls beyond the palisade. The watch doubles.', '◈');
  }
  if (state.nextIncident === null && !state.expedition && hour >= 6 && Math.random() < 0.14) {
    const days = state.stats.daysSurvived;
    state.nextIncident = { day: state.time.day, hour: Math.min(23.5, hour + 3 + Math.random() * 5) };
  }
}

export function triggerIncident(state, forced = null) {
  const day = state.time.day;
  const pool = INCIDENTS.filter(i => !forced && day >= i.minDay) || [];
  if (forced) {
    const chosen = INCIDENTS.find(i => i.id === forced);
    if (chosen) resolveIncident(state, chosen);
    return;
  }
  let total = pool.reduce((s, i) => s + i.weight, 0);
  let roll = Math.random() * total;
  let chosen = pool[0] || INCIDENTS[0];
  for (const i of pool) { roll -= i.weight; if (roll <= 0) { chosen = i; break; } }
  resolveIncident(state, chosen);
  const nextDelay = 7 + Math.random() * 14;
  state.nextIncident = { day: state.time.day + Math.floor((state.time.hour + nextDelay) / 24), hour: (state.time.hour + nextDelay) % 24 };
}

function resolveIncident(state, incident) {
  showBanner(state, incident.title, incident.text, incident.kicker);
  logEvent(state, `<strong>${incident.title}.</strong> ${incident.text}`, '◈', incident.spawn ? 'bad' : 'epic');
  if (incident.spawn) {
    const count = incident.count[0] + Math.floor(Math.random() * (incident.count[1] - incident.count[0] + 1));
    for (let i = 0; i < count; i++) spawnEnemy(state, incident.spawn, i);
    notify(state, `${incident.title} — ${count} hostiles approach.`, 'bad');
    state.speed = state.speed === 0 ? 0 : 1;
    return;
  }
  switch (incident.action) {
    case 'traveler': {
      if (state.colonists.filter(c => !c.dead).length >= 9) {
        addResource(state, 'silver', 9);
        notify(state, 'The traveler leaves a small pouch of silver and moves on.', '');
        logEvent(state, 'A traveler shares news, then walks on. <strong>+9 silver</strong>.', '◈', 'good');
      } else {
        addColonist(state, Math.random);
        logEvent(state, 'The traveler chooses to stay. Another chair by the fire.', '◈', 'good');
      }
      break;
    }
    case 'merchant': {
      if (state.resources.silver >= 18) {
        state.resources.silver -= 18;
        addResource(state, 'herbs', 6, true);
        addResource(state, 'crystal', 2, true);
        notify(state, 'The masked merchant sells 6 herbs and 2 crystal for 18 silver.', 'good');
        logEvent(state, 'A masked merchant trades <strong>6 herbs, 2 crystal</strong> for 18 silver.', '◈', 'good');
      } else {
        notify(state, 'The merchant scoffs at your empty purse and moves on.', 'bad');
      }
      break;
    }
    case 'eclipse': {
      state.time.weather = 'Eclipse';
      state.time.weatherTtl = 20;
      for (const c of state.colonists) c.mood = Math.max(0, c.mood - 9);
      notify(state, 'An unnatural eclipse. Moods sour; shadows move.', 'bad');
      break;
    }
    case 'cache': {
      const rewards = { wood: 18, stone: 12, food: 10, silver: 8 };
      for (const [r, n] of Object.entries(rewards)) addResource(state, r, n, true);
      notify(state, 'A sealed cache yields timber, stone, food and silver.', 'good');
      logEvent(state, 'A rain-sealed cache is opened: <strong>+18 wood, +12 stone, +10 food, +8 silver</strong>.', '◈', 'good');
      break;
    }
    case 'omen': {
      addResearch(state, 12);
      notify(state, 'The waystone murmurs. +12 research; the shrine calls.', 'epic');
      break;
    }
    case 'festival': {
      for (const c of state.colonists) c.mood = Math.min(100, c.mood + 13);
      state.resources.meals += 4;
      notify(state, 'A small festival. Mood rises; four meals appear from nowhere.', 'good');
      logEvent(state, 'Honey, bad singing, and a night of defiant joy. <strong>Mood rises.</strong>', '❦', 'good');
      break;
    }
  }
  state.dirty = true;
}

export function spawnEnemy(state, type, index = 0) {
  const info = ENEMY_TYPES[type];
  const edge = Math.floor(Math.random() * 4);
  let x, y, tries = 0;
  do {
    if (edge === 0) { x = 2 + Math.floor(Math.random() * (state.world.w - 4)); y = 2; }
    else if (edge === 1) { x = state.world.w - 3; y = 2 + Math.floor(Math.random() * (state.world.h - 4)); }
    else if (edge === 2) { x = 2 + Math.floor(Math.random() * (state.world.w - 4)); y = state.world.h - 3; }
    else { x = 2; y = 2 + Math.floor(Math.random() * (state.world.h - 4)); }
    tries++;
  } while (!isWalkable(state, x, y) && tries < 80);
  if (!isWalkable(state, x, y)) { x = state.world.campX + 12; y = state.world.campY; }
  const scale = 1 + Math.max(0, state.time.day - 1) * 0.055;
  const e = {
    id: 'e' + (state.nextId++), type, name: info.name,
    x, y, hp: Math.round(info.hp * scale), maxHp: Math.round(info.hp * scale),
    damage: info.damage, range: info.range, speed: info.speed, color: info.color,
    accent: info.accent, shape: info.shape, cooldown: 1 + index * .25, path: [],
    pathTimer: 0, targetId: null, dead: false, hitFlash: 0, facing: 1, bob: Math.random() * 6,
    xp: info.xp, loot: info.loot,
  };
  state.enemies.push(e);
  return e;
}

export function simulate(state, rawDt) {
  if (state.speed === 0 || state.gameOver) {
    updateVisuals(state, rawDt);
    return;
  }
  const speedScale = state.speed === 1 ? 1 : state.speed === 2 ? 2.8 : 7;
  const dt = Math.min(rawDt, .08) * speedScale;
  state.simTime += dt;
  state.threat = state.enemies.filter(e => !e.dead).length;
  updateTime(state, dt);
  updateFarms(state, dt);
  updateFeatures(state, dt);
  updateColonists(state, dt);
  updateEnemies(state, dt);
  updateProjectiles(state, dt);
  updateFloats(state, dt);
  updateVisuals(state, rawDt);
  updateMood(state, dt);
  state.tick++;
  if (state.tick % 6 === 0) state.dirty = true;
}

function updateVisuals(state, dt) {
  const pdt = Math.min(dt, .1);
  for (const p of state.particles) {
    p.life -= pdt;
    p.x += p.vx * pdt;
    p.y += p.vy * pdt;
    p.vy += p.gravity * pdt;
    p.vx *= .985;
    p.vy *= .985;
  }
  state.particles = state.particles.filter(p => p.life > 0);
  for (const f of state.floats) { f.ttl -= pdt; f.y += f.vy * pdt; f.vy *= .96; }
  state.floats = state.floats.filter(f => f.ttl > 0);
  if (state.banner) {
    state.banner.ttl -= dt;
    if (state.banner.ttl <= 0) state.banner = null;
  }
  state.notifications = state.notifications.filter(n => { n.ttl -= dt; return n.ttl > 0; });
  for (const c of state.colonists) { c.attackTimer = Math.max(0, c.attackTimer - dt); c.movePhase += dt * 7; }
  for (const e of state.enemies) { e.cooldown = Math.max(0, e.cooldown - dt); e.hitFlash = Math.max(0, e.hitFlash - dt); e.bob += dt * 4; }
}

function updateFarms(state, dt) {
  for (const b of state.buildings) {
    if (b.type !== 'farm' || !b.complete) continue;
    const growthRate = state.completedResearch.includes('agriculture') ? 0.022 : 0.016;
    b.crop = Math.min(1, (b.crop || 0) + dt * growthRate * (0.8 + (state.time.season === 2 ? -0.3 : state.time.season === 0 ? 0.2 : 0)));
  }
}

function updateFeatures(state, dt) {
  for (const f of state.features) {
    if (f.type === 'bush' && f.amount < f.max && f.regrow) {
      f.regrowTimer += dt;
      if (f.regrowTimer > f.regrow) {
        f.amount = f.max;
        f.regrowTimer = 0;
        state.dirty = true;
      }
    }
  }
}

function updateMood(state, dt) {
  if (state.tick % 8 !== 0) return;
  const campX = state.world.campX, campY = state.world.campY;
  const hasFire = state.buildings.some(b => b.type === 'campfire' && b.complete);
  const hasShrine = state.buildings.some(b => b.type === 'shrine' && b.complete);
  const hasWell = state.buildings.some(b => b.type === 'well' && b.complete);
  const beds = state.buildings.filter(b => b.type === 'bed' && b.complete).length;
  const night = state.time.hour < 6 || state.time.hour > 21;
  let total = 0, alive = 0;
  for (const c of state.colonists) {
    if (c.dead || c.onExpedition) continue;
    alive++;
    let target = c.moodBase;
    target += (c.hunger - 55) * .13;
    target += (c.rest - 55) * .09;
    if (hasFire) target += 4;
    if (hasShrine) target += 8;
    if (hasWell) target += 3;
    if (beds >= state.colonists.filter(v => !v.dead).length) target += 3;
    if (state.time.weather.includes('rain') || state.time.weather.includes('sleet')) target -= 5;
    if (state.time.weather === 'Eclipse') target -= 12;
    if (state.recentDeath > 0) target -= state.recentDeath;
    for (const tr of c.traits) {
      const td = TRAITS[tr];
      if (td?.mood) target += td.mood;
      if (tr === 'nightOwl' && night) target += 5;
      if (tr === 'wanderlust' && c.job?.type === 'idle') target -= 4;
      if (tr === 'scarred' && state.time.weather.includes('rain')) target -= 6;
    }
    const home = dist(c.x, c.y, campX, campY);
    if (home < 6) target += 2;
    target = clamp(target, 0, 100);
    c.mood += (target - c.mood) * .07;
    c.mood = clamp(c.mood, 0, 100);
    total += c.mood;
    c.thought = thoughtFor(c, state);
    if (c.mood < 16 && c.breakTimer <= 0) {
      c.breakTimer = 30;
      logEvent(state, `<strong>${c.name}</strong> is overcome by despair and wanders from their duties.`, '☹', 'bad');
      clearJob(state, c);
    }
    if (c.breakTimer > 0) c.breakTimer -= dt;
  }
  state.mood = alive ? total / alive : 0;
  if (state.recentDeath > 0) state.recentDeath = Math.max(0, state.recentDeath - 0.03);
}

function thoughtFor(c, state) {
  if (c.downed) return 'Bleeding into the dirt.';
  if (c.bleeding > 0) return 'Wounded and bleeding.';
  if (c.hunger < 22) return 'Hungry enough to chew leather.';
  if (c.rest < 20) return 'Exhausted.';
  if (c.job?.type === 'fight') return 'Standing between the dark and the fire.';
  if (state.time.weather === 'Eclipse') return 'The sun has turned its face away.';
  if (c.mood > 78) return 'Grateful for this strange, stubborn home.';
  if (c.mood < 30) return 'Wondering what they left behind.';
  if (c.job?.type === 'research') return 'Chasing a thought through old symbols.';
  if (c.job?.type === 'cook') return 'Something warm, at last.';
  return 'Watching the horizon.';
}

function updateColonists(state, dt) {
  for (const c of state.colonists) {
    if (c.dead) continue;
    if (c.onExpedition) { c.status = 'On expedition'; continue; }
    if (c.downed) {
      c.downTimer += dt;
      if (c.bleeding > 0) {
        c.bleeding = Math.max(0, c.bleeding - dt * .04);
        c.hp -= dt * .35;
      }
      if (c.hp <= -8 || c.downTimer > 150) killColonist(state, c);
      continue;
    }
    c.hunger = Math.max(0, c.hunger - dt * .17);
    c.rest = Math.max(0, c.rest - dt * .105);
    if (c.hunger <= 0) { c.hp -= dt * .35; c.bleeding = Math.max(c.bleeding, .2); }
    if (c.bleeding > 0) {
      c.hp -= dt * c.bleeding * .11;
      c.bleeding = Math.max(0, c.bleeding - dt * .055);
      if (c.hp <= 0) downColonist(state, c, 'bled out');
    } else if (c.hp < c.maxHp && c.job?.type !== 'sleep') {
      c.hp = Math.min(c.maxHp, c.hp + dt * .06);
    }
    if (c.breakTimer > 0) {
      c.breakTimer -= dt;
      if (!c.job || c.job.type === 'idle') { c.status = 'Despairing'; continue; }
    }
    if (state.threat > 0 && c.hp > 18 && (c.priorities.guard || 4) < 4) {
      if (!c.job || c.job.type !== 'fight') {
        const target = nearestEnemy(state, c.x, c.y);
        if (target) { startFight(state, c, target); continue; }
      }
    }
    if (c.job?.type === 'fight' && (state.threat === 0 || !state.enemies.some(e => e.id === c.job.targetId && !e.dead))) {
      clearJob(state, c); c.job = null;
    }
    if (!c.job) chooseActivity(state, c);
    if (!c.job) { c.status = c.breakTimer > 0 ? 'Despairing' : 'Idle'; continue; }
    if (c.job.type === 'fight') { updateFight(state, c, dt); continue; }
    if (c.job.type === 'sleep') { updateSleep(state, c, dt); continue; }
    if (c.job.type === 'eat') { updateEat(state, c, dt); continue; }
    updateWork(state, c, dt);
  }
}

function nearestEnemy(state, x, y) {
  let best = null, bd = 99;
  for (const e of state.enemies) {
    if (e.dead) continue;
    const d = dist(x, y, e.x, e.y);
    if (d < bd) { bd = d; best = e; }
  }
  return best;
}

function nearestColonist(state, x, y) {
  let best = null, bd = 99;
  for (const c of state.colonists) {
    if (c.dead || c.downed || c.onExpedition) continue;
    const d = dist(x, y, c.x, c.y);
    if (d < bd) { bd = d; best = c; }
  }
  return best;
}

function startFight(state, c, enemy) {
  clearJob(state, c);
  c.job = { type: 'fight', targetId: enemy.id, workType: 'guard', x: enemy.x, y: enemy.y };
  c.status = CLASSES[c.cls].ranged ? 'Loosing arrows' : 'Charging';
  c.path = [];
  c.pathTimer = 0;
}

function updateFight(state, c, dt) {
  const e = state.enemies.find(v => v.id === c.job.targetId && !v.dead);
  if (!e) { clearJob(state, c); return; }
  const cls = CLASSES[c.cls];
  const d = dist(c.x, c.y, e.x, e.y);
  c.facing = e.x < c.x ? -1 : 1;
  c.pathTimer -= dt;
  const desired = cls.ranged ? Math.max(2.8, cls.range * .62) : 1.05;
  if (d > desired && c.pathTimer <= 0) {
    c.pathTimer = .7;
    const spot = findAdjacentWalkable(state, Math.round(e.x), Math.round(e.y));
    if (spot) {
      const path = findPath(state, Math.round(c.x), Math.round(c.y), spot.x, spot.y, 1800);
      if (path) c.path = path;
      c.pathIndex = 0;
    }
  }
  if (d > desired) { moveAlongPath(state, c, dt, 1.15); c.status = 'Closing'; }
  else { c.status = cls.ranged ? 'Firing' : 'Fighting'; }
  if (c.attackTimer <= 0 && d <= (cls.ranged ? cls.range : 1.45)) {
    c.attackTimer = cls.ranged ? 1.45 : 1.0;
    const bonus = 1 + (c.skills.combat || 1) * .075;
    let dmg = range(Math.random, cls.damage[0], cls.damage[1]) * bonus;
    if (cls.ranged) {
      const color = c.cls === 'sorcerer' ? '#c79ae8' : c.cls === 'cleric' ? '#f0dfaa' : '#d7b477';
      state.projectiles.push({
        x: c.x, y: c.y - .25, targetId: e.id, tx: e.x, ty: e.y, speed: 9,
        damage: dmg, color, type: c.cls === 'sorcerer' ? 'orb' : 'arrow', life: 2.2,
      });
      spawnParticles(state, c.x + c.facing * .3, c.y - .3, 3, [color], { speed: .5, life: .3, size: 1 });
    } else {
      hurtEnemy(state, e, dmg, c);
      spawnParticles(state, e.x, e.y - .2, 5, ['#8d3c31', '#b25343', '#5b2d25'], { speed: .9, life: .55, size: 1.5, gravity: 1.2 });
    }
  }
}

function hurtEnemy(state, e, dmg, source) {
  if (e.dead) return;
  e.hp -= dmg;
  e.hitFlash = .15;
  addFloat(state, e.x, e.y - .8, Math.round(dmg), '#e7b08a');
  if (e.hp <= 0) {
    e.dead = true;
    state.stats.kills++;
    if (source) source.skills.combat = Math.min(10, (source.skills.combat || 1) + .08);
    spawnParticles(state, e.x, e.y - .2, 16, ['#7a2d25', '#a54636', '#d0b58b'], { speed: 1.5, life: .9, size: 2, gravity: 1.2 });
    for (const [r, n] of Object.entries(ENEMY_TYPES[e.type].loot)) addResource(state, r, n, true);
    if (e.type === 'ogre' || e.type === 'wraith') logEvent(state, `<strong>${source?.name || 'The colony'}</strong> fells a ${e.name}.`, '⚔', 'good');
    checkQuests(state);
    if (state.enemies.every(v => v.dead)) {
      notify(state, 'The attack is broken. The fire still burns.', 'good');
      logEvent(state, 'The last hostile falls. Silence returns to the Marches.', '⚔', 'good');
      for (const c of state.colonists) if (!c.dead) c.mood = Math.min(100, c.mood + 5);
    }
  }
}

function downColonist(state, c, reason) {
  if (c.downed || c.dead) return;
  c.downed = true;
  c.hp = 0;
  c.bleeding = Math.max(c.bleeding, 1.4);
  c.downTimer = 0;
  clearJob(state, c);
  c.status = 'Downed';
  logEvent(state, `<strong>${c.name}</strong> is downed — ${reason}.`, '✚', 'bad');
  notify(state, `${c.name} is down and bleeding.`, 'bad');
  spawnParticles(state, c.x, c.y, 12, ['#8d3c31', '#b25343'], { speed: 1.1, life: .8, size: 1.6, gravity: 1.1 });
}

function killColonist(state, c) {
  if (c.dead) return;
  c.dead = true;
  c.downed = false;
  clearJob(state, c);
  c.status = 'Dead';
  state.recentDeath = Math.min(28, state.recentDeath + 14);
  logEvent(state, `<strong>${c.name}</strong> has died. The colony will carry the weight of it.`, '†', 'bad');
  notify(state, `${c.name} is dead.`, 'bad');
  showBanner(state, 'A Life Ends', `${c.name} has died. The Marches do not apologize.`, 'Death in the Colony');
  const f = { id: 'f' + (state.nextId++), type: 'grave', x: Math.round(c.x), y: Math.round(c.y), amount: 1, max: 1, marked: false, regrow: 0, sway: 0, size: 1, variant: 0 };
  state.features.push(f);
  state.featureIndex.set(key(f.x, f.y), f);
  if (state.selected?.id === c.id) state.selected = null;
  if (state.colonists.every(v => v.dead)) {
    state.gameOver = true;
    setTimeout(() => {}, 0);
  }
}

function clearJob(state, c) {
  c.job = null;
  c.path = [];
  c.pathIndex = 0;
  c.status = 'Idle';
}

function chooseActivity(state, c) {
  if (state.threat > 0 && (c.priorities.guard || 4) < 4 && c.hp > 18) {
    const target = nearestEnemy(state, c.x, c.y);
    if (target) { startFight(state, c, target); return; }
  }
  // Critical needs.
  if (c.hunger < 24 && (state.resources.meals > 0 || state.resources.food > 0)) {
    startEat(state, c); return;
  }
  const sleepy = c.rest < 16 || ((state.time.hour >= 22 || state.time.hour < 5) && c.rest < 68);
  if (sleepy && state.threat === 0) { startSleep(state, c); return; }
  if (c.hp < c.maxHp * .35 && c.bleeding > 0 && state.threat === 0) {
    startSleep(state, c, true); return;
  }
  if (c.breakTimer > 0) { startWander(state, c); return; }
  const job = findJob(state, c);
  if (job) { startJob(state, c, job); return; }
  startWander(state, c);
}

function startEat(state, c) {
  let spot = state.buildings.find(b => b.type === 'campfire' && b.complete);
  if (!spot) spot = state.buildings.find(b => b.type === 'stockpile' && b.complete);
  const target = spot ? { x: spot.x + Math.floor(spot.w / 2), y: spot.y + Math.floor(spot.h / 2) } : { x: c.x, y: c.y };
  clearJob(state, c);
  const path = findPath(state, Math.round(c.x), Math.round(c.y), target.x, target.y, 2000);
  c.job = { type: 'eat', x: target.x, y: target.y, phase: 'moving', progress: 0, workType: 'patient', duration: 3.2 };
  c.path = path || [];
  c.pathIndex = 0;
  c.status = 'Hungry';
  if (!path && dist(c.x, c.y, target.x, target.y) > 1.5) { c.job.phase = 'working'; }
}

function updateEat(state, c, dt) {
  if (c.job.phase === 'moving') {
    if (moveAlongPath(state, c, dt)) c.job.phase = 'working';
    c.status = 'Heading to eat';
    if (!c.path.length) c.job.phase = 'working';
    return;
  }
  c.job.progress += dt;
  c.status = 'Eating';
  if (c.job.progress >= c.job.duration) {
    if (state.resources.meals > 0) {
      state.resources.meals--;
      c.hunger = Math.min(100, c.hunger + 62);
      c.mood = Math.min(100, c.mood + 4);
      addFloat(state, c.x, c.y - .9, 'Meal', '#e9c987');
    } else if (state.resources.food > 0) {
      state.resources.food--;
      c.hunger = Math.min(100, c.hunger + 38);
      addFloat(state, c.x, c.y - .9, 'Raw food', '#b8a378');
    }
    c.hunger = Math.min(100, c.hunger + 5);
    clearJob(state, c);
  }
}

function startSleep(state, c, medical = false) {
  const beds = state.buildings.filter(b => (b.type === 'bed' || b.type === 'infirmary') && b.complete);
  const occupied = new Set(state.colonists.filter(v => v !== c && v.job?.type === 'sleep' && v.job.buildingId).map(v => v.job.buildingId));
  const bed = beds.find(b => !occupied.has(b.id)) || null;
  const tx = bed ? bed.x + Math.floor(bed.w / 2) : state.world.campX;
  const ty = bed ? bed.y + Math.floor(bed.h / 2) : state.world.campY + 1;
  clearJob(state, c);
  const path = findPath(state, Math.round(c.x), Math.round(c.y), tx, ty, 2200);
  c.job = { type: 'sleep', x: tx, y: ty, phase: 'moving', progress: 0, workType: 'patient', buildingId: bed?.id, medical };
  c.path = path || [];
  c.pathIndex = 0;
  c.status = 'Seeking rest';
}

function updateSleep(state, c, dt) {
  if (c.job.phase === 'moving') {
    c.status = 'Seeking a bed';
    if (moveAlongPath(state, c, dt) || !c.path.length) c.job.phase = 'sleeping';
    return;
  }
  c.status = 'Sleeping';
  const comfort = c.job.buildingId ? (state.completedResearch.includes('medicine') ? 4.4 : 3.6) : 2.0;
  c.rest = Math.min(100, c.rest + dt * comfort);
  if (c.job.medical) { c.hp = Math.min(c.maxHp, c.hp + dt * .35); c.bleeding = Math.max(0, c.bleeding - dt * .12); }
  else c.hp = Math.min(c.maxHp, c.hp + dt * .08);
  if (c.rest >= 92 || (state.threat > 0 && c.rest > 30) || (state.time.hour >= 6 && state.time.hour < 20)) {
    clearJob(state, c);
    c.status = 'Rested';
  }
}

function startWander(state, c) {
  const angle = Math.random() * Math.PI * 2;
  const r = 1.5 + Math.random() * 4.5;
  let tx = Math.round(state.world.campX + Math.cos(angle) * r);
  let ty = Math.round(state.world.campY + Math.sin(angle) * r);
  if (!isWalkable(state, tx, ty)) { tx = Math.round(c.x); ty = Math.round(c.y); }
  const path = findPath(state, Math.round(c.x), Math.round(c.y), tx, ty, 800) || [];
  c.job = { type: 'idle', x: tx, y: ty, path: null, phase: 'moving', wait: .5 + Math.random() * 2, workType: 'haul' };
  c.path = path;
  c.pathIndex = 0;
  c.status = c.breakTimer > 0 ? 'Despairing' : 'Wandering';
}

function findJob(state, c) {
  const candidates = createJobs(state).filter(j => (c.priorities[j.workType] || 4) < 4);
  if (!candidates.length) return null;
  let best = null, bestScore = Infinity;
  for (const j of candidates) {
    if (j.claimedBy && j.claimedBy !== c.id) continue;
    const d = dist(c.x, c.y, j.x, j.y);
    const skill = WORK_TYPES.find(w => w.id === j.workType)?.skill;
    const sk = skill ? c.skills[skill] || 1 : 4;
    const score = (c.priorities[j.workType] || 4) * 90 + d * 3 - sk * 2.2 + (j.urgency || 0);
    if (score < bestScore) { bestScore = score; best = j; }
  }
  return best;
}

function createJobs(state) {
  const jobs = [];
  const claimed = new Set();
  for (const c of state.colonists) {
    if (c.job?.jobKey) claimed.add(c.job.jobKey);
  }
  const add = (job) => {
    if (!job.jobKey) job.jobKey = job.type + ':' + (job.targetId || job.featureId || job.buildingId || `${job.x},${job.y}`);
    if (claimed.has(job.jobKey)) return;
    claimed.add(job.jobKey);
    jobs.push(job);
  };

  // Construction first — the colony needs walls more than another story.
  for (const b of state.buildings) {
    if (b.complete) continue;
    const def = BUILDINGS[b.type];
    add({ type: 'construct', workType: 'construct', buildingId: b.id, x: b.x, y: b.y, targetId: b.id, urgency: -40, duration: def.time });
  }

  // Marked resources.
  for (const f of state.features) {
    if (!f.marked || f.amount <= 0 || f.type === 'grave' || f.type === 'waystone') continue;
    let workType = 'chop', label = 'Chopping';
    if (f.type === 'rock' || f.type === 'crystal' || f.type === 'ruinStone') { workType = 'mine'; label = 'Mining'; }
    if (f.type === 'bush') { workType = 'harvest'; label = 'Foraging'; }
    add({ type: 'gather', workType, featureId: f.id, x: f.x, y: f.y, targetId: f.id, urgency: -10, label });
  }

  // Farms: plant empty plots, harvest ripe ones.
  for (const b of state.buildings) {
    if (b.type !== 'farm' || !b.complete) continue;
    if ((b.crop || 0) >= 1) add({ type: 'harvest', workType: 'harvest', buildingId: b.id, targetId: b.id, x: b.x, y: b.y, urgency: -30, label: 'Harvesting' });
    else if ((b.crop || 0) <= 0) add({ type: 'plant', workType: 'plant', buildingId: b.id, targetId: b.id, x: b.x, y: b.y, urgency: -5, label: 'Sowing' });
  }

  // Cooking.
  const fire = state.buildings.find(b => b.type === 'campfire' && b.complete);
  if (fire && state.resources.food >= 2 && state.resources.meals < Math.max(6, state.colonists.filter(c => !c.dead).length * 2)) {
    add({ type: 'cook', workType: 'cook', buildingId: fire.id, targetId: fire.id, x: fire.x, y: fire.y, urgency: -15, duration: 6.5, label: 'Cooking' });
  }

  // Research.
  const desk = state.buildings.find(b => b.type === 'researchDesk' && b.complete);
  if (desk && state.researchActive && !state.completedResearch.includes(state.researchActive)) {
    add({ type: 'research', workType: 'research', buildingId: desk.id, targetId: desk.id, x: desk.x, y: desk.y, urgency: 10, duration: 15, label: 'Researching' });
  }

  // Crafting.
  const bench = state.buildings.find(b => (b.type === 'workbench' || b.type === 'forge') && b.complete);
  if (bench && state.resources.wood >= 4 && state.resources.silver < 160) {
    add({ type: 'craft', workType: 'craft', buildingId: bench.id, targetId: bench.id, x: bench.x, y: bench.y, urgency: 25, duration: 14, label: 'Crafting' });
  }

  // Doctor.
  const patient = state.colonists.find(v => !v.dead && !v.onExpedition && (v.bleeding > 0 || v.hp < v.maxHp * .7) && v.id !== '');
  if (patient) {
    add({ type: 'doctor', workType: 'doctor', patientId: patient.id, targetId: patient.id, x: patient.x, y: patient.y, urgency: -55, duration: 8, label: 'Healing' });
  }

  return jobs;
}

function findWorkSpot(state, x, y, def) {
  if (!def?.blocks && isWalkable(state, x, y)) return { x, y };
  return findAdjacentWalkable(state, x, y) || { x, y };
}

function startJob(state, c, job) {
  clearJob(state, c);
  const def = job.buildingId ? BUILDINGS[state.buildings.find(b => b.id === job.buildingId)?.type] : null;
  let spot;
  if (job.type === 'doctor') {
    const patient = state.colonists.find(v => v.id === job.patientId);
    spot = patient ? findAdjacentWalkable(state, Math.round(patient.x), Math.round(patient.y)) : null;
  } else if (job.type === 'gather') {
    spot = findAdjacentWalkable(state, job.x, job.y);
  } else {
    spot = findWorkSpot(state, job.x, job.y, def);
  }
  if (!spot) return;
  const path = findPath(state, Math.round(c.x), Math.round(c.y), spot.x, spot.y, 2600);
  if (!path) {
    if (c.job?.type !== 'idle') c.status = 'No path';
    return;
  }
  const skill = WORK_TYPES.find(w => w.id === job.workType)?.skill;
  const sk = skill ? c.skills[skill] || 1 : 4;
  job.phase = 'moving';
  job.progress = 0;
  job.duration = (job.duration || 7) * (1.15 - sk * .045);
  if (job.type === 'construct') {
    job.duration *= state.completedResearch.includes('stonecraft') ? .85 : 1;
    job.duration *= 1.15 - sk * .05;
  }
  job.startX = c.x; job.startY = c.y;
  c.job = job;
  c.path = path;
  c.pathIndex = 0;
  c.status = job.label || 'Working';
  if (job.type === 'plant') c.status = 'Sowing';
}

function moveAlongPath(state, c, dt, speedMult = 1) {
  if (!c.path || c.pathIndex >= c.path.length) return true;
  const speedTrait = c.traits.includes('sluggish') ? .88 : c.traits.includes('quick') ? 1.15 : 1;
  const speed = 2.15 * speedTrait * speedMult * dt;
  let remaining = speed;
  while (remaining > 0 && c.pathIndex < c.path.length) {
    const node = c.path[c.pathIndex];
    const dx = node.x - c.x, dy = node.y - c.y;
    const d = Math.hypot(dx, dy);
    if (d <= remaining) {
      c.x = node.x; c.y = node.y;
      c.pathIndex++;
      remaining -= d;
    } else {
      c.x += dx / d * remaining;
      c.y += dy / d * remaining;
      if (Math.abs(dx) > .05) c.facing = dx < 0 ? -1 : 1;
      remaining = 0;
    }
  }
  if (c.pathIndex >= c.path.length) { c.path = []; return true; }
  return false;
}

function updateWork(state, c, dt) {
  if (c.job.phase === 'moving') {
    c.status = c.job.type === 'construct' ? 'Building' : c.job.label || 'Working';
    if (moveAlongPath(state, c, dt)) c.job.phase = 'working';
    return;
  }
  const job = c.job;
  if (job.type === 'idle') {
    job.wait -= dt;
    c.status = c.breakTimer > 0 ? 'Despairing' : 'Wandering';
    if (job.wait <= 0) clearJob(state, c);
    return;
  }
  c.status = job.label || jobStatus(job);
  const skill = WORK_TYPES.find(w => w.id === job.workType)?.skill;
  const sk = skill ? c.skills[skill] || 1 : 4;
  job.progress += dt * (0.75 + sk * .04);
  if (job.type === 'sleep') return;
  if (job.progress < job.duration) return;

  switch (job.type) {
    case 'gather': completeGather(state, c, job); break;
    case 'construct': completeConstruct(state, c, job); break;
    case 'harvest': completeHarvest(state, c, job); break;
    case 'plant': completePlant(state, c, job); break;
    case 'cook': completeCook(state, c, job); break;
    case 'research': completeResearchWork(state, c, job); break;
    case 'craft': completeCraft(state, c, job); break;
    case 'doctor': completeDoctor(state, c, job); break;
  }
}

function jobStatus(job) {
  return {
    gather: job.label || 'Gathering', construct: 'Building', harvest: 'Harvesting',
    plant: 'Sowing', cook: 'Cooking', research: 'Researching', craft: 'Crafting',
    doctor: 'Healing', sleep: 'Sleeping', eat: 'Eating', idle: 'Wandering', fight: 'Fighting',
  }[job.type] || 'Working';
}

function completeGather(state, c, job) {
  const f = state.features.find(v => v.id === job.featureId);
  if (!f || f.amount <= 0) { clearJob(state, c); return; }
  const sk = c.skills[job.workType === 'chop' ? 'survival' : 'mining'] || 3;
  const take = Math.min(f.amount, 3 + Math.floor(sk / 2) + Math.floor(Math.random() * 3));
  f.amount -= take;
  const res = f.type === 'tree' ? 'wood' : f.type === 'rock' || f.type === 'ruinStone' ? 'stone' : f.type === 'crystal' ? 'crystal' : 'food';
  addResource(state, res, take, true);
  state.stats.gathered += take;
  state.dirty = true;
  c.skills[job.workType === 'chop' ? 'survival' : 'mining'] = Math.min(10, sk + .05);
  addFloat(state, f.x, f.y - .8, `+${take}`, res === 'wood' ? '#c7a56c' : res === 'stone' ? '#b8b0a0' : res === 'crystal' ? '#c79ae8' : '#9db078');
  spawnParticles(state, f.x, f.y - .3, 7, res === 'wood' ? ['#7a633d', '#ad8b50', '#5e633d'] : res === 'crystal' ? ['#a27dc4', '#d0b7e8'] : ['#8e8878', '#c2bbaa'], { speed: 1, life: .6, size: 1.5, gravity: .9 });
  if (f.amount <= 0) {
    state.featureIndex.delete(key(f.x, f.y));
    state.features = state.features.filter(v => v.id !== f.id);
  }
  clearJob(state, c);
}

function completeConstruct(state, c, job) {
  const b = state.buildings.find(v => v.id === job.buildingId);
  if (!b) { clearJob(state, c); return; }
  b.complete = true;
  b.progress = 100;
  state.stats.built++;
  const def = BUILDINGS[b.type];
  spawnParticles(state, b.x + b.w / 2, b.y + b.h / 2, 15, ['#c9a15c', '#e6d4ae', '#8c7b5b'], { speed: 1.3, life: .8, size: 1.6, gravity: .7 });
  addFloat(state, b.x + .5, b.y, def.name, '#e9c987');
  if (b.type === 'shrine') {
    logEvent(state, '<strong>The waystone shrine is restored.</strong> The air tastes of rain and old metal.', '◈', 'epic');
    showBanner(state, 'The Ward Restored', 'The waystone answers. Somewhere below, something ancient turns in its sleep.', 'Colony Milestone');
  } else {
    logEvent(state, `${def.name} completed.`, '⌂', 'good');
  }
  checkQuests(state);
  clearJob(state, c);
}

function completeHarvest(state, c, job) {
  const b = state.buildings.find(v => v.id === job.buildingId);
  if (!b) { clearJob(state, c); return; }
  const bonus = state.completedResearch.includes('agriculture') ? 1.35 : 1;
  const amount = Math.round((7 + Math.random() * 5) * bonus * (0.85 + (c.skills.plants || 3) * .025));
  addResource(state, 'food', amount, true);
  b.crop = 0;
  b.harvests = (b.harvests || 0) + 1;
  addFloat(state, b.x, b.y - .6, `+${amount} food`, '#a8b981');
  spawnParticles(state, b.x, b.y, 10, ['#c7b36d', '#8fa35f', '#e0c26f'], { speed: 1, life: .7, size: 1.4, gravity: .8 });
  c.skills.plants = Math.min(10, (c.skills.plants || 1) + .08);
  state.dirty = true;
  clearJob(state, c);
}

function completePlant(state, c, job) {
  const b = state.buildings.find(v => v.id === job.buildingId);
  if (!b) { clearJob(state, c); return; }
  b.crop = .06;
  addFloat(state, b.x, b.y - .5, 'Sown', '#a8b981');
  state.dirty = true;
  clearJob(state, c);
}

function completeCook(state, c, job) {
  if (state.resources.food < 2) { clearJob(state, c); return; }
  state.resources.food -= 2;
  const meals = 2 + (c.skills.cooking > 7 ? 2 : 1);
  addResource(state, 'meals', meals, true);
  state.stats.mealsCooked += meals;
  addFloat(state, c.x, c.y - .9, `+${meals} meals`, '#e9c987');
  spawnParticles(state, c.x, c.y - .4, 8, ['#d9a95b', '#f0d494', '#9a6d3c'], { speed: .7, life: .7, size: 1.3, gravity: -.1, lift: .2 });
  c.skills.cooking = Math.min(10, (c.skills.cooking || 1) + .07);
  state.dirty = true;
  clearJob(state, c);
}

function completeResearchWork(state, c, job) {
  const gain = 2.2 + (c.skills.research || 1) * .85 + Math.random() * 1.2;
  addResearch(state, gain);
  addFloat(state, c.x, c.y - .8, `+${Math.round(gain)}`, '#c79ae8');
  spawnParticles(state, c.x, c.y - .4, 5, ['#a27dc4', '#d0b7e8', '#7f8fb3'], { speed: .6, life: .8, size: 1.2, gravity: -.2, lift: .1 });
  c.skills.research = Math.min(10, (c.skills.research || 1) + .06);
  state.dirty = true;
  clearJob(state, c);
}

function completeCraft(state, c, job) {
  if (state.resources.wood < 4) { clearJob(state, c); return; }
  state.resources.wood -= 4;
  const silver = 4 + Math.floor((c.skills.crafting || 3) * .9);
  addResource(state, 'silver', silver, true);
  addFloat(state, c.x, c.y - .8, `+${silver} silver`, '#e9c987');
  c.skills.crafting = Math.min(10, (c.skills.crafting || 1) + .08);
  state.dirty = true;
  clearJob(state, c);
}

function completeDoctor(state, c, job) {
  const patient = state.colonists.find(v => v.id === job.patientId);
  if (!patient || patient.dead) { clearJob(state, c); return; }
  const heal = 14 + (c.skills.medicine || 2) * 3.1;
  patient.hp = Math.min(patient.maxHp, patient.hp + heal);
  patient.bleeding = Math.max(0, patient.bleeding - 1.4);
  if (patient.downed) { patient.downed = false; patient.hp = Math.max(8, patient.hp); patient.status = 'Recovering'; }
  addFloat(state, patient.x, patient.y - .9, `+${Math.round(heal)}`, '#9eb080');
  spawnParticles(state, patient.x, patient.y - .3, 6, ['#9eb080', '#e6d4ae'], { speed: .5, life: .7, size: 1.2, gravity: -.1 });
  c.skills.medicine = Math.min(10, (c.skills.medicine || 1) + .07);
  state.dirty = true;
  clearJob(state, c);
}

function updateEnemies(state, dt) {
  for (const e of state.enemies) {
    if (e.dead) continue;
    const target = nearestColonist(state, e.x, e.y);
    if (!target) { e.idle = true; continue; }
    const d = dist(e.x, e.y, target.x, target.y);
    e.facing = target.x < e.x ? -1 : 1;
    if (d > e.range * .9) {
      e.pathTimer -= dt;
      if (e.pathTimer <= 0) {
        e.pathTimer = .8 + Math.random() * .5;
        const spot = findAdjacentWalkable(state, Math.round(target.x), Math.round(target.y));
        if (spot) {
          const path = findPath(state, Math.round(e.x), Math.round(e.y), spot.x, spot.y, 1900);
          if (path) { e.path = path; e.pathIndex = 0; }
        }
      }
      if (e.path?.length) {
        const node = e.path[e.pathIndex];
        if (!node) { e.path = []; continue; }
        const dx = node.x - e.x, dy = node.y - e.y;
        const len = Math.hypot(dx, dy);
        const step = e.speed * dt;
        if (len <= step) { e.x = node.x; e.y = node.y; e.pathIndex++; }
        else { e.x += dx / len * step; e.y += dy / len * step; }
      } else {
        e.x += (target.x - e.x) / (d || 1) * e.speed * dt * .4;
        e.y += (target.y - e.y) / (d || 1) * e.speed * dt * .4;
      }
    } else if (e.cooldown <= 0) {
      e.cooldown = 1.25 + Math.random() * .5;
      let dmg = range(Math.random, e.damage[0], e.damage[1]);
      if (state.completedResearch.includes('wards')) dmg *= .8;
      target.hp -= dmg;
      target.bleeding = Math.min(4, target.bleeding + .7);
      target.mood = Math.max(0, target.mood - 2);
      addFloat(state, target.x, target.y - .9, `-${Math.round(dmg)}`, '#d27a64');
      spawnParticles(state, target.x, target.y - .3, 5, ['#8d3c31', '#b25343'], { speed: .8, life: .5, size: 1.4, gravity: 1 });
      if (target.hp <= 0) downColonist(state, target, `struck down by a ${e.name}`);
      else if (Math.random() < .15) logEvent(state, `<strong>${target.name}</strong> is wounded by a ${e.name}.`, '⚔', 'bad');
    }
  }
  state.enemies = state.enemies.filter(e => !e.dead || e.hitFlash > 0);
}

function updateProjectiles(state, dt) {
  for (const p of state.projectiles) {
    p.life -= dt;
    const target = state.enemies.find(e => e.id === p.targetId && !e.dead);
    if (target) { p.tx = target.x; p.ty = target.y - .15; }
    const dx = p.tx - p.x, dy = p.ty - p.y;
    const d = Math.hypot(dx, dy);
    const step = p.speed * dt;
    if (d <= step || d < .2) {
      if (target) hurtEnemy(state, target, p.damage, state.colonists.find(c => c.job?.type === 'fight' && c.job.targetId === target.id) || null);
      spawnParticles(state, p.tx, p.ty, 4, [p.color, '#e6d4ae'], { speed: .6, life: .4, size: 1.2 });
      p.life = 0;
    } else {
      p.x += dx / d * step;
      p.y += dy / d * step;
    }
  }
  state.projectiles = state.projectiles.filter(p => p.life > 0);
}

function updateFloats(state, dt) {
  // Floats are aged in updateVisuals; kept for symmetry.
}

export function getStatus(state) {
  const alive = state.colonists.filter(c => !c.dead).length;
  const threat = state.enemies.filter(e => !e.dead).length;
  return { alive, threat };
}

export function getProgress(state, building) {
  if (building.complete) return 1;
  const def = BUILDINGS[building.type];
  return clamp((building.progress || 0) / 100, 0, 1);
}

export function selectedEntity(state) {
  if (!state.selected) return null;
  if (state.selected.kind === 'colonist') return state.colonists.find(c => c.id === state.selected.id) || null;
  if (state.selected.kind === 'building') return state.buildings.find(b => b.id === state.selected.id) || null;
  if (state.selected.kind === 'enemy') return state.enemies.find(e => e.id === state.selected.id) || null;
  return null;
}

import { BUILDINGS, CLASSES, RACES, SEASONS, TERRAIN, TERRAIN_INFO, TRAITS } from './content.js';

const TILE_BASE = 32;
const hash = (x, y) => {
  let h = x * 374761393 + y * 668265263;
  h = (h ^ (h >> 13)) * 1274126177;
  return ((h ^ (h >> 16)) >>> 0) / 4294967296;
};
const lerp = (a, b, t) => a + (b - a) * t;

export function createRenderer(canvas, state) {
  const ctx = canvas.getContext('2d');
  const cam = { x: state.world.campX + 1, y: state.world.campY, zoom: 1.15, targetZoom: 1.15 };
  let W = 0, H = 0, dpr = 1;
  let last = performance.now();
  let rainSeeds = Array.from({ length: 180 }, () => ({
    x: Math.random(), y: Math.random(), l: .012 + Math.random() * .02, s: .5 + Math.random() * .8,
  }));
  let fireflies = Array.from({ length: 42 }, () => ({
    x: Math.random(), y: Math.random(), p: Math.random() * 6.28, s: .1 + Math.random() * .3,
  }));
  let minimapState = null;

  function resize() {
    dpr = Math.min(2, window.devicePixelRatio || 1);
    W = window.innerWidth; H = window.innerHeight;
    canvas.width = Math.floor(W * dpr);
    canvas.height = Math.floor(H * dpr);
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    if (!resize.done) {
      cam.zoom = cam.targetZoom = W < 700 ? .78 : W < 1100 ? .98 : 1.16;
      resize.done = true;
    }
  }
  resize();

  function tilePx() { return TILE_BASE * cam.zoom; }
  function worldToScreen(x, y) {
    const t = tilePx();
    return { x: (x - cam.x) * t + W / 2, y: (y - cam.y) * t + H / 2 };
  }
  function screenToWorld(sx, sy) {
    const t = tilePx();
    return { x: (sx - W / 2) / t + cam.x, y: (sy - H / 2) / t + cam.y };
  }
  function centerOn(x, y, instant = false) {
    if (instant) { cam.x = x; cam.y = y; }
    else { cam.x = lerp(cam.x, x, .15); cam.y = lerp(cam.y, y, .15); }
  }

  function draw(now) {
    const dt = Math.min(.05, (now - last) / 1000);
    last = now;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    cam.zoom += (cam.targetZoom - cam.zoom) * .12;
    drawBackdrop();
    drawTerrain();
    drawGridHints();
    drawBuildings(false);
    drawFeatures();
    drawBuildings(true);
    drawProjectiles();
    drawColonists();
    drawEnemies();
    drawParticles();
    drawFloats();
    drawLighting();
    drawWeather();
    drawSelectionAndGhost();
    drawHudHints();
    drawMinimap();
    return { cam, W, H, tilePx: tilePx() };
  }

  function drawBackdrop() {
    ctx.fillStyle = '#10130f';
    ctx.fillRect(0, 0, W, H);
  }

  function visibleBounds() {
    const t = tilePx();
    const x0 = Math.max(0, Math.floor(cam.x - W / 2 / t) - 2);
    const y0 = Math.max(0, Math.floor(cam.y - H / 2 / t) - 2);
    const x1 = Math.min(state.world.w, Math.ceil(cam.x + W / 2 / t) + 2);
    const y1 = Math.min(state.world.h, Math.ceil(cam.y + H / 2 / t) + 2);
    return { x0, y0, x1, y1 };
  }

  function terrainColor(t, x, y) {
    const v = hash(x, y);
    const v2 = state.world.variant[y * state.world.w + x] / 255;
    switch (t) {
      case TERRAIN.GRASS: return shade('#52613e', (v - .5) * .11 + (v2 - .5) * .05);
      case TERRAIN.FOREST: return shade('#445236', (v - .5) * .12);
      case TERRAIN.DIRT: return shade('#68533a', (v - .5) * .13);
      case TERRAIN.WATER: return shade('#2f4d55', (v - .5) * .08);
      case TERRAIN.MOUNTAIN: return shade('#4a4841', (v - .5) * .14);
      case TERRAIN.SAND: return shade('#75694d', (v - .5) * .1);
      case TERRAIN.RUIN: return shade('#59564b', (v - .5) * .12);
      case TERRAIN.FARM: return shade('#5c452e', (v - .5) * .1);
      default: return '#4d573b';
    }
  }

  function drawTerrain() {
    const t = tilePx();
    const { x0, y0, x1, y1 } = visibleBounds();
    const time = state.simTime + performance.now() / 1000;
    for (let y = y0; y < y1; y++) {
      for (let x = x0; x < x1; x++) {
        const terrain = state.world.tiles[y * state.world.w + x];
        const sx = (x - cam.x) * t + W / 2;
        const sy = (y - cam.y) * t + H / 2;
        ctx.fillStyle = terrainColor(terrain, x, y);
        ctx.fillRect(Math.floor(sx), Math.floor(sy), Math.ceil(t + 1), Math.ceil(t + 1));

        if (terrain === TERRAIN.WATER) {
          const wob = Math.sin(time * 1.4 + x * .7 + y * .5) * t * .08;
          ctx.strokeStyle = `rgba(150,190,193,${.10 + hash(x, y) * .06})`;
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(sx + t * .16, sy + t * .4 + wob);
          ctx.quadraticCurveTo(sx + t * .45, sy + t * .33 - wob, sx + t * .78, sy + t * .44 + wob);
          ctx.stroke();
          if (hash(x + 3, y + 8) > .55) {
            ctx.strokeStyle = 'rgba(205,224,215,.11)';
            ctx.beginPath();
            ctx.moveTo(sx + t * .2, sy + t * .7);
            ctx.lineTo(sx + t * .48, sy + t * .68);
            ctx.stroke();
          }
        } else if (terrain === TERRAIN.GRASS) {
          if (hash(x + 5, y + 9) > .52) {
            ctx.strokeStyle = 'rgba(174,187,121,.14)';
            ctx.lineWidth = .8;
            const ox = hash(x, y + 4) * t * .7 + t * .12;
            const oy = hash(x + 9, y) * t * .7 + t * .12;
            ctx.beginPath();
            ctx.moveTo(sx + ox, sy + oy + t * .13);
            ctx.lineTo(sx + ox + t * .03, sy + oy);
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(sx + ox + t * .04, sy + oy + t * .13);
            ctx.lineTo(sx + ox + t * .08, sy + oy + t * .02);
            ctx.stroke();
          }
          if (hash(x + 12, y + 22) > .82) {
            ctx.fillStyle = 'rgba(201,183,123,.42)';
            ctx.beginPath();
            ctx.arc(sx + t * .65, sy + t * .3, 1.2, 0, 7);
            ctx.fill();
          }
        } else if (terrain === TERRAIN.DIRT) {
          ctx.fillStyle = 'rgba(30,22,15,.12)';
          if (hash(x + 2, y + 5) > .48) ctx.fillRect(sx + t * .2, sy + t * .6, t * .06, t * .03);
          if (hash(x + 7, y + 1) > .66) ctx.fillRect(sx + t * .67, sy + t * .32, t * .05, t * .04);
        } else if (terrain === TERRAIN.MOUNTAIN) {
          ctx.fillStyle = 'rgba(196,190,168,.08)';
          ctx.beginPath();
          ctx.moveTo(sx + t * .16, sy + t * .76);
          ctx.lineTo(sx + t * .45, sy + t * .16);
          ctx.lineTo(sx + t * .7, sy + t * .7);
          ctx.closePath();
          ctx.fill();
          ctx.strokeStyle = 'rgba(24,24,22,.18)';
          ctx.beginPath();
          ctx.moveTo(sx + t * .45, sy + t * .16);
          ctx.lineTo(sx + t * .4, sy + t * .7);
          ctx.stroke();
        } else if (terrain === TERRAIN.RUIN) {
          ctx.strokeStyle = 'rgba(28,26,21,.2)';
          ctx.lineWidth = 1;
          if (hash(x, y) > .4) {
            ctx.beginPath();
            ctx.moveTo(sx + t * .1, sy + t * .15);
            ctx.lineTo(sx + t * .1, sy + t * .85);
            ctx.stroke();
          }
          if (hash(x + 4, y + 3) > .55) {
            ctx.beginPath();
            ctx.moveTo(sx + t * .3, sy + t * .8);
            ctx.lineTo(sx + t * .73, sy + t * .8);
            ctx.stroke();
          }
        } else if (terrain === TERRAIN.FARM) {
          ctx.strokeStyle = 'rgba(37,27,17,.35)';
          for (let i = 1; i < 4; i++) {
            ctx.beginPath();
            ctx.moveTo(sx + t * .08, sy + t * i / 4);
            ctx.lineTo(sx + t * .92, sy + t * i / 4);
            ctx.stroke();
          }
        }
        // Subtle transitions.
        if (x > 0) {
          const left = state.world.tiles[y * state.world.w + x - 1];
          if (left !== terrain) {
            ctx.fillStyle = terrainColor(left, x - 1, y);
            ctx.globalAlpha = .16;
            ctx.fillRect(sx, sy, 2, t);
            ctx.globalAlpha = 1;
          }
        }
      }
    }
    // Map border.
    const c0 = worldToScreen(0, 0), c1 = worldToScreen(state.world.w, state.world.h);
    ctx.strokeStyle = 'rgba(201,161,92,.14)';
    ctx.lineWidth = 2;
    ctx.strokeRect(c0.x, c0.y, c1.x - c0.x, c1.y - c0.y);
  }

  function drawGridHints() {
    if (!state.buildMode && !state.hover) return;
    const t = tilePx();
    if (state.buildMode) {
      const { x0, y0, x1, y1 } = visibleBounds();
      ctx.strokeStyle = 'rgba(230,212,174,.025)';
      ctx.lineWidth = .5;
      for (let x = x0; x < x1; x++) {
        const sx = (x - cam.x) * t + W / 2;
        ctx.beginPath(); ctx.moveTo(sx, y0 * t - cam.y * t + H / 2); ctx.lineTo(sx, y1 * t - cam.y * t + H / 2); ctx.stroke();
      }
      for (let y = y0; y < y1; y++) {
        const sy = (y - cam.y) * t + H / 2;
        ctx.beginPath(); ctx.moveTo(x0 * t - cam.x * t + W / 2, sy); ctx.lineTo(x1 * t - cam.x * t + W / 2, sy); ctx.stroke();
      }
    }
  }

  function drawFeatures() {
    const t = tilePx();
    const { x0, y0, x1, y1 } = visibleBounds();
    const time = state.simTime;
    const list = state.features.filter(f => f.x >= x0 && f.x <= x1 && f.y >= y0 && f.y <= y1).sort((a, b) => a.y - b.y);
    for (const f of list) {
      const sx = (f.x - cam.x) * t + W / 2;
      const sy = (f.y - cam.y) * t + H / 2;
      const sway = Math.sin(time * 1.2 + f.sway) * t * .025;
      if (f.marked) {
        ctx.strokeStyle = 'rgba(233,201,135,.7)';
        ctx.lineWidth = 1;
        const b = t * .09;
        ctx.beginPath();
        ctx.moveTo(sx + b, sy + 2); ctx.lineTo(sx + 2, sy + 2); ctx.lineTo(sx + 2, sy + b);
        ctx.moveTo(sx + t - b, sy + 2); ctx.lineTo(sx + t - 2, sy + 2); ctx.lineTo(sx + t - 2, sy + b);
        ctx.moveTo(sx + 2, sy + t - b); ctx.lineTo(sx + 2, sy + t - 2); ctx.lineTo(sx + b, sy + t - 2);
        ctx.moveTo(sx + t - b, sy + t - 2); ctx.lineTo(sx + t - 2, sy + t - 2); ctx.lineTo(sx + t - 2, sy + t - b);
        ctx.stroke();
      }
      switch (f.type) {
        case 'tree': drawTree(sx + sway, sy, t, f, time); break;
        case 'rock': drawRock(sx, sy, t, f); break;
        case 'bush': drawBush(sx + sway * .4, sy, t, f, time); break;
        case 'crystal': drawCrystal(sx, sy, t, f, time); break;
        case 'ruinStone': drawRuinStone(sx, sy, t, f); break;
        case 'grave': drawGrave(sx, sy, t); break;
        case 'waystone': drawWaystone(sx, sy, t, time); break;
      }
    }
  }

  function drawTree(sx, sy, t, f, time) {
    const s = f.size;
    const cx = sx + t * .5, base = sy + t * .83;
    ctx.fillStyle = 'rgba(10,14,10,.28)';
    ctx.beginPath(); ctx.ellipse(cx, base + t * .02, t * .28 * s, t * .09 * s, 0, 0, 7); ctx.fill();
    ctx.strokeStyle = '#3a2d1c';
    ctx.lineWidth = Math.max(1, t * .055 * s);
    ctx.beginPath(); ctx.moveTo(cx, base); ctx.lineTo(cx - t * .015, base - t * .28 * s); ctx.stroke();
    const shades = f.variant % 3 === 0 ? ['#364b31', '#435c39', '#526c40', '#607b47'] : f.variant % 3 === 1 ? ['#3d4d2e', '#4d6037', '#5c7040', '#6b7e47'] : ['#314831', '#3e573b', '#4d6745', '#5d794f'];
    const cy = base - t * .47 * s;
    const r = t * .25 * s;
    ctx.fillStyle = shades[0];
    ctx.beginPath(); ctx.arc(cx - r * .65, cy + r * .38, r * .83, 0, 7); ctx.fill();
    ctx.beginPath(); ctx.arc(cx + r * .68, cy + r * .33, r * .8, 0, 7); ctx.fill();
    ctx.fillStyle = shades[1];
    ctx.beginPath(); ctx.arc(cx, cy - r * .18, r * 1.05, 0, 7); ctx.fill();
    ctx.fillStyle = shades[2];
    ctx.beginPath(); ctx.arc(cx - r * .22, cy - r * .45, r * .68, 0, 7); ctx.fill();
    ctx.fillStyle = shades[3];
    ctx.beginPath(); ctx.arc(cx - r * .42, cy - r * .62, r * .29, 0, 7); ctx.fill();
    if (f.amount < f.max) {
      ctx.fillStyle = '#3d2f20';
      ctx.fillRect(cx - t * .06, base - t * .05, t * .12, t * .07);
    }
  }

  function drawRock(sx, sy, t, f) {
    const s = f.size;
    ctx.fillStyle = 'rgba(10,10,9,.28)';
    ctx.beginPath(); ctx.ellipse(sx + t * .5, sy + t * .8, t * .3 * s, t * .1, 0, 0, 7); ctx.fill();
    ctx.fillStyle = '#5a5850';
    ctx.beginPath();
    ctx.moveTo(sx + t * .17, sy + t * .75);
    ctx.lineTo(sx + t * .25, sy + t * .38);
    ctx.lineTo(sx + t * .48, sy + t * .2 * s + .12 * t);
    ctx.lineTo(sx + t * .77, sy + t * .33);
    ctx.lineTo(sx + t * .85, sy + t * .72);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#6d6b61';
    ctx.beginPath();
    ctx.moveTo(sx + t * .27, sy + t * .38);
    ctx.lineTo(sx + t * .48, sy + t * .22 * s + .12 * t);
    ctx.lineTo(sx + t * .67, sy + t * .41);
    ctx.lineTo(sx + t * .46, sy + t * .57);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(32,31,28,.35)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(sx + t * .48, sy + t * .22 * s + .12 * t); ctx.lineTo(sx + t * .44, sy + t * .7); ctx.stroke();
    if (f.amount < f.max) {
      ctx.fillStyle = '#45443d'; ctx.fillRect(sx + t * .32, sy + t * .72, t * .18, t * .05);
    }
  }

  function drawBush(sx, sy, t, f, time) {
    const s = f.size;
    const cx = sx + t * .5, cy = sy + t * .63;
    ctx.fillStyle = 'rgba(10,14,10,.2)';
    ctx.beginPath(); ctx.ellipse(cx, cy + t * .2, t * .25 * s, t * .07, 0, 0, 7); ctx.fill();
    ctx.fillStyle = '#435a34';
    for (let i = 0; i < 4; i++) {
      ctx.beginPath(); ctx.arc(cx + Math.cos(i * 1.7) * t * .12 * s, cy + Math.sin(i * 1.7) * t * .06, t * .16 * s, 0, 7); ctx.fill();
    }
    ctx.fillStyle = '#5d7441';
    ctx.beginPath(); ctx.arc(cx - t * .06, cy - t * .08, t * .13 * s, 0, 7); ctx.fill();
    if (f.amount > 0) {
      ctx.fillStyle = f.amount < f.max ? '#8b5a43' : '#b46f4e';
      for (let i = 0; i < 3; i++) {
        ctx.beginPath(); ctx.arc(cx + (i - 1) * t * .13, cy + (i % 2) * t * .08 - t * .03, Math.max(1, t * .028), 0, 7); ctx.fill();
      }
    }
  }

  function drawCrystal(sx, sy, t, f, time) {
    const s = f.size;
    const cx = sx + t * .5, base = sy + t * .78;
    const glow = .5 + Math.sin(time * 2 + f.sway) * .2;
    const grd = ctx.createRadialGradient(cx, base - t * .2, 1, cx, base - t * .2, t * .42);
    grd.addColorStop(0, `rgba(167,118,211,${.25 + glow * .12})`);
    grd.addColorStop(1, 'rgba(167,118,211,0)');
    ctx.fillStyle = grd;
    ctx.beginPath(); ctx.arc(cx, base - t * .2, t * .42, 0, 7); ctx.fill();
    for (let i = 0; i < 4; i++) {
      const ox = (i - 1.5) * t * .1 * s;
      const h = t * (.2 + (i % 2) * .12) * s;
      ctx.fillStyle = i % 2 ? '#9d72c0' : '#b78bd4';
      ctx.beginPath();
      ctx.moveTo(cx + ox, base);
      ctx.lineTo(cx + ox + t * .055, base - h);
      ctx.lineTo(cx + ox + t * .09, base);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = 'rgba(235,216,250,.5)';
      ctx.beginPath();
      ctx.moveTo(cx + ox + t * .055, base - h);
      ctx.lineTo(cx + ox + t * .07, base - h * .55);
      ctx.lineTo(cx + ox + t * .058, base - h * .35);
      ctx.closePath(); ctx.fill();
    }
  }

  function drawRuinStone(sx, sy, t, f) {
    ctx.fillStyle = '#666257';
    ctx.fillRect(sx + t * .22, sy + t * .3, t * .22, t * .48);
    ctx.fillStyle = '#777266';
    ctx.fillRect(sx + t * .55, sy + t * .44, t * .19, t * .34);
    ctx.strokeStyle = 'rgba(35,33,28,.4)';
    ctx.beginPath(); ctx.moveTo(sx + t * .3, sy + t * .38); ctx.lineTo(sx + t * .36, sy + t * .65); ctx.stroke();
  }

  function drawGrave(sx, sy, t) {
    ctx.fillStyle = 'rgba(10,10,9,.3)';
    ctx.beginPath(); ctx.ellipse(sx + t * .5, sy + t * .8, t * .2, t * .06, 0, 0, 7); ctx.fill();
    ctx.fillStyle = '#5b574d';
    ctx.beginPath();
    ctx.moveTo(sx + t * .34, sy + t * .78);
    ctx.lineTo(sx + t * .34, sy + t * .34);
    ctx.quadraticCurveTo(sx + t * .5, sy + t * .2, sx + t * .66, sy + t * .34);
    ctx.lineTo(sx + t * .66, sy + t * .78);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(201,161,92,.35)';
    ctx.beginPath(); ctx.moveTo(sx + t * .5, sy + t * .38); ctx.lineTo(sx + t * .5, sy + t * .62); ctx.moveTo(sx + t * .43, sy + t * .47); ctx.lineTo(sx + t * .57, sy + t * .47); ctx.stroke();
  }

  function drawWaystone(sx, sy, t, time) {
    const cx = sx + t * .5, base = sy + t * .8;
    const pulse = Math.sin(time * 1.6) * .15 + .55;
    const grd = ctx.createRadialGradient(cx, base - t * .35, 1, cx, base - t * .35, t * .6);
    grd.addColorStop(0, `rgba(167,118,211,${.2 * pulse})`);
    grd.addColorStop(1, 'rgba(167,118,211,0)');
    ctx.fillStyle = grd; ctx.beginPath(); ctx.arc(cx, base - t * .35, t * .6, 0, 7); ctx.fill();
    ctx.fillStyle = '#5e5b53';
    ctx.beginPath();
    ctx.moveTo(cx - t * .14, base);
    ctx.lineTo(cx - t * .1, sy + t * .22);
    ctx.lineTo(cx + t * .04, sy + t * .13);
    ctx.lineTo(cx + t * .13, sy + t * .3);
    ctx.lineTo(cx + t * .17, base);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = `rgba(180,137,220,${.4 + pulse * .4})`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(cx - t * .02, base - t * .14); ctx.lineTo(cx + t * .06, base - t * .28); ctx.lineTo(cx - t * .03, base - t * .4); ctx.lineTo(cx + t * .05, base - t * .53);
    ctx.stroke();
  }

  function drawBuildings(foreground) {
    const t = tilePx();
    const list = state.buildings.slice().sort((a, b) => (a.y + a.h) - (b.y + b.h));
    for (const b of list) {
      const def = BUILDINGS[b.type];
      const tall = ['wall', 'palisade', 'watchtower', 'forge', 'tent'].includes(b.type);
      if (foreground !== tall) continue;
      const sx = (b.x - cam.x) * t + W / 2;
      const sy = (b.y - cam.y) * t + H / 2;
      if (sx < -t * 6 || sy < -t * 8 || sx > W + t * 4 || sy > H + t * 4) continue;
      drawBuilding(b, def, sx, sy, t);
    }
  }

  function drawBuilding(b, def, sx, sy, t) {
    const w = b.w * t, h = b.h * t;
    if (!b.complete) {
      ctx.fillStyle = 'rgba(201,161,92,.055)';
      ctx.fillRect(sx + 2, sy + 2, w - 4, h - 4);
      ctx.strokeStyle = 'rgba(233,201,135,.58)';
      ctx.lineWidth = 1;
      ctx.setLineDash([5, 4]);
      ctx.strokeRect(sx + 3, sy + 3, w - 6, h - 6);
      ctx.setLineDash([]);
      // scaffolding
      ctx.strokeStyle = 'rgba(176,137,81,.55)';
      ctx.beginPath();
      ctx.moveTo(sx + w * .18, sy + h * .85); ctx.lineTo(sx + w * .18, sy + h * .2);
      ctx.moveTo(sx + w * .82, sy + h * .85); ctx.lineTo(sx + w * .82, sy + h * .2);
      ctx.moveTo(sx + w * .12, sy + h * .36); ctx.lineTo(sx + w * .88, sy + h * .36);
      ctx.stroke();
      ctx.fillStyle = 'rgba(14,11,8,.8)';
      ctx.fillRect(sx + w * .22, sy + h * .88, w * .56, Math.max(3, t * .11));
      const grd = ctx.createLinearGradient(sx, 0, sx + w, 0);
      grd.addColorStop(0, '#9d7947'); grd.addColorStop(1, '#e9c987');
      ctx.fillStyle = grd;
      ctx.fillRect(sx + w * .22, sy + h * .88, w * .56 * ((b.progress || 0) / 100), Math.max(3, t * .11));
      ctx.fillStyle = 'rgba(233,201,135,.9)';
      ctx.font = `${Math.max(7, t * .22)}px Georgia, serif`;
      ctx.textAlign = 'center';
      ctx.fillText(def.name, sx + w / 2, sy + h * .15);
      return;
    }
    ctx.save();
    switch (b.type) {
      case 'bed': {
        ctx.fillStyle = 'rgba(10,9,7,.3)';
        ctx.beginPath(); ctx.ellipse(sx + w * .5, sy + h * .82, w * .42, h * .09, 0, 0, 7); ctx.fill();
        ctx.fillStyle = '#4e3a26';
        ctx.fillRect(sx + w * .13, sy + h * .2, w * .74, h * .64);
        ctx.fillStyle = '#796044';
        ctx.fillRect(sx + w * .17, sy + h * .24, w * .66, h * .54);
        ctx.fillStyle = '#8e6d4c';
        ctx.fillRect(sx + w * .2, sy + h * .42, w * .6, h * .35);
        ctx.fillStyle = '#d2c39f';
        ctx.fillRect(sx + w * .22, sy + h * .27, w * .25, h * .17);
        ctx.strokeStyle = 'rgba(38,28,18,.45)';
        ctx.strokeRect(sx + w * .13, sy + h * .2, w * .74, h * .64);
        break;
      }
      case 'tent': {
        ctx.fillStyle = 'rgba(10,9,7,.3)';
        ctx.beginPath(); ctx.ellipse(sx + w * .5, sy + h * .88, w * .43, h * .08, 0, 0, 7); ctx.fill();
        ctx.fillStyle = '#726147';
        ctx.beginPath(); ctx.moveTo(sx + w * .5, sy + h * .08); ctx.lineTo(sx + w * .94, sy + h * .84); ctx.lineTo(sx + w * .06, sy + h * .84); ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#8b7856';
        ctx.beginPath(); ctx.moveTo(sx + w * .5, sy + h * .11); ctx.lineTo(sx + w * .78, sy + h * .8); ctx.lineTo(sx + w * .5, sy + h * .8); ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#1c1711';
        ctx.beginPath(); ctx.moveTo(sx + w * .5, sy + h * .35); ctx.lineTo(sx + w * .63, sy + h * .8); ctx.lineTo(sx + w * .37, sy + h * .8); ctx.closePath(); ctx.fill();
        ctx.strokeStyle = '#a28e68'; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.moveTo(sx + w * .5, sy + h * .06); ctx.lineTo(sx + w * .5, sy + h * .1); ctx.stroke();
        break;
      }
      case 'campfire': {
        const time = state.simTime + performance.now() / 1000;
        const cx = sx + w * .5, cy = sy + h * .63;
        const grd = ctx.createRadialGradient(cx, cy, t * .05, cx, cy, t * 2.2);
        grd.addColorStop(0, 'rgba(244,170,76,.32)');
        grd.addColorStop(.4, 'rgba(214,114,48,.1)');
        grd.addColorStop(1, 'rgba(214,114,48,0)');
        ctx.fillStyle = grd; ctx.beginPath(); ctx.arc(cx, cy, t * 2.2, 0, 7); ctx.fill();
        ctx.fillStyle = '#4e4a40';
        for (let i = 0; i < 7; i++) {
          const a = i / 7 * 6.28;
          ctx.beginPath(); ctx.arc(cx + Math.cos(a) * t * .24, cy + Math.sin(a) * t * .11, t * .045, 0, 7); ctx.fill();
        }
        ctx.strokeStyle = '#3a2a1b'; ctx.lineWidth = t * .06;
        ctx.beginPath(); ctx.moveTo(cx - t * .15, cy + t * .05); ctx.lineTo(cx + t * .15, cy - t * .06); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(cx - t * .13, cy - t * .06); ctx.lineTo(cx + t * .14, cy + t * .06); ctx.stroke();
        const flick = Math.sin(time * 12) * .04;
        ctx.fillStyle = '#d76b36';
        ctx.beginPath();
        ctx.moveTo(cx - t * .13, cy);
        ctx.quadraticCurveTo(cx - t * .18, cy - t * .25, cx + flick * t, cy - t * .6 - Math.sin(time * 6) * t * .06);
        ctx.quadraticCurveTo(cx + t * .18, cy - t * .22, cx + t * .13, cy);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#f2bd62';
        ctx.beginPath();
        ctx.moveTo(cx - t * .07, cy);
        ctx.quadraticCurveTo(cx - t * .08, cy - t * .2, cx + flick * t * .3, cy - t * .37);
        ctx.quadraticCurveTo(cx + t * .09, cy - t * .15, cx + t * .07, cy);
        ctx.closePath(); ctx.fill();
        break;
      }
      case 'stockpile': {
        ctx.fillStyle = 'rgba(10,9,7,.18)';
        ctx.fillRect(sx + 3, sy + 3, w - 6, h - 6);
        ctx.strokeStyle = 'rgba(194,162,104,.14)'; ctx.lineWidth = 1;
        ctx.strokeRect(sx + 4, sy + 4, w - 8, h - 8);
        for (let i = 0; i < 4; i++) {
          const bx = sx + t * (.18 + (i % 2) * .38);
          const by = sy + t * (.18 + Math.floor(i / 2) * .4);
          ctx.fillStyle = ['#6f5232', '#7d5e3a', '#5a452c', '#86653e'][i];
          ctx.fillRect(bx, by, t * .29, t * .27);
          ctx.strokeStyle = '#3e2d1b'; ctx.strokeRect(bx, by, t * .29, t * .27);
          ctx.strokeStyle = 'rgba(201,161,92,.35)';
          ctx.beginPath(); ctx.moveTo(bx, by + t * .13); ctx.lineTo(bx + t * .29, by + t * .13); ctx.stroke();
        }
        break;
      }
      case 'farm': {
        const crop = b.crop || 0;
        ctx.fillStyle = 'rgba(285,205,106,.03)';
        if (crop > .1) {
          ctx.strokeStyle = crop >= 1 ? '#c9b35c' : crop > .55 ? '#8f9b4f' : '#5f753f';
          ctx.lineWidth = Math.max(.8, t * .025);
          for (let row = 0; row < 3; row++) {
            const yy = sy + t * (.27 + row * .23);
            for (let i = 0; i < 4; i++) {
              const xx = sx + t * (.13 + i * .22);
              ctx.beginPath(); ctx.moveTo(xx, yy + t * .05); ctx.lineTo(xx + t * .02, yy - t * .1 * crop); ctx.stroke();
              if (crop > .55) {
                ctx.fillStyle = crop >= 1 ? '#dec56d' : '#a8b34f';
                ctx.beginPath(); ctx.arc(xx + t * .02, yy - t * .1 * crop, Math.max(1, t * .025), 0, 7); ctx.fill();
              }
            }
          }
        }
        break;
      }
      case 'workbench': {
        ctx.fillStyle = '#4d3823';
        ctx.fillRect(sx + t * .12, sy + t * .34, t * .76, t * .19);
        ctx.fillStyle = '#6d5030';
        ctx.fillRect(sx + t * .16, sy + t * .37, t * .68, t * .11);
        ctx.fillStyle = '#3d2b1b';
        ctx.fillRect(sx + t * .2, sy + t * .53, t * .07, t * .3);
        ctx.fillRect(sx + t * .73, sy + t * .53, t * .07, t * .3);
        ctx.strokeStyle = '#a8a09a'; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.moveTo(sx + t * .62, sy + t * .34); ctx.lineTo(sx + t * .7, sy + t * .22); ctx.stroke();
        ctx.fillStyle = '#7f817a';
        ctx.beginPath(); ctx.moveTo(sx + t * .67, sy + t * .29); ctx.lineTo(sx + t * .76, sy + t * .35); ctx.lineTo(sx + t * .67, sy + t * .37); ctx.closePath(); ctx.fill();
        break;
      }
      case 'researchDesk': {
        ctx.fillStyle = '#4b3825';
        ctx.fillRect(sx + t * .1, sy + t * .33, t * .8, t * .17);
        ctx.fillStyle = '#6f5437';
        ctx.fillRect(sx + t * .14, sy + t * .35, t * .72, t * .1);
        ctx.fillStyle = '#3b2a1a';
        ctx.fillRect(sx + t * .18, sy + t * .5, t * .05, t * .32);
        ctx.fillRect(sx + t * .77, sy + t * .5, t * .05, t * .32);
        ctx.fillStyle = '#c8bd9d';
        ctx.beginPath(); ctx.moveTo(sx + t * .36, sy + t * .35); ctx.lineTo(sx + t * .48, sy + t * .35); ctx.lineTo(sx + t * .45, sy + t * .27); ctx.lineTo(sx + t * .34, sy + t * .27); ctx.closePath(); ctx.fill();
        const pulse = .7 + Math.sin(state.simTime * 2) * .2;
        ctx.fillStyle = `rgba(167,118,211,${pulse})`;
        ctx.beginPath(); ctx.arc(sx + t * .65, sy + t * .27, t * .045, 0, 7); ctx.fill();
        ctx.fillStyle = `rgba(167,118,211,.15)`;
        ctx.beginPath(); ctx.arc(sx + t * .65, sy + t * .27, t * .15, 0, 7); ctx.fill();
        break;
      }
      case 'palisade': {
        ctx.fillStyle = 'rgba(10,9,7,.25)';
        ctx.fillRect(sx + t * .1, sy + t * .7, t * .8, t * .12);
        for (let i = 0; i < 4; i++) {
          const xx = sx + t * (.14 + i * .2);
          ctx.fillStyle = i % 2 ? '#5e4329' : '#6d4f30';
          ctx.beginPath();
          ctx.moveTo(xx, sy + t * .86);
          ctx.lineTo(xx + t * .03, sy + t * .12);
          ctx.lineTo(xx + t * .16, sy + t * .06);
          ctx.lineTo(xx + t * .19, sy + t * .86);
          ctx.closePath(); ctx.fill();
          ctx.strokeStyle = 'rgba(36,24,13,.5)'; ctx.stroke();
        }
        ctx.fillStyle = '#49331f';
        ctx.fillRect(sx + t * .08, sy + t * .39, t * .84, t * .06);
        break;
      }
      case 'watchtower': {
        ctx.fillStyle = 'rgba(10,9,7,.3)';
        ctx.beginPath(); ctx.ellipse(sx + w * .5, sy + h * .9, w * .38, h * .06, 0, 0, 7); ctx.fill();
        ctx.fillStyle = '#4b3926';
        ctx.fillRect(sx + w * .16, sy + h * .3, w * .12, h * .55);
        ctx.fillRect(sx + w * .72, sy + h * .3, w * .12, h * .55);
        ctx.fillStyle = '#6b4f33';
        ctx.fillRect(sx + w * .08, sy + h * .2, w * .84, h * .14);
        ctx.fillRect(sx + w * .12, sy + h * .5, w * .76, h * .08);
        ctx.fillStyle = '#3b2a1c';
        ctx.fillRect(sx + w * .3, sy + h * .53, w * .4, h * .3);
        ctx.fillStyle = 'rgba(233,201,135,.2)';
        ctx.beginPath(); ctx.arc(sx + w * .5, sy + h * .62, w * .12, 0, 7); ctx.fill();
        ctx.strokeStyle = '#87795e'; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.moveTo(sx + w * .5, sy + h * .2); ctx.lineTo(sx + w * .5, sy + h * .05); ctx.stroke();
        break;
      }
      case 'infirmary': {
        ctx.fillStyle = '#5b4a33';
        ctx.fillRect(sx + t * .13, sy + t * .24, t * .74, t * .58);
        ctx.fillStyle = '#b9ad8d';
        ctx.fillRect(sx + t * .17, sy + t * .28, t * .66, t * .5);
        ctx.fillStyle = '#d5c8a6';
        ctx.fillRect(sx + t * .22, sy + t * .32, t * .2, t * .13);
        ctx.fillStyle = '#8e3d35';
        ctx.fillRect(sx + t * .55, sy + t * .48, t * .16, t * .05);
        ctx.fillRect(sx + t * .605, sy + t * .425, t * .05, t * .16);
        break;
      }
      case 'forge': {
        ctx.fillStyle = 'rgba(10,9,7,.3)';
        ctx.fillRect(sx + w * .1, sy + h * .72, w * .8, h * .16);
        ctx.fillStyle = '#56524a';
        ctx.fillRect(sx + w * .12, sy + h * .3, w * .3, h * .52);
        ctx.fillStyle = '#68635a';
        ctx.fillRect(sx + w * .16, sy + h * .26, w * .22, h * .08);
        ctx.fillStyle = '#2f2c28';
        ctx.beginPath(); ctx.arc(sx + w * .27, sy + h * .58, w * .09, 0, 7); ctx.fill();
        const fire = .55 + Math.sin(state.simTime * 7) * .15;
        ctx.fillStyle = `rgba(235,123,57,${fire})`;
        ctx.beginPath(); ctx.arc(sx + w * .27, sy + h * .58, w * .055, 0, 7); ctx.fill();
        ctx.fillStyle = '#493a2a';
        ctx.fillRect(sx + w * .52, sy + h * .53, w * .32, h * .09);
        ctx.fillRect(sx + w * .56, sy + h * .62, w * .06, h * .2);
        ctx.fillRect(sx + w * .74, sy + h * .62, w * .06, h * .2);
        break;
      }
      case 'shrine': {
        const pulse = .55 + Math.sin(state.simTime * 1.8) * .22;
        const cx = sx + w / 2, cy = sy + h / 2;
        const grd = ctx.createRadialGradient(cx, cy, 2, cx, cy, w * .65);
        grd.addColorStop(0, `rgba(167,118,211,${.24 * pulse})`);
        grd.addColorStop(1, 'rgba(167,118,211,0)');
        ctx.fillStyle = grd; ctx.beginPath(); ctx.arc(cx, cy, w * .65, 0, 7); ctx.fill();
        ctx.strokeStyle = '#77736a'; ctx.lineWidth = Math.max(2, t * .08);
        ctx.beginPath(); ctx.ellipse(cx, cy + h * .18, w * .4, h * .24, 0, 0, 7); ctx.stroke();
        for (let i = 0; i < 6; i++) {
          const a = i / 6 * 6.28 + state.simTime * .08;
          ctx.fillStyle = i % 2 ? '#716d63' : '#858076';
          ctx.fillRect(cx + Math.cos(a) * w * .43 - t * .06, cy + Math.sin(a) * h * .28 - t * .2, t * .12, t * .35);
        }
        ctx.fillStyle = '#8b8679';
        ctx.beginPath(); ctx.moveTo(cx - w * .12, cy + h * .25); ctx.lineTo(cx - w * .06, cy - h * .28); ctx.lineTo(cx + w * .04, cy - h * .34); ctx.lineTo(cx + w * .12, cy - h * .2); ctx.lineTo(cx + w * .16, cy + h * .25); ctx.closePath(); ctx.fill();
        ctx.strokeStyle = `rgba(176,131,214,${.4 + pulse * .4})`; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.moveTo(cx, cy + h * .15); ctx.lineTo(cx + w * .02, cy - h * .02); ctx.lineTo(cx - w * .03, cy - h * .13); ctx.lineTo(cx + w * .03, cy - h * .26); ctx.stroke();
        break;
      }
      case 'herbGarden': {
        ctx.fillStyle = 'rgba(32,24,15,.18)'; ctx.fillRect(sx + 3, sy + 3, w - 6, h - 6);
        for (let i = 0; i < 6; i++) {
          const xx = sx + t * (.22 + (i % 3) * .26);
          const yy = sy + t * (.3 + Math.floor(i / 3) * .34);
          ctx.strokeStyle = '#617544'; ctx.beginPath(); ctx.moveTo(xx, yy + t * .12); ctx.lineTo(xx, yy); ctx.stroke();
          ctx.fillStyle = i % 2 ? '#7b9259' : '#677e4b';
          ctx.beginPath(); ctx.arc(xx - 2, yy, t * .05, 0, 7); ctx.arc(xx + 2, yy - 2, t * .045, 0, 7); ctx.fill();
        }
        break;
      }
      case 'runeWard': {
        const pulse = .4 + Math.sin(state.simTime * 3) * .25;
        ctx.strokeStyle = `rgba(167,118,211,${pulse + .2})`; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.arc(sx + w / 2, sy + h / 2, w * .3, 0, 7); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(sx + w / 2, sy + h * .2); ctx.lineTo(sx + w * .78, sy + h * .7); ctx.lineTo(sx + w * .22, sy + h * .7); ctx.closePath(); ctx.stroke();
        ctx.fillStyle = `rgba(167,118,211,${pulse})`; ctx.beginPath(); ctx.arc(sx + w / 2, sy + h / 2, t * .04, 0, 7); ctx.fill();
        break;
      }
      case 'well': {
        ctx.fillStyle = '#514d45';
        ctx.beginPath(); ctx.ellipse(sx + w * .5, sy + h * .72, w * .3, h * .13, 0, 0, 7); ctx.fill();
        ctx.fillStyle = '#2a3435';
        ctx.beginPath(); ctx.ellipse(sx + w * .5, sy + h * .67, w * .22, h * .09, 0, 0, 7); ctx.fill();
        ctx.strokeStyle = '#5f4930'; ctx.lineWidth = t * .06;
        ctx.beginPath(); ctx.moveTo(sx + w * .2, sy + h * .65); ctx.lineTo(sx + w * .2, sy + h * .22); ctx.lineTo(sx + w * .8, sy + h * .22); ctx.lineTo(sx + w * .8, sy + h * .65); ctx.stroke();
        ctx.fillStyle = '#6d5536';
        ctx.beginPath(); ctx.moveTo(sx + w * .14, sy + h * .24); ctx.lineTo(sx + w * .5, sy + h * .06); ctx.lineTo(sx + w * .86, sy + h * .24); ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#94774c';
        ctx.fillRect(sx + w * .46, sy + h * .3, w * .08, h * .15);
        break;
      }
    }
    ctx.restore();
    if (b.type !== 'farm' && b.type !== 'stockpile' && b.type !== 'runeWard') {
      ctx.fillStyle = 'rgba(233,201,135,.35)';
      ctx.font = `${Math.max(6, t * .16)}px Georgia, serif`;
      ctx.textAlign = 'center';
      // Only labels when zoomed in and selected.
      if (state.selected?.id === b.id) ctx.fillText(def.name, sx + w / 2, sy - 5);
    }
  }

  function drawColonists() {
    const t = tilePx();
    const list = state.colonists.filter(c => !c.onExpedition).sort((a, b) => a.y - b.y);
    for (const c of list) {
      if (c.dead) continue;
      const sx = (c.x - cam.x) * t + W / 2;
      const sy = (c.y - cam.y) * t + H / 2;
      if (sx < -t * 2 || sy < -t * 2 || sx > W + t * 2 || sy > H + t * 2) continue;
      const selected = state.selected?.kind === 'colonist' && state.selected.id === c.id;
      const bob = c.job?.phase === 'moving' ? Math.sin(c.movePhase) * t * .025 : 0;
      ctx.save();
      ctx.translate(sx, sy + bob);
      // shadow
      ctx.fillStyle = 'rgba(8,8,6,.32)';
      ctx.beginPath(); ctx.ellipse(0, t * .29, t * .2, t * .07, 0, 0, 7); ctx.fill();
      if (c.downed) {
        ctx.rotate(-Math.PI / 2);
        drawPawn(c, t, true);
      } else {
        drawPawn(c, t, false);
      }
      ctx.restore();

      if (selected) {
        ctx.strokeStyle = 'rgba(233,201,135,.85)';
        ctx.lineWidth = 1.2;
        ctx.setLineDash([4, 4]);
        ctx.beginPath(); ctx.ellipse(sx, sy + t * .27, t * .28, t * .11, 0, 0, 7); ctx.stroke();
        ctx.setLineDash([]);
        ctx.strokeStyle = 'rgba(233,201,135,.16)';
        ctx.beginPath(); ctx.ellipse(sx, sy + t * .27, t * .38, t * .15, 0, 0, 7); ctx.stroke();
      }
      // name
      if (cam.zoom > .82) {
        ctx.font = `${Math.max(7, t * .19)}px Georgia, serif`;
        ctx.textAlign = 'center';
        const tw = ctx.measureText(c.first).width;
        ctx.fillStyle = 'rgba(12,10,8,.62)';
        ctx.fillRect(sx - tw / 2 - 3, sy - t * .84, tw + 6, t * .26);
        ctx.fillStyle = selected ? '#f2dfb8' : 'rgba(230,212,174,.82)';
        ctx.fillText(c.first, sx, sy - t * .66);
      }
      // health/progress
      const hurt = c.hp < c.maxHp * .95 || c.bleeding > 0 || c.downed;
      if (hurt) {
        const bw = t * .38;
        ctx.fillStyle = 'rgba(10,8,6,.65)';
        ctx.fillRect(sx - bw / 2, sy - t * 1.02, bw, Math.max(2, t * .045));
        ctx.fillStyle = c.downed ? '#9a4134' : '#9b6c5c';
        ctx.fillRect(sx - bw / 2, sy - t * 1.02, bw * Math.max(0, c.hp / c.maxHp), Math.max(2, t * .045));
      }
      if (c.job && c.job.phase === 'working' && c.job.type !== 'idle' && c.job.duration) {
        const bw = t * .34;
        const ratio = Math.min(1, c.job.progress / c.job.duration);
        ctx.fillStyle = 'rgba(10,8,6,.55)'; ctx.fillRect(sx - bw / 2, sy + t * .37, bw, Math.max(1.5, t * .035));
        ctx.fillStyle = '#c9a15c'; ctx.fillRect(sx - bw / 2, sy + t * .37, bw * ratio, Math.max(1.5, t * .035));
      }
      // status icon
      const icon = statusIcon(c);
      if (icon && !c.downed) {
        ctx.fillStyle = 'rgba(18,14,10,.82)';
        ctx.beginPath(); ctx.arc(sx + t * .23, sy - t * .55, t * .12, 0, 7); ctx.fill();
        ctx.strokeStyle = 'rgba(201,161,92,.35)'; ctx.lineWidth = .7; ctx.stroke();
        ctx.fillStyle = icon.color || '#c9a15c';
        ctx.font = `${Math.max(6, t * .15)}px Georgia, serif`;
        ctx.textAlign = 'center';
        ctx.fillText(icon.glyph, sx + t * .23, sy - t * .5);
      }
      if (c.mood < 20 && !c.downed) {
        ctx.fillStyle = '#c27f6c';
        ctx.font = `${Math.max(8, t * .2)}px Georgia, serif`;
        ctx.textAlign = 'center';
        ctx.fillText('!', sx - t * .24, sy - t * .55);
      }
    }
  }

  function drawPawn(c, t, downed) {
    const cls = CLASSES[c.cls];
    const facing = c.facing || 1;
    if (downed) {
      ctx.fillStyle = c.skin;
      ctx.beginPath(); ctx.arc(t * .18, 0, t * .1, 0, 7); ctx.fill();
      ctx.fillStyle = cls.color;
      ctx.beginPath(); ctx.ellipse(-t * .04, 0, t * .22, t * .16, 0, 0, 7); ctx.fill();
      return;
    }
    // legs
    ctx.fillStyle = '#2f261c';
    ctx.fillRect(-t * .07, t * .12, t * .05, t * .14);
    ctx.fillRect(t * .02, t * .12, t * .05, t * .14);
    // cloak
    ctx.fillStyle = cls.color;
    ctx.beginPath();
    ctx.moveTo(-t * .13, t * .15);
    ctx.quadraticCurveTo(-t * .2, -t * .08, -t * .1, -t * .2);
    ctx.lineTo(t * .1, -t * .2);
    ctx.quadraticCurveTo(t * .2, -t * .08, t * .13, t * .15);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.08)';
    ctx.beginPath();
    ctx.moveTo(-t * .08, -t * .14);
    ctx.lineTo(-t * .01, -t * .14);
    ctx.lineTo(-t * .03, t * .1);
    ctx.lineTo(-t * .1, t * .1);
    ctx.closePath(); ctx.fill();
    // arms
    ctx.strokeStyle = c.skin;
    ctx.lineWidth = Math.max(1.3, t * .055);
    ctx.beginPath();
    ctx.moveTo(-t * .12, -t * .08); ctx.lineTo(-t * .16, t * .06);
    ctx.moveTo(t * .12, -t * .08); ctx.lineTo(t * .15, t * .06);
    ctx.stroke();
    // head
    ctx.fillStyle = c.skin;
    ctx.beginPath(); ctx.arc(0, -t * .29, t * .098, 0, 7); ctx.fill();
    ctx.fillStyle = c.race === 'dwarf' ? '#5a3c24' : c.race === 'tiefling' ? '#3a2020' : c.race === 'elf' ? '#b0a37c' : '#31251b';
    ctx.beginPath(); ctx.arc(0, -t * .315, t * .1, Math.PI, 0); ctx.fill();
    if (c.race === 'dwarf') { ctx.fillStyle = '#6a4b2d'; ctx.fillRect(-t * .07, -t * .22, t * .14, t * .08); }
    // weapon / focus
    if (cls.ranged) {
      ctx.strokeStyle = '#bc9a66';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(facing * t * .16, -t * .03, t * .1, -1.2, 1.2); ctx.stroke();
    } else {
      ctx.strokeStyle = '#b9b2a3';
      ctx.lineWidth = 1.3;
      ctx.beginPath();
      ctx.moveTo(facing * t * .15, t * .1);
      ctx.lineTo(facing * t * .21, -t * .17);
      ctx.stroke();
      ctx.fillStyle = '#775e3e';
      ctx.fillRect(facing * t * .145 - 1, -t * .03, t * .05, t * .03);
    }
    ctx.fillStyle = 'rgba(233,201,135,.5)';
    ctx.beginPath(); ctx.arc(-facing * t * .03, -t * .3, t * .018, 0, 7); ctx.fill();
  }

  function statusIcon(c) {
    if (c.downed) return { glyph: '✚', color: '#d39080' };
    if (c.bleeding > 0) return { glyph: '✚', color: '#c77d6b' };
    const j = c.job?.type;
    if (j === 'sleep') return { glyph: 'z', color: '#8fa8b1' };
    if (j === 'eat') return { glyph: '•', color: '#c9a15c' };
    if (j === 'fight') return { glyph: '⚔', color: '#d39080' };
    if (j === 'cook') return { glyph: '♨', color: '#e0a866' };
    if (j === 'construct') return { glyph: '⚒', color: '#c9a15c' };
    if (j === 'research') return { glyph: '✦', color: '#c79ae8' };
    if (j === 'doctor') return { glyph: '✚', color: '#9eb080' };
    if (j === 'gather') return { glyph: '❦', color: '#aebd76' };
    if (j === 'plant' || j === 'harvest') return { glyph: '❧', color: '#a8b981' };
    if (j === 'craft') return { glyph: '⚒', color: '#d7b477' };
    if (c.breakTimer > 0) return { glyph: '!', color: '#d39080' };
    return null;
  }

  function drawEnemies() {
    const t = tilePx();
    for (const e of state.enemies) {
      if (e.dead) continue;
      const sx = (e.x - cam.x) * t + W / 2;
      const sy = (e.y - cam.y) * t + H / 2;
      if (sx < -t * 2 || sy < -t * 2 || sx > W + t * 2 || sy > H + t * 2) continue;
      ctx.save();
      ctx.translate(sx, sy);
      ctx.fillStyle = 'rgba(8,8,6,.36)';
      ctx.beginPath(); ctx.ellipse(0, t * .29, t * .22, t * .08, 0, 0, 7); ctx.fill();
      if (e.hitFlash > 0) { ctx.shadowColor = '#fff'; ctx.shadowBlur = 10; }
      drawEnemyShape(e, t);
      ctx.restore();
      const bw = t * .4;
      ctx.fillStyle = 'rgba(10,7,6,.7)'; ctx.fillRect(sx - bw / 2, sy - t * .67, bw, Math.max(2, t * .05));
      ctx.fillStyle = '#a34839'; ctx.fillRect(sx - bw / 2, sy - t * .67, bw * Math.max(0, e.hp / e.maxHp), Math.max(2, t * .05));
      m: {
        // hostility marker
        ctx.fillStyle = 'rgba(163,72,57,.9)';
        ctx.beginPath(); ctx.arc(sx, sy - t * .78, t * .08, 0, 7); ctx.fill();
        ctx.fillStyle = '#f0d1c2'; ctx.font = `bold ${Math.max(6, t * .13)}px Georgia, serif`; ctx.textAlign = 'center';
        ctx.fillText('!', sx, sy - t * .735);
      }
      if (state.selected?.kind === 'enemy' && state.selected.id === e.id) {
        ctx.strokeStyle = 'rgba(163,72,57,.8)'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.ellipse(sx, sy + t * .28, t * .3, t * .12, 0, 0, 7); ctx.stroke();
        ctx.fillStyle = '#e6d4ae'; ctx.font = `${Math.max(8, t * .2)}px Georgia, serif`; ctx.textAlign = 'center';
        ctx.fillText(e.name, sx, sy - t * .9);
      }
    }
  }

  function drawEnemyShape(e, t) {
    const f = e.facing || 1;
    if (e.shape === 'wolf') {
      ctx.fillStyle = e.color;
      ctx.beginPath(); ctx.ellipse(0, t * .05, t * .23, t * .11, 0, 0, 7); ctx.fill();
      ctx.beginPath(); ctx.arc(f * t * .2, -t * .04, t * .1, 0, 7); ctx.fill();
      ctx.fillStyle = e.accent;
      ctx.beginPath(); ctx.moveTo(f * t * .18, -t * .1); ctx.lineTo(f * t * .14, -t * .19); ctx.lineTo(f * t * .24, -t * .12); ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#d3c8b2'; ctx.beginPath(); ctx.arc(f * t * .24, -t * .04, t * .012, 0, 7); ctx.fill();
      ctx.strokeStyle = e.color; ctx.lineWidth = t * .035;
      ctx.beginPath(); ctx.moveTo(-t * .2, 0); ctx.lineTo(-t * .34, -t * .09); ctx.stroke();
    } else if (e.shape === 'skeleton') {
      ctx.strokeStyle = e.color; ctx.lineWidth = t * .035;
      ctx.beginPath(); ctx.moveTo(0, -t * .13); ctx.lineTo(0, t * .13); ctx.stroke();
      ctx.fillStyle = e.accent;
      ctx.beginPath(); ctx.arc(0, -t * .25, t * .1, 0, 7); ctx.fill();
      ctx.fillStyle = '#2d2622'; ctx.fillRect(-t * .05, -t * .26, t * .025, t * .025); ctx.fillRect(t * .025, -t * .26, t * .025, t * .025);
      ctx.strokeStyle = e.color;
      ctx.beginPath(); ctx.moveTo(-t * .13, -t * .08); ctx.lineTo(0, -t * .03); ctx.lineTo(t * .13, -t * .1); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-t * .09, t * .13); ctx.lineTo(0, t * .02); ctx.lineTo(t * .1, t * .14); ctx.stroke();
    } else if (e.shape === 'cultist') {
      ctx.fillStyle = e.color;
      ctx.beginPath();
      ctx.moveTo(0, -t * .32); ctx.lineTo(t * .2, t * .17); ctx.lineTo(-t * .2, t * .17); ctx.closePath(); ctx.fill();
      ctx.fillStyle = e.accent;
      ctx.beginPath(); ctx.arc(0, -t * .31, t * .09, 0, 7); ctx.fill();
      ctx.fillStyle = '#2a1a26'; ctx.beginPath(); ctx.arc(0, -t * .28, t * .065, 0, 7); ctx.fill();
      ctx.fillStyle = '#d17c7c'; ctx.beginPath(); ctx.arc(-t * .022, -t * .29, t * .012, 0, 7); ctx.arc(t * .022, -t * .29, t * .012, 0, 7); ctx.fill();
      ctx.strokeStyle = '#a9779b'; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(f * t * .22, -t * .01, t * .08, 0, 7); ctx.stroke();
    } else if (e.shape === 'ogre') {
      ctx.fillStyle = e.color;
      ctx.beginPath(); ctx.ellipse(0, t * .03, t * .26, t * .24, 0, 0, 7); ctx.fill();
      ctx.fillStyle = e.accent;
      ctx.beginPath(); ctx.arc(0, -t * .28, t * .12, 0, 7); ctx.fill();
      ctx.fillStyle = '#3d3423';
      ctx.beginPath(); ctx.arc(-t * .035, -t * .3, t * .014, 0, 7); ctx.arc(t * .04, -t * .3, t * .014, 0, 7); ctx.fill();
      ctx.fillStyle = '#6a563a';
      ctx.fillRect(-t * .16, -t * .08, t * .09, t * .23);
      ctx.fillRect(t * .08, -t * .08, t * .09, t * .23);
      ctx.strokeStyle = '#5a4b35'; ctx.lineWidth = t * .05;
      ctx.beginPath(); ctx.moveTo(f * t * .18, -t * .1); ctx.lineTo(f * t * .32, t * .14); ctx.stroke();
    } else if (e.shape === 'wraith') {
      const grd = ctx.createRadialGradient(0, 0, 1, 0, 0, t * .36);
      grd.addColorStop(0, 'rgba(176,202,202,.55)'); grd.addColorStop(1, 'rgba(101,117,124,0)');
      ctx.fillStyle = grd; ctx.beginPath(); ctx.arc(0, 0, t * .36, 0, 7); ctx.fill();
      ctx.fillStyle = 'rgba(145,174,176,.55)';
      ctx.beginPath(); ctx.moveTo(0, -t * .32); ctx.quadraticCurveTo(t * .25, -t * .05, t * .13, t * .18); ctx.quadraticCurveTo(0, t * .05, -t * .13, t * .18); ctx.quadraticCurveTo(-t * .25, -t * .05, 0, -t * .32); ctx.fill();
      ctx.fillStyle = '#e5f1ee'; ctx.fillRect(-t * .055, -t * .23, t * .035, t * .02); ctx.fillRect(t * .025, -t * .23, t * .035, t * .02);
    } else {
      // goblin
      ctx.fillStyle = e.color;
      ctx.beginPath(); ctx.ellipse(0, t * .06, t * .17, t * .19, 0, 0, 7); ctx.fill();
      ctx.fillStyle = e.accent;
      ctx.beginPath(); ctx.arc(0, -t * .2, t * .12, 0, 7); ctx.fill();
      ctx.fillStyle = e.color;
      ctx.beginPath(); ctx.moveTo(-t * .09, -t * .26); ctx.lineTo(-t * .19, -t * .38); ctx.lineTo(-t * .04, -t * .31); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(t * .09, -t * .26); ctx.lineTo(t * .19, -t * .38); ctx.lineTo(t * .04, -t * .31); ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#271c1c'; ctx.beginPath(); ctx.arc(-t * .04, -t * .22, t * .012, 0, 7); ctx.arc(t * .04, -t * .22, t * .012, 0, 7); ctx.fill();
      ctx.strokeStyle = '#b7b0a0'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(f * t * .18, t * .14); ctx.lineTo(f * t * .24, -t * .15); ctx.stroke();
    }
  }

  function drawProjectiles() {
    const t = tilePx();
    for (const p of state.projectiles) {
      const sx = (p.x - cam.x) * t + W / 2;
      const sy = (p.y - cam.y) * t + H / 2;
      const tx = (p.tx - cam.x) * t + W / 2;
      const ty = (p.ty - cam.y) * t + H / 2;
      if (p.type === 'orb') {
        const grd = ctx.createRadialGradient(sx, sy, 0, sx, sy, t * .25);
        grd.addColorStop(0, p.color); grd.addColorStop(1, 'rgba(167,118,211,0)');
        ctx.fillStyle = grd; ctx.beginPath(); ctx.arc(sx, sy, t * .25, 0, 7); ctx.fill();
        ctx.fillStyle = '#f0e3ff'; ctx.beginPath(); ctx.arc(sx, sy, t * .04, 0, 7); ctx.fill();
      } else {
        const a = Math.atan2(ty - sy, tx - sx);
        ctx.strokeStyle = p.color; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(sx - Math.cos(a) * t * .17, sy - Math.sin(a) * t * .17); ctx.stroke();
      }
    }
  }

  function drawParticles() {
    const t = tilePx();
    for (const p of state.particles) {
      const a = Math.max(0, p.life / p.max);
      const sx = (p.x - cam.x) * t + W / 2;
      const sy = (p.y - cam.y) * t + H / 2;
      ctx.globalAlpha = Math.min(1, a * 1.4);
      ctx.fillStyle = p.color;
      ctx.beginPath(); ctx.arc(sx, sy, p.size * cam.zoom, 0, 7); ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function drawFloats() {
    const t = tilePx();
    for (const f of state.floats) {
      const sx = (f.x - cam.x) * t + W / 2;
      const sy = (f.y - cam.y) * t + H / 2;
      ctx.globalAlpha = Math.min(1, f.ttl / f.max * 1.6);
      ctx.font = `${Math.max(8, t * .25)}px Georgia, serif`;
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(10,8,6,.55)';
      ctx.fillText(f.text, sx + 1, sy + 1);
      ctx.fillStyle = f.color;
      ctx.fillText(f.text, sx, sy);
    }
    ctx.globalAlpha = 1;
  }

  function drawLighting() {
    const hour = state.time.hour;
    let dark = 0;
    if (hour < 5) dark = .48;
    else if (hour < 7) dark = lerp(.48, 0, (hour - 5) / 2);
    else if (hour < 18) dark = 0;
    else if (hour < 21) dark = lerp(0, .46, (hour - 18) / 3);
    else dark = .46;
    if (state.time.weather === 'Eclipse') dark = Math.max(dark, .33);
    if (dark > 0) {
      const grd = ctx.createLinearGradient(0, 0, 0, H);
      grd.addColorStop(0, `rgba(10,16,28,${dark * .95})`);
      grd.addColorStop(1, `rgba(8,11,19,${dark * .72})`);
      ctx.fillStyle = grd;
      ctx.fillRect(0, 0, W, H);
      // firelight
      const t = tilePx();
      for (const b of state.buildings) {
        if (!b.complete) continue;
        if (!['campfire', 'forge', 'shrine'].includes(b.type)) continue;
        const sx = (b.x + b.w / 2 - cam.x) * t + W / 2;
        const sy = (b.y + b.h / 2 - cam.y) * t + H / 2;
        const radius = (b.type === 'shrine' ? 3.3 : 2.9) * t;
        const col = b.type === 'shrine' ? '167,118,211' : '235,151,74';
        const glow = ctx.createRadialGradient(sx, sy, 0, sx, sy, radius);
        glow.addColorStop(0, `rgba(${col},${b.type === 'shrine' ? .22 : .28})`);
        glow.addColorStop(.4, `rgba(${col},${b.type === 'shrine' ? .09 : .12})`);
        glow.addColorStop(1, `rgba(${col},0)`);
        ctx.fillStyle = glow;
        ctx.beginPath(); ctx.arc(sx, sy, radius, 0, 7); ctx.fill();
      }
      // fireflies
      if (hour > 19 || hour < 5) {
        for (const f of fireflies) {
          const x = ((f.x + Math.sin(state.simTime * .1 + f.p) * .02 + 1) % 1) * W;
          const y = ((f.y + Math.cos(state.simTime * .08 + f.p) * .02 + 1) % 1) * H * .78 + H * .08;
          const a = .2 + Math.sin(state.simTime * f.s * 3 + f.p) * .16;
          if (a <= 0) continue;
          ctx.fillStyle = `rgba(233,201,135,${a})`;
          ctx.beginPath(); ctx.arc(x, y, 1.2, 0, 7); ctx.fill();
        }
      }
    }
  }

  function drawWeather() {
    const weather = state.time.weather;
    if (weather.includes('rain') || weather.includes('sleet') || weather.includes('Mist')) {
      const raining = weather.includes('rain');
      if (raining) {
        ctx.strokeStyle = weather.includes('sleet') ? 'rgba(190,210,215,.24)' : 'rgba(170,194,200,.2)';
        ctx.lineWidth = 1;
        const speed = weather.includes('sleet') ? .55 : .95;
        for (const r of rainSeeds) {
          const x = (r.x * W + state.simTime * 12 * r.s) % W;
          const y = (r.y * H + state.simTime * 310 * speed * r.s) % H;
          ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - 2, y + r.l * H * .38); ctx.stroke();
        }
      }
      const mist = ctx.createLinearGradient(0, 0, 0, H);
      mist.addColorStop(0, 'rgba(183,198,193,.02)');
      mist.addColorStop(.6, 'rgba(183,198,193,.075)');
      mist.addColorStop(1, 'rgba(183,198,193,.12)');
      ctx.fillStyle = mist;
      ctx.fillRect(0, 0, W, H);
    }
    if (weather === 'Eclipse') {
      const grd = ctx.createRadialGradient(W * .5, H * .4, 0, W * .5, H * .4, W * .7);
      grd.addColorStop(0, 'rgba(36,4,28,.06)');
      grd.addColorStop(1, 'rgba(22,0,18,.42)');
      ctx.fillStyle = grd;
      ctx.fillRect(0, 0, W, H);
    }
  }

  function drawSelectionAndGhost() {
    const t = tilePx();
    if (state.hover) {
      const { x, y } = state.hover;
      const sx = (x - cam.x) * t + W / 2;
      const sy = (y - cam.y) * t + H / 2;
      if (state.buildMode) {
        const def = BUILDINGS[state.buildMode.type];
        const check = state.placeCheck;
        const ok = check?.ok;
        ctx.fillStyle = ok ? 'rgba(115,140,91,.2)' : 'rgba(163,72,57,.22)';
        ctx.strokeStyle = ok ? 'rgba(166,197,131,.8)' : 'rgba(211,125,104,.75)';
        ctx.lineWidth = 1;
        ctx.fillRect(sx, sy, def.w * t, def.h * t);
        ctx.strokeRect(sx + .5, sy + .5, def.w * t - 1, def.h * t - 1);
        // ghost silhouette
        ctx.globalAlpha = .4;
        ctx.fillStyle = '#e6d4ae';
        ctx.font = `${Math.max(14, t * .5)}px Georgia, serif`;
        ctx.textAlign = 'center';
        ctx.fillText(def.icon, sx + def.w * t / 2, sy + def.h * t / 2 + t * .18);
        ctx.globalAlpha = 1;
      } else {
        const selected = state.selected;
        if (!selected || selected.kind !== 'building' || selected.id !== buildingIdAt(x, y)) {
          ctx.strokeStyle = 'rgba(233,201,135,.28)';
          ctx.lineWidth = 1;
          ctx.strokeRect(sx + 1, sy + 1, t - 2, t - 2);
        }
      }
    }
    // selected building
    if (state.selected?.kind === 'building') {
      const b = state.buildings.find(v => v.id === state.selected.id);
      if (b) {
        const sx = (b.x - cam.x) * t + W / 2;
        const sy = (b.y - cam.y) * t + H / 2;
        ctx.strokeStyle = 'rgba(233,201,135,.62)';
        ctx.lineWidth = 1.2;
        ctx.setLineDash([5, 4]);
        ctx.strokeRect(sx - 2, sy - 2, b.w * t + 4, b.h * t + 4);
        ctx.setLineDash([]);
      }
    }
    if (state.selected?.kind === 'enemy') {
      const e = state.enemies.find(v => v.id === state.selected.id);
      if (e) {
        const sx = (e.x - cam.x) * t + W / 2;
        const sy = (e.y - cam.y) * t + H / 2;
        ctx.strokeStyle = 'rgba(211,125,104,.7)';
        ctx.beginPath(); ctx.arc(sx, sy, t * .42, 0, 7); ctx.stroke();
      }
    }
  }

  function buildingIdAt(x, y) {
    const b = state.buildings.find(v => x >= v.x && x < v.x + v.w && y >= v.y && y < v.y + v.h);
    return b?.id;
  }

  function drawHudHints() {
    if (!state.buildMode) return;
    const def = BUILDINGS[state.buildMode.type];
    const txt = `Placing ${def.name} — right-click or Esc to cancel`;
    ctx.font = '10px Avenir Next, Segoe UI, sans-serif';
    const w = ctx.measureText(txt).width + 26;
    ctx.fillStyle = 'rgba(16,12,9,.86)';
    ctx.fillRect(W / 2 - w / 2, H - 104, w, 24);
    ctx.strokeStyle = 'rgba(201,161,92,.3)'; ctx.strokeRect(W / 2 - w / 2, H - 104, w, 24);
    ctx.fillStyle = '#e6d4ae';
    ctx.textAlign = 'center';
    ctx.fillText(txt, W / 2, H - 88);
  }

  function drawMinimap() {
    if (W < 861) return;
    const mw = 164, mh = 112;
    const ox = W - 182, oy = H - 68 - mh;
    if (oy < 100) return;
    ctx.save();
    ctx.fillStyle = 'rgba(12,9,7,.8)';
    ctx.fillRect(ox - 3, oy - 3, mw + 6, mh + 6);
    ctx.strokeStyle = 'rgba(201,161,92,.24)';
    ctx.strokeRect(ox - 3, oy - 3, mw + 6, mh + 6);
    ctx.fillStyle = 'rgba(36,47,30,.9)';
    ctx.fillRect(ox, oy, mw, mh);
    const sx = mw / state.world.w, sy = mh / state.world.h;
    for (let y = 0; y < state.world.h; y += 2) {
      for (let x = 0; x < state.world.w; x += 2) {
        const terr = state.world.tiles[y * state.world.w + x];
        if (terr === TERRAIN.WATER) ctx.fillStyle = '#2c4850';
        else if (terr === TERRAIN.FOREST) ctx.fillStyle = '#34422d';
        else if (terr === TERRAIN.MOUNTAIN) ctx.fillStyle = '#47453f';
        else if (terr === TERRAIN.DIRT) ctx.fillStyle = '#5b4a34';
        else if (terr === TERRAIN.RUIN) ctx.fillStyle = '#575348';
        else continue;
        ctx.fillRect(ox + x * sx, oy + y * sy, sx * 2 + .5, sy * 2 + .5);
      }
    }
    for (const b of state.buildings) {
      if (!b.complete) continue;
      ctx.fillStyle = b.type === 'campfire' ? '#e9a35a' : b.type === 'shrine' ? '#b78bd4' : 'rgba(214,189,147,.65)';
      ctx.fillRect(ox + b.x * sx, oy + b.y * sy, Math.max(1.2, b.w * sx), Math.max(1.2, b.h * sy));
    }
    for (const c of state.colonists) {
      if (c.dead || c.onExpedition) continue;
      ctx.fillStyle = c.downed ? '#9a4134' : '#e9c987';
      ctx.beginPath(); ctx.arc(ox + c.x * sx, oy + c.y * sy, 1.6, 0, 7); ctx.fill();
    }
    for (const e of state.enemies) {
      if (e.dead) continue;
      ctx.fillStyle = '#c55b48';
      ctx.beginPath(); ctx.arc(ox + e.x * sx, oy + e.y * sy, 1.8, 0, 7); ctx.fill();
    }
    // viewport
    const vw = (W / tilePx()) * sx, vh = (H / tilePx()) * sy;
    ctx.strokeStyle = 'rgba(233,201,135,.55)'; ctx.lineWidth = 1;
    ctx.strokeRect(ox + (cam.x - W / 2 / tilePx()) * sx, oy + (cam.y - H / 2 / tilePx()) * sy, vw, vh);
    ctx.fillStyle = 'rgba(230,212,174,.62)';
    ctx.font = '6.5px Avenir Next, Segoe UI, sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('ASHENREACH', ox + 4, oy + mh - 4);
    ctx.restore();
    minimapState = { ox, oy, mw, mh };
  }

  function minimapHit(sx, sy) {
    if (!minimapState) return null;
    const m = minimapState;
    if (sx < m.ox || sy < m.oy || sx > m.ox + m.mw || sy > m.oy + m.mh) return null;
    return { x: (sx - m.ox) / m.mw * state.world.w, y: (sy - m.oy) / m.mh * state.world.h };
  }

  function zoomBy(delta) {
    cam.targetZoom = Math.max(.55, Math.min(2.4, cam.targetZoom * (delta > 0 ? .9 : 1.1)));
  }

  function panBy(dx, dy) {
    const t = tilePx();
    cam.x -= dx / t;
    cam.y -= dy / t;
    cam.x = Math.max(4, Math.min(state.world.w - 4, cam.x));
    cam.y = Math.max(4, Math.min(state.world.h - 4, cam.y));
  }

  return { resize, draw, worldToScreen, screenToWorld, centerOn, zoomBy, panBy, minimapHit, cam, get width() { return W; }, get height() { return H; } };
}

function shade(hex, amt) {
  const n = parseInt(hex.slice(1), 16);
  const r = Math.max(0, Math.min(255, (n >> 16) + amt * 255));
  const g = Math.max(0, Math.min(255, ((n >> 8) & 255) + amt * 255));
  const b = Math.max(0, Math.min(255, (n & 255) + amt * 255));
  return `rgb(${r | 0},${g | 0},${b | 0})`;
}

export function drawOverview(canvas, state) {
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const rect = canvas.getBoundingClientRect();
  canvas.width = Math.floor(rect.width * dpr);
  canvas.height = Math.floor(rect.height * dpr);
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const W = rect.width, H = rect.height;
  ctx.clearRect(0, 0, W, H);
  const grd = ctx.createRadialGradient(W * .5, H * .45, 20, W * .5, H * .45, W * .7);
  grd.addColorStop(0, '#26251b');
  grd.addColorStop(1, '#10110d');
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, W, H);
  // Parchment contours.
  ctx.strokeStyle = 'rgba(201,161,92,.06)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 14; i++) {
    ctx.beginPath();
    for (let x = 0; x <= W; x += 10) {
      const y = H * .5 + Math.sin(x * .005 + i * .8) * (30 + i * 5) + (i - 7) * 24;
      if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  const cx = W * .5, cy = H * .5;
  const scaleX = W / state.world.w, scaleY = H / state.world.h;
  const mapW = Math.min(W * .72, state.world.w * 18);
  const mapH = mapW * state.world.h / state.world.w;
  const mx = cx - mapW / 2, my = cy - mapH / 2;
  // landmass silhouette from actual tiles
  ctx.save();
  ctx.beginPath();
  ctx.rect(mx, my, mapW, mapH);
  ctx.clip();
  const step = Math.max(1, Math.floor(state.world.w / 100));
  for (let y = 0; y < state.world.h; y += step) {
    for (let x = 0; x < state.world.w; x += step) {
      const terr = state.world.tiles[y * state.world.w + x];
      if (terr === TERRAIN.WATER) continue;
      ctx.fillStyle = terr === TERRAIN.FOREST ? 'rgba(63,77,50,.85)' : terr === TERRAIN.MOUNTAIN ? 'rgba(88,84,74,.9)' : terr === TERRAIN.RUIN ? 'rgba(102,96,80,.9)' : 'rgba(82,94,63,.7)';
      ctx.fillRect(mx + x / state.world.w * mapW, my + y / state.world.h * mapH, mapW / state.world.w * step + .4, mapH / state.world.h * step + .4);
    }
  }
  // roads as a gold thread
  ctx.strokeStyle = 'rgba(201,161,92,.22)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  curvePath(ctx, [[30, 22], [31, 29], [35, 38], [50, 43]], mx, my, mapW / state.world.w, mapH / state.world.h);
  ctx.stroke();
  ctx.restore();
  // frame
  ctx.strokeStyle = 'rgba(201,161,92,.2)';
  ctx.lineWidth = 1;
  ctx.strokeRect(mx, my, mapW, mapH);
  // locations
  const locations = [
    { id: 'ruins', name: 'Sunken Shrine', x: 47, y: 29, discovered: true, icon: '◈' },
    { id: 'grove', name: 'Whisperwood', x: 13, y: 12, discovered: true, icon: '❦' },
    { id: 'road', name: 'Merchant Road', x: 31, y: 37, discovered: true, icon: '⌁' },
    { id: 'camp', name: 'Ashenreach', x: 30, y: 19, discovered: true, icon: '✦' },
    { id: 'barrow', name: 'Kingsbarrow', x: 51, y: 9, discovered: state.stats.daysSurvived >= 4, icon: '▴' },
    { id: 'tower', name: 'Hollow Watch', x: 8, y: 33, discovered: state.completedResearch.includes('astronomy'), icon: '♜' },
    { id: 'rift', name: 'Sundered Rift', x: 56, y: 37, discovered: state.completedResearch.includes('astronomy'), icon: '◉' },
  ];
  for (const loc of locations) {
    if (!loc.discovered) continue;
    const lx = mx + loc.x / state.world.w * mapW;
    const ly = my + loc.y / state.world.h * mapH;
    const isCamp = loc.id === 'camp';
    const pulse = .7 + Math.sin(performance.now() / 600 + loc.x) * .2;
    ctx.fillStyle = isCamp ? `rgba(233,201,135,${pulse})` : 'rgba(201,161,92,.55)';
    ctx.beginPath(); ctx.arc(lx, ly, isCamp ? 5 : 3, 0, 7); ctx.fill();
    if (isCamp) {
      ctx.strokeStyle = 'rgba(233,201,135,.28)';
      ctx.beginPath(); ctx.arc(lx, ly, 11 + pulse * 4, 0, 7); ctx.stroke();
    }
    ctx.font = '8px Georgia, serif';
    ctx.fillStyle = isCamp ? '#f2dfb8' : 'rgba(230,212,174,.72)';
    ctx.textAlign = 'center';
    ctx.fillText(loc.name, lx, ly - 9);
  }
  // compass
  ctx.strokeStyle = 'rgba(201,161,92,.24)';
  ctx.beginPath(); ctx.arc(W - 54, 52, 24, 0, 7); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(W - 54, 22); ctx.lineTo(W - 54, 82); ctx.moveTo(W - 84, 52); ctx.lineTo(W - 24, 52); ctx.stroke();
  ctx.fillStyle = 'rgba(201,161,92,.45)';
  ctx.font = '7px Georgia, serif'; ctx.textAlign = 'center'; ctx.fillText('N', W - 54, 18);
  ctx.fillStyle = 'rgba(201,161,92,.14)';
  ctx.font = 'italic 11px Georgia, serif'; ctx.textAlign = 'left';
  ctx.fillText('The Sundered Marches', mx, my + mapH + 21);
  ctx.font = '7px Avenir Next, Segoe UI, sans-serif';
  ctx.fillStyle = 'rgba(230,212,174,.35)';
  ctx.fillText('Here be old things. Most are sleeping.', mx, my + mapH + 33);
}

function curvePath(ctx, points, mx, my, sx, sy) {
  ctx.moveTo(mx + points[0][0] * sx, my + points[0][1] * sy);
  for (let i = 1; i < points.length; i++) {
    const prev = points[i - 1], cur = points[i];
    const cx = mx + (prev[0] + cur[0]) / 2 * sx;
    const cy = my + (prev[1] + cur[1]) / 2 * sy;
    ctx.quadraticCurveTo(cx, cy, mx + cur[0] * sx, my + cur[1] * sy);
  }
}

import {
  BUILDINGS, CLASSES, ENEMY_TYPES, EXPEDITIONS, RACES, RESEARCH, RESOURCE_META,
  SEASONS, SKILLS, TRAITS, WORK_TYPES,
} from './content.js';
import {
  canAfford, canPlace, dateLabel, getStatus, isUnlocked, phaseForHour, selectedEntity,
  timeLabel,
} from './sim.js';

const RES_ORDER = ['wood', 'stone', 'food', 'meals', 'herbs', 'crystal', 'silver'];

function svgIcon(name) {
  const paths = {
    wood: '<path d="M3 14h11a3 3 0 0 0 3-3V8H6a3 3 0 0 0-3 3Z"/><path d="M6 16h9a3 3 0 0 0 3-3v-2"/><ellipse cx="7" cy="10.5" rx="2" ry="2.4"/><ellipse cx="12" cy="8.5" rx="1.6" ry="2.2"/>',
    stone: '<path d="m4 14 2-6 4-3 5 2 2 5-3 4H7Z"/><path d="m10 5 1 5 4 2"/><path d="m6 8 4 3-1 5"/>',
    food: '<path d="M12 18V8"/><path d="M12 13c-4 0-6-2-6-6 4 0 6 2 6 6Z"/><path d="M12 11c3 0 4-2 4-5-3 0-4 2-4 5Z"/><path d="M8 18h8"/>',
    meal: '<path d="M4 11h16a8 8 0 0 1-8 7 8 8 0 0 1-8-7Z"/><path d="M7 8c0-1 1-2 2-3M12 7c0-1 1-2 2-3M9 18h6"/>',
    herb: '<path d="M12 20V9"/><path d="M12 12c-4 0-6-2-6-6 4 0 6 2 6 6Z"/><path d="M12 16c4 0 6-2 6-6-4 0-6 2-6 6Z"/>',
    crystal: '<path d="m12 3 5 5-1 9-4 4-4-4-1-9Z"/><path d="m12 3-1 14M7 8l5 3 5-3M11 17l1 4"/>',
    silver: '<ellipse cx="12" cy="7" rx="6" ry="3"/><path d="M6 7v5c0 1.7 2.7 3 6 3s6-1.3 6-3V7"/><path d="M6 12v5c0 1.7 2.7 3 6 3s6-1.3 6-3v-5"/>',
    people: '<circle cx="9" cy="8" r="3"/><path d="M3 20c0-3 2.5-5 6-5s6 2 6 5"/><circle cx="17" cy="9" r="2"/><path d="M16 15c3 0 5 1.6 5 4"/>',
    shield: '<path d="M12 3 5 6v5c0 5 3 8 7 10 4-2 7-5 7-10V6Z"/><path d="m9 12 2 2 4-5"/>',
    sun: '<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
  };
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.stone}</svg>`;
}

function esc(s) {
  return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function pct(v) { return Math.max(0, Math.min(100, Math.round(v))); }
function fmt(n) { return n >= 1000 ? (n / 1000).toFixed(1) + 'k' : Math.round(n).toString(); }

export function createUI(state, actions) {
  const $ = s => document.querySelector(s);
  const leftContent = $('#left-content');
  const rightContent = $('#right-content');
  const resourceBar = $('#resource-bar');
  const seenToasts = new Set();
  let lastLeft = '';
  let lastRight = '';
  let lastRes = '';
  let lastBanner = null;
  let bannerTimer = 0;
  let lastChrono = '';
  let scrollLeft = 0, scrollRight = 0;
  let lastTooltip = null;

  function renderResources() {
    const key = RES_ORDER.map(r => state.resources[r]).join(',');
    if (key === lastRes) return;
    lastRes = key;
    resourceBar.innerHTML = RES_ORDER.map(r => {
      const val = Math.floor(state.resources[r]);
      const warn = (r === 'food' || r === 'meals') && val < state.colonists.filter(c => !c.dead).length * 2;
      return `<div class="resource ${warn ? 'warn' : ''}" title="${RESOURCE_META[r].name} — ${val}${r === 'wood' || r === 'stone' ? ' / ' + state.resourceCap : ''}">
        ${svgIcon(RESOURCE_META[r].icon)}<div><span class="res-val">${fmt(val)}</span>${['wood', 'stone'].includes(r) ? `<span class="res-cap">/${state.resourceCap}</span>` : ''}</div>
      </div>`;
    }).join('');
  }

  function renderChrono() {
    $('#date-label').textContent = dateLabel(state.time);
    $('#year-label').textContent = `Year ${state.time.year}`;
    $('#time-label').textContent = timeLabel(state.time.hour);
    $('#time-phase').textContent = phaseForHour(state.time.hour);
    const weatherGlyph = state.time.weather.includes('rain') ? '☂' : state.time.weather.includes('sleet') ? '❄' : state.time.weather === 'Eclipse' ? '◒' : state.time.weather.includes('wind') ? '≋' : state.time.weather.includes('Mist') ? '░' : '☼';
    $('#weather-label').innerHTML = `<span class="weather-glyph">${weatherGlyph}</span><span>${esc(state.time.weather)}</span>`;
    $('#sun-dot').style.left = `${Math.max(1, Math.min(97, state.time.hour / 24 * 100))}%`;
    const st = getStatus(state);
    $('#colony-status').textContent = st.threat ? `Under threat — ${st.threat} hostile${st.threat > 1 ? 's' : ''}` : `${st.alive} souls · Day ${state.stats.daysSurvived} · ${state.time.weather}`;
  }

  function renderLeft(force = false) {
    const el = document.activeElement;
    if (el && (el.tagName === 'SELECT' || el.tagName === 'INPUT')) return;
    scrollLeft = leftContent.scrollTop;
    let html = '';
    if (state.uiTab === 'colony') html = leftColony();
    else if (state.uiTab === 'work') html = leftWork();
    else if (state.uiTab === 'build') html = leftBuild();
    else if (state.uiTab === 'research') html = leftResearch();
    else html = leftWorld();
    if (html === lastLeft && !force) return;
    lastLeft = html;
    leftContent.innerHTML = html;
    leftContent.scrollTop = scrollLeft;
  }

  function leftColony() {
    const alive = state.colonists.filter(c => !c.dead);
    const beds = state.buildings.filter(b => b.type === 'bed' && b.complete).length;
    const hasFire = state.buildings.some(b => b.type === 'campfire' && b.complete);
    const food = state.resources.meals + state.resources.food * .5;
    const days = Math.max(0, food / Math.max(1, alive.length));
    const moodOrbs = Array.from({ length: 10 }, (_, i) => `<i class="mood-orb ${state.mood > i * 9.5 ? 'on' : ''}"></i>`).join('');
    const roster = state.colonists.map(c => {
      if (c.dead) {
        return `<button class="colonist-card" data-action="select-colonist" data-id="${c.id}" style="opacity:.4">
          <div class="avatar" style="background:#2c2520">†<i class="status-pip bad"></i></div>
          <div><div class="c-name">${esc(c.name)}</div><div class="c-meta">Dead · ${esc(RACES[c.race].name)} ${esc(CLASSES[c.cls].name)}</div></div>
          <div class="c-job">Remembered</div></button>`;
      }
      const low = c.hunger < 30 || c.rest < 25;
      return `<button class="colonist-card ${state.selected?.kind === 'colonist' && state.selected.id === c.id ? 'selected' : ''}" data-action="select-colonist" data-id="${c.id}">
        <div class="avatar" style="background:linear-gradient(145deg,${CLASSES[c.cls].color},#1a1510)">${esc(c.first[0])}<i class="status-pip ${c.downed || c.bleeding > 0 ? 'bad' : c.mood < 32 ? 'warn' : ''}"></i></div>
        <div style="min-width:0">
          <div class="c-name">${esc(c.name)}</div>
          <div class="c-meta">${esc(RACES[c.race].name)} · ${esc(CLASSES[c.cls].name)} · ${c.onExpedition ? 'In the field' : esc(c.status || 'Idle')}</div>
          <div class="need-bars"><i class="${c.hunger < 30 ? 'low' : ''}"><b style="width:${pct(c.hunger)}%"></b></i><i class="${c.rest < 25 ? 'low' : ''}"><b style="width:${pct(c.rest)}%"></b></i><i class="${c.mood < 25 ? 'low' : ''}"><b style="width:${pct(c.mood)}%"></b></i></div>
        </div>
        <div class="c-job">${c.downed ? 'Downed' : esc(c.job?.type === 'fight' ? 'Defending' : c.job?.type === 'sleep' ? 'Sleeping' : c.job?.type === 'eat' ? 'Eating' : c.status || 'Idle')}</div>
      </button>`;
    }).join('');

    return `
      <div class="colony-banner">
        <h4>Ashenreach</h4>
        <p>Five exiles, one broken waystone, and a fire that refuses to go out. The Marches are watching.</p>
        <div class="mood-row">
          <div class="mood-orbs">${moodOrbs}</div>
          <span class="mood-score">${Math.round(state.mood)}</span>
          <span class="mood-caption">Colony spirit</span>
        </div>
      </div>
      <div class="stat-grid">
        <div class="stat-card"><div class="v">${alive.length}</div><div class="k">Souls</div></div>
        <div class="stat-card"><div class="v">${days.toFixed(1)}</div><div class="k">Days food</div></div>
        <div class="stat-card"><div class="v">${beds}</div><div class="k">Beds</div></div>
        <div class="stat-card"><div class="v">${state.stats.built}</div><div class="k">Raised</div></div>
        <div class="stat-card"><div class="v">${state.stats.kills}</div><div class="k">Slain</div></div>
        <div class="stat-card"><div class="v">${state.completedResearch.length}</div><div class="k">Discoveries</div></div>
      </div>
      <div class="section-head"><h3>The Company</h3><span class="rule"></span><span class="count">${alive.length}</span></div>
      <div class="colonist-list">${roster}</div>
      <div class="section-head" style="margin-top:16px"><h3>Chronicle</h3><span class="rule"></span></div>
      <div class="log-list">${state.log.slice(0, 7).map(e => `<div class="log-entry ${e.kind}"><span class="lt">${esc(e.t)}</span><span class="ld">${e.icon || '·'}</span><span>${e.text}</span></div>`).join('')}</div>
      <div style="height:8px"></div>
      <div class="section-sub" style="text-align:center;opacity:.65">${hasFire ? 'The fire is tended.' : '<span style="color:#c77d6b">No fire. Build a campfire.</span>'} · ${alive.length} alive · ${state.time.weather}</div>
    `;
  }

  function leftWork() {
    const alive = state.colonists.filter(c => !c.dead);
    const head = alive.map(c => `<th title="${esc(c.name)}">${esc(c.first.slice(0, 5))}</th>`).join('');
    const rows = WORK_TYPES.map(w => {
      const cells = alive.map(c => {
        const v = c.priorities[w.id] ?? 4;
        return `<td><button class="prio p${v}" data-action="priority" data-cid="${c.id}" data-work="${w.id}" data-val="${v}" title="${esc(c.first)} — ${w.name}: ${{ 1: 'High', 2: 'Normal', 3: 'Low', 4: 'Never' }[v]}">${v < 4 ? v : '—'}</button></td>`;
      }).join('');
      return `<tr><td title="${w.name}">${w.name}</td>${cells}</tr>`;
    }).join('');
    return `
      <div class="section-head"><h3>Work Priorities</h3><span class="rule"></span></div>
      <p class="section-sub">Click a cell to cycle a colonist’s priority. <b style="color:#e9c987">1</b> is urgent, <b style="color:#7c705b">3</b> is idle work, <b>—</b> forbids it. Idle colonists choose the most pressing task they are suited for.</p>
      <div class="work-scroll"><table class="work-table"><thead><tr><th>Task</th>${head}</tr></thead><tbody>${rows}</tbody></table></div>
      <div class="work-legend"><span><b>1</b> Urgent</span><span><b>2</b> Normal</span><span><b>3</b> Idle</span><span><b>—</b> Never</span></div>
      <div class="section-head" style="margin-top:16px"><h3>Skills</h3><span class="rule"></span></div>
      <div class="section-sub">Work speed and quality improve with practice. Combat and survival improve under pressure.</div>
      <div class="skill-grid" style="grid-template-columns:1fr 1fr">
        ${alive.map(c => `<div style="border:1px solid var(--line-soft);padding:6px;font-size:8px">
          <div style="font-family:var(--serif);font-size:10px;color:var(--parch);margin-bottom:4px">${esc(c.first)}</div>
          ${SKILLS.slice(0, 6).map(s => `<div class="skill-row"><span>${s.name}</span><div class="pips">${Array.from({ length: 10 }, (_, i) => `<i class="${i < Math.round(c.skills[s.id]) ? 'on' : ''}"></i>`).join('')}</div><b>${Math.round(c.skills[s.id])}</b></div>`).join('')}
        </div>`).join('')}
      </div>
    `;
  }

  function leftBuild() {
    const cats = ['All', 'Shelter', 'Production', 'Defense', 'Faith'];
    const cat = state.buildCategory || 'All';
    const items = Object.entries(BUILDINGS).filter(([, d]) => cat === 'All' || d.cat === cat);
    const cards = items.map(([id, d]) => {
      const locked = !isUnlocked(state, id);
      const afford = canAfford(state, d.cost);
      const active = state.buildMode?.type === id;
      const cost = Object.entries(d.cost).map(([r, n]) => `<span class="${state.resources[r] < n ? 'lack' : ''}">${n} ${RESOURCE_META[r].name.slice(0, 4)}</span>`).join('');
      return `<button class="build-card ${locked ? 'locked' : ''} ${active ? 'active' : ''}" ${locked ? 'disabled' : ''} data-action="build" data-type="${id}" title="${esc(d.desc)}">
        ${d.requires ? `<span class="b-key">${esc(RESEARCH[d.requires].name.split(' ')[0])}</span>` : ''}
        <span class="b-icon">${d.icon}</span>
        <div class="b-name">${esc(d.name)}</div>
        <div class="b-cost">${locked ? `<span style="color:#8d7c61">Requires ${esc(RESEARCH[d.requires].name)}</span>` : cost}</div>
        ${!locked && !afford ? '<div class="b-lock">Materials lacking</div>' : ''}
      </button>`;
    }).join('');
    return `
      <div class="section-head"><h3>Build</h3><span class="rule"></span><span class="count">${Object.keys(BUILDINGS).length}</span></div>
      <p class="section-sub">Choose a structure, then click the map to place its blueprint. Colonists with <b>Construct</b> priority will raise it. Right-click or <b>Esc</b> cancels.</p>
      <div class="build-toolbar">${cats.map(c => `<button class="chip-btn ${c === cat ? 'active' : ''}" data-action="build-category" data-cat="${c}">${c}</button>`).join('')}</div>
      <div class="build-grid">${cards}</div>
      <div class="section-head" style="margin-top:16px"><h3>The Ground</h3><span class="rule"></span></div>
      <p class="section-sub">Mark trees, stone, and bushes for gathering by clicking them on the map and choosing <b>Mark for harvest</b>. Farms ripen on their own.</p>
      <div class="stat-grid">
        <div class="stat-card"><div class="v">${state.features.filter(f => f.marked).length}</div><div class="k">Marked</div></div>
        <div class="stat-card"><div class="v">${state.buildings.filter(b => !b.complete).length}</div><div class="k">Blueprints</div></div>
        <div class="stat-card"><div class="v">${state.features.filter(f => f.type === 'crystal').length}</div><div class="k">Crystal</div></div>
      </div>
      <button class="panel-btn full" data-action="stop-build" style="margin-top:6px">Cancel placement</button>
    `;
  }

  function leftResearch() {
    const r = RESEARCH[state.researchActive];
    const progress = r ? Math.min(100, state.researchPoints / r.cost * 100) : 100;
    const cards = Object.entries(RESEARCH).map(([id, d]) => {
      const done = state.completedResearch.includes(id);
      const locked = d.requires && !state.completedResearch.includes(d.requires);
      const active = state.researchActive === id;
      return `<button class="research-card ${done ? 'done' : ''} ${!done && active ? 'active' : ''} ${locked ? 'locked' : ''}" ${locked ? 'disabled' : ''} data-action="research" data-id="${id}">
        ${done ? '<span class="done-mark">✦</span>' : ''}
        <h4><span class="r-icon">${d.icon}</span>${esc(d.name)}</h4>
        <p>${esc(d.desc)}</p>
        <div class="r-meta"><span>${locked ? 'Locked · ' + esc(RESEARCH[d.requires].name) : done ? 'Understood' : active ? 'Studying' : d.cost + ' insight'}</span><span>${done ? '✓' : d.requires ? d.requires : 'Foundation'}</span></div>
        ${active && !done ? `<div class="r-prog"><i style="width:${progress}%"></i></div>` : ''}
      </button>`;
    }).join('');
    return `
      <div class="section-head"><h3>Arcana &amp; Craft</h3><span class="rule"></span><span class="count">${state.completedResearch.length}/${Object.keys(RESEARCH).length}</span></div>
      <div class="research-points"><b>${Math.floor(state.researchPoints)}</b><span>accumulated insight</span></div>
      <p class="section-sub">Colonists with <b>Research</b> priority study at a Rune Desk. Deeper truths unlock new structures — and attract older things.</p>
      ${state.researchActive ? `<div class="quest-card" style="border-left-color:var(--gold)"><h4>${esc(RESEARCH[state.researchActive].name)}</h4><p>${esc(RESEARCH[state.researchActive].desc)}</p><div class="r-prog" style="margin-top:8px"><i style="width:${progress}%"></i></div><div class="q-obj"><span>Progress</span><b>${Math.floor(state.researchPoints)} / ${RESEARCH[state.researchActive].cost}</b></div></div>` : '<div class="quest-card"><h4>No active study</h4><p>Choose a project below. Insight accumulates even while another project is selected.</p></div>'}
      <div class="section-head" style="margin-top:14px"><h3>Projects</h3><span class="rule"></span></div>
      ${cards}
    `;
  }

  function leftWorld() {
    const exp = state.expedition;
    const expHtml = exp ? `<div class="quest-card" style="border-left-color:var(--blue)">
      <h4>In the field — ${esc(exp.name)}</h4>
      <p>The party is ${Math.round(exp.progress / exp.total * 100)}% through the journey. Supplies are committed.</p>
      <div class="r-prog" style="margin-top:8px"><i style="width:${exp.progress / exp.total * 100}%;background:var(--blue)"></i></div>
      <div class="q-obj"><span>Risk ${exp.risk}</span><b>Day ${state.time.day}</b></div></div>` : '';
    const expActions = EXPEDITIONS.map(e => {
      const locked = e.requires === 'barrow' && !state.quests.find(q => q.id === 'barrow' && q.status === 'active');
      return `<button class="world-action" ${locked ? 'disabled style="opacity:.42;cursor:not-allowed"' : ''} data-action="expedition" data-id="${e.id}">
        <div><div class="wa-name">${esc(e.name)}</div><div class="wa-sub">${locked ? 'Landmark not yet discovered' : esc(e.desc)}</div></div>
        <div class="wa-cost">${locked ? '???' : Object.entries(e.cost).map(([r, n]) => `${n} ${RESOURCE_META[r].name.slice(0, 4)}`).join('<br>')}</div>
      </button>`;
    }).join('');
    return `
      <div class="section-head"><h3>The Marches</h3><span class="rule"></span><span class="count">Open world</span></div>
      <p class="section-sub">Beyond the fire, landmarks wait. Expeditions cost supplies and time; the Marches rarely give something for nothing.</p>
      ${expHtml}
      <div class="section-head"><h3>Quests</h3><span class="rule"></span></div>
      <div class="quests">${state.quests.map(q => `<div class="quest-card ${q.status === 'complete' ? 'done' : ''}">
        <h4>${esc(q.title)}</h4><p>${esc(q.desc)}</p>
        <div class="q-obj"><span>${esc(q.objective)}</span><b>${q.progress} / ${q.total}${q.status === 'complete' ? ' · Done' : ''}</b></div>
        ${q.status === 'active' ? `<div class="r-prog" style="margin-top:5px"><i style="width:${q.progress / q.total * 100}%"></i></div>` : ''}
      </div>`).join('')}</div>
      <div class="section-head" style="margin-top:14px"><h3>Expeditions</h3><span class="rule"></span></div>
      <div class="world-actions">${expActions}</div>
      <button class="panel-btn full" style="margin-top:10px" data-action="open-overview">Open the Sundered Marches map</button>
      <div class="section-head" style="margin-top:16px"><h3>Field Notes</h3><span class="rule"></span></div>
      <div class="log-list">${state.log.slice(0, 6).map(e => `<div class="log-entry ${e.kind}"><span class="lt">${esc(e.t)}</span><span class="ld">${e.icon || '·'}</span><span>${e.text}</span></div>`).join('')}</div>
    `;
  }

  function renderRight() {
    scrollRight = rightContent.scrollTop;
    const entity = selectedEntity(state);
    let html = '';
    if (state.selected?.kind === 'feature') {
      const f = state.features.find(v => v.id === state.selected.id);
      if (f) html = inspectorFeature(f);
    } else if (state.selected?.kind === 'colonist' && entity) {
      html = inspectorColonist(entity);
    } else if (state.selected?.kind === 'building' && entity) {
      html = inspectorBuilding(entity);
    } else if (state.selected?.kind === 'enemy' && entity) {
      html = inspectorEnemy(entity);
    } else {
      html = inspectorOverview();
    }
    if (html === lastRight) return;
    lastRight = html;
    rightContent.innerHTML = html;
    rightContent.scrollTop = scrollRight;
  }

  function inspectorColonist(c) {
    const cls = CLASSES[c.cls], race = RACES[c.race];
    if (c.dead) {
      return `<div class="inspector-head"><div class="avatar" style="background:#2c2520">†</div><div><h3>${esc(c.name)}</h3><div class="sub" style="color:#a46a5e">Fallen</div></div></div>
      <p class="section-sub">A place at the fire remains empty. Their name is carved into the waystone.</p>`;
    }
    const traitHtml = c.traits.map(t => `<span class="tag ${TRAITS[t]?.good ? 'good' : 'bad'}" title="${esc(TRAITS[t]?.desc || '')}">${esc(TRAITS[t]?.name || t)}</span>`).join('');
    return `
      <div class="inspector-head">
        <div class="avatar" style="background:linear-gradient(145deg,${cls.color},#1a1510);font-size:22px">${esc(c.first[0])}</div>
        <div><h3>${esc(c.name)}</h3><div class="sub">${race.name} · ${cls.name} · Lv.${c.level}</div>
        <div class="inspector-tags">${c.onExpedition ? '<span class="tag">In the field</span>' : ''}${c.downed ? '<span class="tag bad">Downed</span>' : ''}${traitHtml}</div></div>
      </div>
      <div class="vitals">
        <div class="vital-row"><span class="vk">Health</span><div class="vbar ${c.hp < c.maxHp * .35 ? 'low' : ''}"><i style="width:${pct(c.hp / c.maxHp * 100)}%"></i></div><span class="vv">${Math.round(c.hp)}</span></div>
        <div class="vital-row"><span class="vk">Hunger</span><div class="vbar hunger ${c.hunger < 30 ? 'low' : ''}"><i style="width:${pct(c.hunger)}%"></i></div><span class="vv">${Math.round(c.hunger)}</span></div>
        <div class="vital-row"><span class="vk">Rest</span><div class="vbar rest ${c.rest < 25 ? 'low' : ''}"><i style="width:${pct(c.rest)}%"></i></div><span class="vv">${Math.round(c.rest)}</span></div>
        <div class="vital-row"><span class="vk">Spirit</span><div class="vbar mood ${c.mood < 30 ? 'low' : ''}"><i style="width:${pct(c.mood)}%"></i></div><span class="vv">${Math.round(c.mood)}</span></div>
      </div>
      <div class="trait-line"><b>${esc(c.status || 'Idle')}.</b> ${esc(c.thought)}</div>
      <div class="micro-label">Skills</div>
      <div class="skill-grid">
        ${SKILLS.map(s => `<div class="skill-row" title="${s.name} ${c.skills[s.id].toFixed(1)}"><span>${s.name}</span><div class="pips">${Array.from({ length: 10 }, (_, i) => `<i class="${i < Math.round(c.skills[s.id]) ? 'on' : ''}"></i>`).join('')}</div><b>${Math.round(c.skills[s.id])}</b></div>`).join('')}
      </div>
      <div class="micro-label">Current Labour</div>
      <div class="trait-line" style="margin-bottom:8px">${c.job ? `${esc(c.job.label || jobLabel(c.job))}${c.job.phase === 'working' && c.job.duration ? ` · ${Math.round(Math.min(1, c.job.progress / c.job.duration) * 100)}%` : ''}` : c.onExpedition ? 'Traveling the Marches' : 'Awaiting orders'}</div>
      <div class="micro-label">Bonds &amp; Burdens</div>
      <div class="trait-line" style="padding-top:2px;padding-bottom:2px">${c.traits.map(t => `<div style="margin:3px 0"><b>${esc(TRAITS[t]?.name || t)}</b> — ${esc(TRAITS[t]?.desc || '')}</div>`).join('')}</div>
      <div class="building-actions">
        <button class="panel-btn" data-action="focus-colonist" data-id="${c.id}">Locate</button>
        <button class="panel-btn" data-action="toggle-priority" data-cid="${c.id}" data-work="guard">${(c.priorities.guard < 4) ? 'Hold Fire' : 'Take Up Arms'}</button>
        <button class="panel-btn" data-action="rest-colonist" data-id="${c.id}">Rest</button>
      </div>
      <button class="panel-btn full" style="margin-top:5px" data-action="open-char" data-id="${c.id}">View character sheet</button>
      <div style="height:6px"></div>
    `;
  }

  function jobLabel(job) {
    return job.type === 'fight' ? 'Defending' : job.type === 'sleep' ? 'Sleeping' : job.type === 'eat' ? 'Eating' : job.label || job.type;
  }

  function inspectorBuilding(b) {
    const d = BUILDINGS[b.type];
    const complete = b.complete;
    const crop = b.crop ?? null;
    const tags = (d.tags || []).map(t => `<span class="tag">${esc(t)}</span>`).join('');
    return `
      <div class="inspector-head">
        <div class="avatar" style="background:linear-gradient(145deg,#4a3b27,#1a1510);font-size:22px">${d.icon}</div>
        <div><h3>${esc(d.name)}</h3><div class="sub" style="color:${complete ? 'var(--gold)' : '#a9895a'}">${complete ? 'Completed' : 'Blueprint'}</div>
        <div class="inspector-tags">${tags}</div></div>
      </div>
      <p class="section-sub" style="margin-top:0">${esc(d.desc)}</p>
      ${!complete ? `<div class="trait-line"><b>Construction ${Math.round(b.progress || 0)}%</b><div class="r-prog" style="margin-top:5px"><i style="width:${b.progress || 0}%"></i></div></div>` : ''}
      ${complete && b.type === 'farm' ? `<div class="vital-row"><span class="vk">Crop</span><div class="vbar"><i style="width:${(crop || 0) * 100}%"></i></div><span class="vv">${Math.round((crop || 0) * 100)}%</span></div>` : ''}
      <div class="colony-meters">
        <div class="colony-meter"><span>Footprint</span><div class="cm-bar"><i style="width:${Math.min(100, b.w * b.h / 4 * 100)}%"></i></div><b>${b.w}×${b.h}</b></div>
        <div class="colony-meter"><span>Materials</span><div class="cm-bar"><i style="width:${Math.min(100, Object.values(d.cost).reduce((a, b) => a + b, 0) / 25 * 100)}%"></i></div><b>${Object.values(d.cost).reduce((a, n) => a + n, 0)}</b></div>
      </div>
      <div class="micro-label">Construction Cost</div>
      <div class="trait-line">${Object.entries(d.cost).map(([r, n]) => `${n} ${RESOURCE_META[r].name}`).join(' · ')}</div>
      <div class="building-actions">
        ${!complete ? `<button class="panel-btn danger" data-action="cancel-building" data-id="${b.id}">Cancel blueprint</button>` : `<button class="panel-btn" data-action="focus-building" data-id="${b.id}">Locate</button><button class="panel-btn" data-action="toggle-building" data-id="${b.id}">${b.active ? 'Switch off' : 'Switch on'}</button><button class="panel-btn danger" data-action="deconstruct" data-id="${b.id}">Deconstruct</button>`}
      </div>
      <div style="height:6px"></div>
    `;
  }

  function inspectorEnemy(e) {
    const info = ENEMY_TYPES[e.type];
    return `
      <div class="inspector-head">
        <div class="avatar" style="background:linear-gradient(145deg,#792f25,#1a1010);font-size:20px">☠</div>
        <div><h3>${esc(e.name)}</h3><div class="sub" style="color:#c77d6b">Hostile · CR ${Math.max(1, Math.round(e.maxHp / 20))}</div>
        <div class="inspector-tags"><span class="tag bad">Threat</span><span class="tag">${e.shape}</span></div></div>
      </div>
      <div class="vitals">
        <div class="vital-row"><span class="vk">Health</span><div class="vbar"><i style="width:${pct(e.hp / e.maxHp * 100)}%;background:linear-gradient(90deg,#6e2a22,#b35243)"></i></div><span class="vv">${Math.round(e.hp)}</span></div>
      </div>
      <p class="section-sub">A creature of the wild Marches. It will kill your people if it can. Ranged colonists engage at distance; guardians hold the line.</p>
      <div class="micro-label">Drops</div>
      <div class="trait-line">${Object.entries(info.loot).map(([r, n]) => `${n} ${RESOURCE_META[r].name}`).join(' · ')}</div>
      <button class="panel-btn full" data-action="focus-enemy" data-id="${e.id}">Track creature</button>
    `;
  }

  function inspectorFeature(f) {
    const names = { tree: 'Old Timber', rock: 'Stone Outcrop', bush: 'Berry Bush', crystal: 'Vein of Crystal', ruinStone: 'Fallen Masonry', grave: 'Grave', waystone: 'Broken Waystone' };
    const icons = { tree: '♣', rock: '▲', bush: '❦', crystal: '◈', ruinStone: '▥', grave: '†', waystone: '✦' };
    return `
      <div class="inspector-head">
        <div class="avatar" style="background:linear-gradient(145deg,#445236,#1a1510);font-size:22px">${icons[f.type] || '·'}</div>
        <div><h3>${esc(names[f.type] || f.type)}</h3><div class="sub">${f.marked ? 'Marked for harvest' : 'Wild resource'}</div></div>
      </div>
      <div class="colony-meters">
        <div class="colony-meter"><span>Remaining</span><div class="cm-bar"><i style="width:${f.amount / f.max * 100}%"></i></div><b>${Math.floor(f.amount)}</b></div>
      </div>
      <p class="section-sub">Marked resources are gathered by colonists with the matching work priority. Trees yield wood; outcrops yield stone; bushes yield food.</p>
      <button class="panel-btn full" data-action="mark-feature" data-id="${f.id}">${f.marked ? 'Unmark resource' : 'Mark for harvest'}</button>
      ${f.type === 'waystone' ? '<p class="section-sub" style="margin-top:10px">It hums when the sun goes down. The Sunken Shrine calls from the east.</p>' : ''}
    `;
  }

  function inspectorOverview() {
    const alive = state.colonists.filter(c => !c.dead);
    const beds = state.buildings.filter(b => b.type === 'bed' && b.complete).length;
    const farms = state.buildings.filter(b => b.type === 'farm' && b.complete).length;
    const armed = alive.filter(c => (c.priorities.guard || 4) < 4).length;
    const threat = state.enemies.filter(e => !e.dead).length;
    return `
      <div class="empty-inspector">
        <div class="glyph">◈</div>
        <h3>Ashenreach</h3>
        <p>Select a colonist, structure, or creature to inspect it. Click the ground to clear your selection.</p>
      </div>
      <div class="section-head"><h3>Colony Ledger</h3><span class="rule"></span></div>
      <div class="colony-meters">
        <div class="colony-meter"><span>Spirit</span><div class="cm-bar"><i style="width:${state.mood}%;background:${state.mood > 50 ? 'var(--moss)' : '#a46a5e'}"></i></div><b>${Math.round(state.mood)}</b></div>
        <div class="colony-meter"><span>Shelter</span><div class="cm-bar"><i style="width:${Math.min(100, beds / Math.max(1, alive.length) * 100)}%"></i></div><b>${beds}/${alive.length}</b></div>
        <div class="colony-meter"><span>Defense</span><div class="cm-bar"><i style="width:${Math.min(100, armed / Math.max(1, alive.length) * 100)}%;background:#a46a5e"></i></div><b>${armed}</b></div>
        <div class="colony-meter"><span>Farms</span><div class="cm-bar"><i style="width:${Math.min(100, farms / 8 * 100)}%;background:#96a36a"></i></div><b>${farms}</b></div>
      </div>
      <div class="stat-grid">
        <div class="stat-card"><div class="v">${alive.length}</div><div class="k">Souls</div></div>
        <div class="stat-card"><div class="v">${threat}</div><div class="k">Threats</div></div>
        <div class="stat-card"><div class="v">${state.stats.daysSurvived}</div><div class="k">Days</div></div>
      </div>
      ${threat ? `<div class="quest-card" style="border-left-color:var(--blood)"><h4 style="color:#d39080">The camp is under attack</h4><p>${threat} hostile${threat > 1 ? 's are' : ' is'} inside the Marches. Colonists with Guard priority will engage. Select the wounded to check them.</p></div>` : ''}
      <div class="section-head" style="margin-top:14px"><h3>Ongoing</h3><span class="rule"></span></div>
      ${state.quests.filter(q => q.status === 'active').slice(0, 2).map(q => `<div class="quest-card"><h4>${esc(q.title)}</h4><p>${esc(q.desc)}</p><div class="q-obj"><span>${esc(q.objective)}</span><b>${q.progress} / ${q.total}</b></div></div>`).join('') || '<p class="section-sub">No active quests. The Marches are quiet. That is rarely good.</p>'}
      <div class="section-head" style="margin-top:12px"><h3>Time &amp; Weather</h3><span class="rule"></span></div>
      <div class="trait-line">${dateLabel(state.time)}, ${timeLabel(state.time.hour)}. ${phaseForHour(state.time.hour)}. ${esc(state.time.weather)}. ${esc(SEASONS[state.time.season].name)} is on the land.</div>
      <button class="panel-btn full" data-action="open-help" style="margin-top:4px">How to play</button>
      <div style="height:8px"></div>
    `;
  }

  function renderToasts() {
    const stack = $('#toast-stack');
    for (const n of state.notifications) {
      if (seenToasts.has(n.id)) continue;
      seenToasts.add(n.id);
      const el = document.createElement('div');
      el.className = 'toast ' + (n.kind || '');
      el.innerHTML = n.text;
      stack.appendChild(el);
      setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 320); }, 4600);
      while (stack.children.length > 4) stack.firstChild.remove();
    }
    for (const id of seenToasts) if (!state.notifications.some(n => n.id === id)) seenToasts.delete(id);
  }

  function renderBanner() {
    const el = $('#event-banner');
    if (state.banner) {
      const key = state.banner.title + state.banner.text;
      if (lastBanner !== key) {
        lastBanner = key;
        el.innerHTML = `<div class="eb-kicker">${esc(state.banner.kicker)}</div><h3>${esc(state.banner.title)}</h3><p>${esc(state.banner.text)}</p>`;
        el.classList.remove('hidden');
        clearTimeout(bannerTimer);
        bannerTimer = setTimeout(() => el.classList.add('hidden'), Math.max(1600, state.banner.ttl * 1000));
      }
    } else if (lastBanner !== null) {
      lastBanner = null;
      el.classList.add('hidden');
    }
  }

  function renderBottom() {
    const st = getStatus(state);
    const armed = state.colonists.filter(c => !c.dead && (c.priorities.guard || 4) < 4).length;
    $('#bottom-stats').innerHTML = `<span>Colonists <b>${st.alive}</b></span><span>Defenders <b>${armed}</b></span><span>Hostiles <b style="color:${st.threat ? '#d39080' : 'var(--parch)'}">${st.threat}</b></span><span>Speed <b>${state.speed === 0 ? 'Paused' : state.speed + '×'}</b></span>`;
    const recent = state.log[0];
    if (recent) $('#alert-text').innerHTML = recent.text.replace(/<\/?[^>]+>/g, '');
    document.querySelectorAll('.speed-btn').forEach(b => b.classList.toggle('active', Number(b.dataset.speed) === state.speed));
    document.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t.dataset.tab === state.uiTab));
  }

  function renderAll() {
    renderResources();
    renderChrono();
    renderLeft();
    renderRight();
    renderBottom();
  }

  function tick() {
    renderChrono();
    renderResources();
    renderBottom();
    renderBanner();
    renderToasts();
    if (state.dirty) {
      renderLeft();
      renderRight();
      state.dirty = false;
    }
  }

  function showModal(html) {
    $('#modal-content').innerHTML = html;
    $('#modal-layer').classList.remove('hidden');
  }

  function closeModal() {
    $('#modal-layer').classList.add('hidden');
  }

  function helpModal() {
    showModal(`
      <div class="m-kicker">Field Manual · Ashenreach</div>
      <h2>How to Keep the Fire</h2>
      <p>Ashenreach is a colony chronicle. You do not control every step — you set priorities, mark work, raise walls, and hope. Time passes when you let it.</p>
      <div class="rules">
        <div class="rule"><b>1. The map</b>Drag with the right mouse to pan; scroll to zoom. Click colonists, creatures, or structures to inspect them.</div>
        <div class="rule"><b>2. Work</b>Open Work and set each colonist’s priorities. Idle colonists choose tasks by priority, distance, and skill.</div>
        <div class="rule"><b>3. Build</b>Choose a structure in Build, then click the map. Blueprints need materials and a free colonist.</div>
        <div class="rule"><b>4. Gather</b>Click a tree, outcrop, or bush and mark it. Colonists with Chop/Mine/Harvest priorities bring resources home.</div>
        <div class="rule"><b>5. Needs</b>Hunger, rest, and spirit matter. Meals are better than raw food. Beds, fire, wells, and shrines lift morale.</div>
        <div class="rule"><b>6. Danger</b>Raiders spawn at the edges. Defenders fight automatically; wounded colonists need a doctor or a bed.</div>
        <div class="rule"><b>7. Explore</b>Use the World tab to send parties to landmarks. Expeditions cost supplies and time, and return with stories.</div>
        <div class="rule"><b>8. Arcana</b>Research unlocks new structures. Build a Rune Desk and assign a scholar.</div>
      </div>
      <div class="m-actions"><button data-action="close-modal">Return to the Marches</button><button data-action="restart">New chronicle</button></div>
    `);
  }

  function menuModal() {
    showModal(`
      <div class="m-kicker">Chronicle Menu</div>
      <h2>Ashenreach</h2>
      <p>A small fire against a very large dark. Your story is being written in the Chronicle.</p>
      <ul class="m-list">
        <li><span>Colonists</span><b>${state.colonists.filter(c => !c.dead).length}</b></li>
        <li><span>Day / season</span><b>${state.stats.daysSurvived} · ${SEASONS[state.time.season].name}</b></li>
        <li><span>Structures raised</span><b>${state.stats.built}</b></li>
        <li><span>Creatures slain</span><b>${state.stats.kills}</b></li>
        <li><span>Insight discovered</span><b>${state.completedResearch.length} projects</b></li>
        <li><span>World seed</span><b>${state.seed}</b></li>
      </ul>
      <div class="m-actions"><button data-action="close-modal">Continue</button><button data-action="open-help">Field manual</button><button data-action="restart">New chronicle</button></div>
    `);
  }

  function charModal(c) {
    if (!c) return;
    showModal(`
      <div class="m-kicker">${esc(RACES[c.race].name)} · ${esc(CLASSES[c.cls].name)}</div>
      <h2>${esc(c.name)}</h2>
      <p>${esc(c.thought)}</p>
      <div class="m-list">
        ${SKILLS.map(s => `<li><span>${s.name}</span><b>${c.skills[s.id].toFixed(1)} / 10</b></li>`).join('')}
        <li><span>Traits</span><b>${c.traits.map(t => TRAITS[t]?.name || t).join(', ')}</b></li>
        <li><span>Health</span><b>${Math.round(c.hp)} / ${c.maxHp}</b></li>
        <li><span>Mood</span><b>${Math.round(c.mood)}</b></li>
      </div>
      <div class="m-actions"><button data-action="close-modal">Close</button></div>
    `);
  }

  function bind() {
    document.addEventListener('click', e => {
      const btn = e.target.closest('[data-action]');
      if (!btn || btn.disabled) return;
      const action = btn.dataset.action;
      const id = btn.dataset.id;
      if (action === 'tab') { state.uiTab = btn.dataset.tab; state.dirty = true; lastLeft = ''; renderLeft(true); renderBottom(); }
      else if (action === 'select-colonist') actions.select('colonist', id);
      else if (action === 'build') actions.build(btn.dataset.type);
      else if (action === 'build-category') { state.buildCategory = btn.dataset.cat; state.dirty = true; lastLeft = ''; renderLeft(true); }
      else if (action === 'priority') {
        const v = Number(btn.dataset.val);
        actions.priority(btn.dataset.cid, btn.dataset.work, v >= 4 ? 1 : v + 1);
      }
      else if (action === 'research') actions.research(id);
      else if (action === 'expedition') actions.expedition(id);
      else if (action === 'stop-build') actions.stopBuild();
      else if (action === 'mark-feature') actions.markFeature(id);
      else if (action === 'cancel-building') actions.cancelBuilding(id);
      else if (action === 'deconstruct') actions.deconstruct(id);
      else if (action === 'toggle-building') actions.toggleBuilding(id);
      else if (action === 'focus-colonist') actions.focus('colonist', id);
      else if (action === 'focus-building') actions.focus('building', id);
      else if (action === 'focus-enemy') actions.focus('enemy', id);
      else if (action === 'rest-colonist') actions.rest(id);
      else if (action === 'toggle-priority') actions.togglePriority(btn.dataset.cid, btn.dataset.work);
      else if (action === 'open-help') helpModal();
      else if (action === 'open-char') charModal(state.colonists.find(c => c.id === id));
      else if (action === 'open-overview') actions.openOverview();
      else if (action === 'close-modal') closeModal();
      else if (action === 'restart') actions.restart();
      else if (action === 'speed') actions.speed(Number(btn.dataset.speed));
    });
    document.querySelectorAll('.tab').forEach(t => t.addEventListener('click', () => {
      state.uiTab = t.dataset.tab; state.dirty = true; lastLeft = ''; renderLeft(true); renderBottom();
    }));
    document.querySelectorAll('.speed-btn').forEach(b => b.addEventListener('click', () => actions.speed(Number(b.dataset.speed))));
    $('#modal-close').addEventListener('click', closeModal);
    $('#modal-layer').addEventListener('click', e => { if (e.target.id === 'modal-layer') closeModal(); });
    $('#btn-help').addEventListener('click', helpModal);
    $('#btn-menu').addEventListener('click', menuModal);
    $('#btn-minimap').addEventListener('click', () => actions.openOverview());
    $('#overview-close').addEventListener('click', () => actions.closeOverview());
  }

  return { bind, tick, renderAll, renderLeft, renderRight, showModal, closeModal, helpModal, menuModal, charModal, forceLeft: () => renderLeft(true), forceRight: () => renderRight() };
}

export function renderStartDetails() {}

import './style.css';
import { BUILDINGS, RESOURCE_META } from './content.js';
import { createGame, logEvent, placeBuilding, select, setPriority, setResearch, setSpeed, simulate, spawnParticles, startExpedition, addResource, notify } from './sim.js';
import { createRenderer, drawOverview } from './render.js';
import { createUI } from './ui.js';
import { key } from './world.js';

const state = createGame(732);
state.speed = 0;
state.prevSpeed = 1;

const canvas = document.getElementById('world');
const renderer = createRenderer(canvas, state);
const ui = createUI(state, actions);

let started = false;
let overviewOpen = false;
let lastUI = 0;
let lastOverview = 0;
let hoverFeature = null;
let pointers = new Map();
let panPointer = null;
let panStart = null;
let panCam = null;
let pinchState = null;

const actions = {
  select(kind, id) {
    select(state, kind, id);
  },
  build(type) {
    const def = BUILDINGS[type];
    if (!def) return;
    state.buildMode = { type };
    state.uiTab = 'build';
    state.dirty = true;
    ui.forceLeft();
    ui.forceRight();
    renderer.cam.targetZoom = Math.max(renderer.cam.targetZoom, 1.05);
  },
  stopBuild() {
    state.buildMode = null;
    state.placeCheck = null;
    state.dirty = true;
  },
  priority(cid, work, val) {
    setPriority(state, cid, work, val);
    ui.forceLeft();
  },
  research(id) {
    setResearch(state, id);
    ui.forceLeft();
  },
  expedition(id) {
    startExpedition(state, id);
    state.uiTab = 'world';
    state.dirty = true;
    ui.forceLeft();
  },
  markFeature(id) {
    const f = state.features.find(v => v.id === id);
    if (!f) return;
    f.marked = !f.marked;
    state.dirty = true;
    ui.forceRight();
    notify(state, `${f.type === 'tree' ? 'Timber' : f.type === 'rock' ? 'Stone' : f.type === 'crystal' ? 'Crystal' : 'Foraging'} ${f.marked ? 'marked for harvest.' : 'unmarked.'}`, '');
  },
  cancelBuilding(id) {
    const b = state.buildings.find(v => v.id === id);
    if (!b) return;
    if (b.complete) return;
    const def = BUILDINGS[b.type];
    for (const [r, n] of Object.entries(def.cost)) addResource(state, r, Math.floor(n / 2), true);
    state.buildings = state.buildings.filter(v => v.id !== id);
    state.selected = null;
    logEvent(state, `Cancelled ${def.name}. Half the materials recovered.`, '⌫');
    state.dirty = true;
    ui.forceRight();
  },
  deconstruct(id) {
    const b = state.buildings.find(v => v.id === id);
    if (!b || !b.complete) return;
    const def = BUILDINGS[b.type];
    for (const [r, n] of Object.entries(def.cost)) addResource(state, r, Math.max(1, Math.floor(n * .5)), true);
    state.buildings = state.buildings.filter(v => v.id !== id);
    spawnParticles(state, b.x + b.w / 2, b.y + b.h / 2, 12, ['#a78b62', '#6b5a43', '#e6d4ae'], { speed: 1, life: .7, size: 1.5 });
    state.selected = null;
    logEvent(state, `${def.name} deconstructed. Half the materials recovered.`, '⌫', '');
    state.dirty = true;
    ui.forceRight();
    ui.forceLeft();
  },
  toggleBuilding(id) {
    const b = state.buildings.find(v => v.id === id);
    if (!b) return;
    b.active = !b.active;
    notify(state, `${BUILDINGS[b.type].name} switched ${b.active ? 'on' : 'off'}.`, '');
    state.dirty = true;
    ui.forceRight();
  },
  focus(kind, id) {
    const entity = kind === 'colonist' ? state.colonists.find(c => c.id === id) : kind === 'enemy' ? state.enemies.find(e => e.id === id) : state.buildings.find(b => b.id === id);
    if (!entity) return;
    select(state, kind, id);
    renderer.centerOn(kind === 'building' ? entity.x + (entity.w || 1) / 2 : entity.x, kind === 'building' ? entity.y + (entity.h || 1) / 2 : entity.y);
    if (kind === 'enemy') renderer.cam.targetZoom = Math.max(renderer.cam.targetZoom, 1.25);
  },
  rest(id) {
    const c = state.colonists.find(v => v.id === id);
    if (!c) return;
    c.job = null;
    c.path = [];
    c.rest = Math.min(c.rest, 4);
    notify(state, `${c.first} has been ordered to rest.`, '');
    state.dirty = true;
  },
  togglePriority(cid, work) {
    const c = state.colonists.find(v => v.id === cid);
    if (!c) return;
    c.priorities[work] = (c.priorities[work] || 4) < 4 ? 4 : 3;
    if (c.priorities[work] === 4 && c.job?.type === 'fight') c.job = null;
    state.dirty = true;
    ui.forceRight();
  },
  openOverview() {
    overviewOpen = true;
    document.getElementById('overview').classList.remove('hidden');
    drawOverview(document.getElementById('overview-canvas'), state);
  },
  closeOverview() {
    overviewOpen = false;
    document.getElementById('overview').classList.add('hidden');
  },
  speed(n) {
    setSpeed(state, n);
    document.querySelectorAll('.speed-btn').forEach(b => b.classList.toggle('active', Number(b.dataset.speed) === n));
  },
  restart() {
    window.location.reload();
  },
};

ui.bind();
ui.renderAll();

/* ------------------------------------------------------------------ input */
function tileFromEvent(e) {
  return renderer.screenToWorld(e.clientX, e.clientY);
}

function updateHover(e) {
  const w = tileFromEvent(e);
  const tx = Math.floor(w.x), ty = Math.floor(w.y);
  state.hover = { x: tx, y: ty };
  if (state.buildMode) {
    const def = BUILDINGS[state.buildMode.type];
    const check = canPlaceSafe(state.buildMode.type, tx, ty);
    state.placeCheck = check;
  } else {
    state.placeCheck = null;
  }
  const f = state.featureIndex.get(key(tx, ty)) || null;
  hoverFeature = f;
  const tooltip = document.getElementById('tooltip');
  if (f && !state.buildMode) {
    const names = { tree: 'Old Timber', rock: 'Stone Outcrop', bush: 'Berry Bush', crystal: 'Crystal Vein', ruinStone: 'Fallen Masonry', grave: 'Grave', waystone: 'Broken Waystone' };
    tooltip.innerHTML = `<b>${names[f.type] || f.type}</b> · ${Math.floor(f.amount)} ${f.type === 'tree' ? 'wood' : f.type === 'crystal' ? 'crystal' : f.type === 'bush' ? 'food' : 'stone'}${f.marked ? ' · marked' : ''}`;
    tooltip.style.left = `${Math.min(window.innerWidth - 230, e.clientX + 14)}px`;
    tooltip.style.top = `${Math.max(84, e.clientY - 30)}px`;
    tooltip.classList.remove('hidden');
  } else {
    tooltip.classList.add('hidden');
  }
}

function canPlaceSafe(type, x, y) {
  try {
    const mod = import.meta;
    return canPlaceLocal(type, x, y);
  } catch { return { ok: false, reason: 'Cannot place here.' }; }
}

function canPlaceLocal(type, x, y) {
  const def = BUILDINGS[type];
  const { TERRAIN_INFO } = window.__content || {};
  // Local mirror to avoid circular UI -> sim import at input time.
  if (!def) return { ok: false };
  for (let yy = 0; yy < def.h; yy++) {
    for (let xx = 0; xx < def.w; xx++) {
      const tx = x + xx, ty = y + yy;
      if (tx < 0 || ty < 0 || tx >= state.world.w || ty >= state.world.h) return { ok: false, reason: 'Beyond the map.' };
      const terr = state.world.tiles[ty * state.world.w + tx];
      if (terr === 3 || terr === 4) return { ok: false, reason: 'Unbuildable ground.' };
      if (state.featureIndex.get(key(tx, ty))) return { ok: false, reason: 'Something already occupies this ground.' };
      if (state.buildings.some(b => tx >= b.x && tx < b.x + b.w && ty >= b.y && ty < b.y + b.h)) return { ok: false, reason: 'Structure overlap.' };
    }
  }
  return { ok: true };
}

function handleMapClick(clientX, clientY) {
  const world = renderer.screenToWorld(clientX, clientY);
  const tx = Math.floor(world.x), ty = Math.floor(world.y);
  if (state.buildMode) {
    const ok = placeBuilding(state, state.buildMode.type, tx, ty);
    if (ok) {
      state.dirty = true;
      ui.forceLeft();
    }
    return;
  }
  // Enemy nearest.
  let best = null, bd = .8;
  for (const en of state.enemies) {
    if (en.dead) continue;
    const d = Math.hypot(en.x - world.x, en.y - world.y);
    if (d < bd) { bd = d; best = en; }
  }
  if (best) { select(state, 'enemy', best.id); return; }
  // Colonist nearest.
  best = null; bd = .65;
  for (const c of state.colonists) {
    if (c.dead || c.onExpedition) continue;
    const d = Math.hypot(c.x - world.x, c.y - world.y);
    if (d < bd) { bd = d; best = c; }
  }
  if (best) { select(state, 'colonist', best.id); return; }
  // Building.
  const b = state.buildings.find(v => tx >= v.x && tx < v.x + v.w && ty >= v.y && ty < v.y + v.h);
  if (b) { select(state, 'building', b.id); return; }
  // Feature.
  const f = state.featureIndex.get(key(tx, ty));
  if (f) { select(state, 'feature', f.id); return; }
  select(state, null, null);
}

canvas.addEventListener('pointerdown', e => {
  if (!started) return;
  const p = { x: e.clientX, y: e.clientY, type: e.pointerType };
  pointers.set(e.pointerId, p);
  canvas.setPointerCapture?.(e.pointerId);
  if (pointers.size === 2) {
    const pts = [...pointers.values()];
    pinchState = { dist: Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y), zoom: renderer.cam.targetZoom };
    panPointer = null;
    return;
  }
  if (e.button === 0 || e.button === 1 || e.button === 2) {
    panPointer = e.pointerId;
    panStart = { x: e.clientX, y: e.clientY };
    panCam = { x: renderer.cam.x, y: renderer.cam.y };
    p.dragged = false;
    p.button = e.button;
  }
});

canvas.addEventListener('pointermove', e => {
  if (!started) return;
  if (!panPointer && !pinchState) updateHover(e);
  const p = pointers.get(e.pointerId);
  if (p) { p.x = e.clientX; p.y = e.clientY; }
  if (pinchState && pointers.size >= 2) {
    const pts = [...pointers.values()];
    const d = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
    const scale = d / pinchState.dist;
    renderer.cam.targetZoom = Math.max(.55, Math.min(2.4, pinchState.zoom * scale));
    return;
  }
  if (panPointer === e.pointerId && panStart) {
    const dx = e.clientX - panStart.x, dy = e.clientY - panStart.y;
    if (Math.hypot(dx, dy) > 5) {
      if (p) p.dragged = true;
      const t = 32 * renderer.cam.zoom;
      renderer.cam.x = Math.max(4, Math.min(state.world.w - 4, panCam.x - dx / t));
      renderer.cam.y = Math.max(4, Math.min(state.world.h - 4, panCam.y - dy / t));
      canvas.style.cursor = 'grabbing';
    }
  }
});

function endPointer(e) {
  const p = pointers.get(e.pointerId);
  pointers.delete(e.pointerId);
  if (pointers.size < 2) pinchState = null;
  if (panPointer === e.pointerId) {
    const moved = p?.dragged;
    const button = p?.button ?? 0;
    panPointer = null;
    panStart = null;
    panCam = null;
    canvas.style.cursor = 'crosshair';
    if (!moved && e.type === 'pointerup') {
      if (e.button === 2) {
        if (state.buildMode) { state.buildMode = null; state.placeCheck = null; state.dirty = true; }
      } else {
        const mm = renderer.minimapHit(e.clientX, e.clientY);
        if (mm) { renderer.centerOn(mm.x + 1, mm.y + .5); return; }
        if (button === 0 || e.pointerType === 'touch') handleMapClick(e.clientX, e.clientY);
      }
    }
  }
}
canvas.addEventListener('pointerup', endPointer);
canvas.addEventListener('pointercancel', e => {
  pointers.delete(e.pointerId);
  if (panPointer === e.pointerId) { panPointer = null; panStart = null; panCam = null; }
  pinchState = null;
});
canvas.addEventListener('pointerleave', e => {
  if (!panPointer) document.getElementById('tooltip').classList.add('hidden');
});
canvas.addEventListener('contextmenu', e => e.preventDefault());
canvas.addEventListener('wheel', e => {
  e.preventDefault();
  renderer.zoomBy(e.deltaY);
}, { passive: false });

window.addEventListener('keydown', e => {
  if (!started) {
    if (e.key === 'Enter' || e.key === ' ') startGame();
    return;
  }
  if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
  if (e.key === 'Escape') {
    if (state.buildMode) { state.buildMode = null; state.placeCheck = null; state.dirty = true; }
    const modal = document.getElementById('modal-layer');
    if (!modal.classList.contains('hidden')) ui.closeModal();
    if (overviewOpen) actions.closeOverview();
  } else if (e.key === ' ') { e.preventDefault(); actions.speed(state.speed === 0 ? state.prevSpeed || 1 : 0); }
  else if (e.key === '1') actions.speed(1);
  else if (e.key === '2') actions.speed(2);
  else if (e.key === '3') actions.speed(3);
  else if (e.key === '0') actions.speed(0);
  else if (e.key === 'b' || e.key === 'B') { state.uiTab = 'build'; state.dirty = true; ui.forceLeft(); }
  else if (e.key === 'w' || e.key === 'W' || e.key === 'ArrowUp') renderer.panBy(0, 90);
  else if (e.key === 's' || e.key === 'S' || e.key === 'ArrowDown') renderer.panBy(0, -90);
  else if (e.key === 'a' || e.key === 'A' || e.key === 'ArrowLeft') renderer.panBy(90, 0);
  else if (e.key === 'd' || e.key === 'D' || e.key === 'ArrowRight') renderer.panBy(-90, 0);
});

window.addEventListener('resize', () => {
  renderer.resize();
  if (overviewOpen) drawOverview(document.getElementById('overview-canvas'), state);
});

/* -------------------------------------------------------------- overview */
const overviewCanvas = document.getElementById('overview-canvas');
overviewCanvas.addEventListener('mousemove', e => {
  if (!overviewOpen) return;
  const rect = overviewCanvas.getBoundingClientRect();
  const x = (e.clientX - rect.left) / rect.width;
  const y = (e.clientY - rect.top) / rect.height;
  const mapW = Math.min(rect.width * .72, state.world.w * 18);
  const mapH = mapW * state.world.h / state.world.w;
  const mx = rect.width / 2 - mapW / 2, my = rect.height / 2 - mapH / 2;
  const wx = (e.clientX - rect.left - mx) / mapW * state.world.w;
  const wy = (e.clientY - rect.top - my) / mapH * state.world.h;
  if (wx >= 0 && wy >= 0 && wx <= state.world.w && wy <= state.world.h) {
    overviewCanvas.style.cursor = 'crosshair';
  } else overviewCanvas.style.cursor = 'default';
});
overviewCanvas.addEventListener('click', e => {
  if (!overviewOpen) return;
  const rect = overviewCanvas.getBoundingClientRect();
  const mapW = Math.min(rect.width * .72, state.world.w * 18);
  const mapH = mapW * state.world.h / state.world.w;
  const mx = rect.width / 2 - mapW / 2, my = rect.height / 2 - mapH / 2;
  const wx = (e.clientX - rect.left - mx) / mapW * state.world.w;
  const wy = (e.clientY - rect.top - my) / mapH * state.world.h;
  if (wx >= 0 && wy >= 0 && wx <= state.world.w && wy <= state.world.h) {
    renderer.centerOn(wx, wy);
    actions.closeOverview();
  }
});

/* ------------------------------------------------------------------- loop */
function startGame() {
  if (started) return;
  started = true;
  state.speed = 1;
  state.prevSpeed = 1;
  state.dirty = true;
  const screen = document.getElementById('start-screen');
  screen.classList.add('dismiss');
  setTimeout(() => { screen.style.display = 'none'; }, 900);
  setTimeout(() => {
    state.dirty = true;
    ui.renderAll();
  }, 120);
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const gain = ctx.createGain();
    gain.gain.value = 0.035;
    gain.connect(ctx.destination);
    const o1 = ctx.createOscillator(); o1.type = 'sine'; o1.frequency.value = 55;
    const o2 = ctx.createOscillator(); o2.type = 'sine'; o2.frequency.value = 82.5;
    const filter = ctx.createBiquadFilter(); filter.type = 'lowpass'; filter.frequency.value = 220;
    o1.connect(filter); o2.connect(filter); filter.connect(gain);
    o1.start(); o2.start();
  } catch { /* no audio is still a story */ }
}

document.getElementById('start-btn').addEventListener('click', startGame);

function frame(now) {
  const dt = Math.min(.1, (now - (frame.last || now)) / 1000);
  frame.last = now;
  if (started) simulate(state, dt);
  renderer.draw(now);
  if (started && now - lastUI > 180) {
    lastUI = now;
    ui.tick();
  }
  if (overviewOpen && now - lastOverview > 450) {
    lastOverview = now;
    drawOverview(document.getElementById('overview-canvas'), state);
  }
  requestAnimationFrame(frame);
}

// Set the initial camera a little above the camp so both panels and the fire read well.
renderer.centerOn(state.world.campX + 1, state.world.campY + .5, true);
requestAnimationFrame(frame);

// Expose for browser verification and debugging, without affecting play.
window.__ashenreach = {
  state,
  renderer,
  start: startGame,
  actions,
  simulate,
  get ui() { return ui; },
};

