    tooltip.innerHTML = `<b>${names[f.type] || f.type}</b> · ${Math.floor(f.amount)} ${f.type === 'tree' ? 'wood' : f.type === 'crystal' ? 'crystal' : f.type === 'bush' ? 'food' : 'stone'}${f.marked ? ' · marked' : ''}`;
