:root {
  --ink: #14100c;
  --ink-2: #1d1711;
  --ink-3: #261e16;
  --panel: rgba(20, 16, 12, .91);
  --panel-soft: rgba(31, 25, 18, .78);
  --parch: #e6d4ae;
  --parch-dim: #ad9c7c;
  --gold: #c9a15c;
  --gold-bright: #e9c987;
  --gold-dim: #7e663d;
  --blood: #9a4134;
  --moss: #73825a;
  --blue: #7a9da3;
  --line: rgba(201, 161, 92, .22);
  --line-soft: rgba(230, 212, 174, .09);
  --shadow: 0 22px 70px rgba(0, 0, 0, .55);
  --serif: Georgia, 'Palatino Linotype', 'Book Antiqua', Palatino, serif;
  --sans: 'Avenir Next', 'Segoe UI', Candara, system-ui, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: #0c0a08; overflow: hidden; }
body { font-family: var(--sans); color: var(--parch); -webkit-font-smoothing: antialiased; user-select: none; }
button { font: inherit; color: inherit; }
button:focus-visible { outline: 1px solid var(--gold-bright); outline-offset: 2px; }
.hidden { display: none !important; }
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: rgba(0,0,0,.16); }
::-webkit-scrollbar-thumb { background: rgba(201,161,92,.28); border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: rgba(201,161,92,.45); }

#app { position: fixed; inset: 0; overflow: hidden; background: #0e120e; }
#world { position: absolute; inset: 0; width: 100%; height: 100%; touch-action: none; cursor: crosshair; }

.map-vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 1;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 42%, rgba(10, 8, 5, .34) 100%),
    linear-gradient(180deg, rgba(8, 6, 4, .62) 0, transparent 16%, transparent 78%, rgba(8, 6, 4, .52) 100%);
}
.map-grain {
  position: absolute; inset: 0; pointer-events: none; z-index: 1; opacity: .055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
}

