    const x0 = Math.max(0, Math.floor(cam.x - W / 2 / t) - 2);
    const y0 = Math.max(0, Math.floor(cam.y - H / 2 / t) - 2);
    const x1 = Math.min(state.world.w, Math.ceil(cam.x + W / 2 / t) + 2);
    const y1 = Math.min(state.world.h, Math.ceil(cam.y + H / 2 / t) + 2);
